window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0112", [{"word":"moisture","ipa_uk":"/ˈmɔɪstʃə/","ipa_us":"/ˈmɔɪstʃər/","definition_zh":"湿气；水分；潮气；含水量","definition_en":"small amounts of water held on a surface, in the air, in soil or inside a material","core_image":"清晨的岩壁上凝着一层看不见的水汽，手指摸上去凉而微湿","scene":"清晨的岩壁上蒙着一层细水汽，摸上去凉凉的。Dew had left a thin film of moisture on the rock face.","sceneCN":"这里该词指「物体表面少量附着的水分」（第 1 个义项：表面的一层薄水）；句意为露水在岩壁上留下了一层薄薄的水汽。","pos":[{"tag":"n.","zh":"湿气；水分；潮气；含水量"}],"collocations":[{"phrase":"moisture content","zh":"含水量；水分含量"},{"phrase":"soil moisture","zh":"土壤水分"},{"phrase":"moisture in the air","zh":"空气中的水汽"},{"phrase":"absorb moisture","zh":"吸收水分"},{"phrase":"retain moisture","zh":"保持水分"},{"phrase":"moisture level","zh":"湿度水平"}],"forms":[{"label":"不可数用法","form":"moisture（通常不可数）"},{"label":"形容词（湿润的）","form":"moist"},{"label":"动词（使湿润）","form":"moisten"},{"label":"名词（湿润）","form":"moistness"},{"label":"复合形容词（防潮的）","form":"moisture-proof"}],"derivatives":[{"word":"moist","pos":"adj.","zh":"微湿的；湿润的"},{"word":"moisten","pos":"v.","zh":"使湿润；沾湿"},{"word":"moistness","pos":"n.","zh":"湿润；潮湿"},{"word":"moisturize","pos":"v.","zh":"给皮肤补充水分"},{"word":"moisturizer","pos":"n.","zh":"保湿霜；润肤品"}],"senses":[{"no":"01","title":"A thin film of water on a surface","titleCN":"物体表面附着的一层薄水","definition":"a small amount of water lying on the surface of an object","definitionCN":"附着在物体表面的一层少量水","example":"Dew had left a thin film of moisture on the rock face.","exampleCN":"露水在岩壁上留下了一层薄薄的水汽。","why":"Moisture never names a body of water; it names water only as something small, held by a surface and waiting to evaporate.","whyCN":"moisture 从不指一片水域，只指被表面挽留、随时会蒸发掉的一点点水。"},{"no":"02","title":"Water vapour held in the air","titleCN":"空气里含有的水汽","definition":"water in the form of vapour that is present in the atmosphere","definitionCN":"以水汽形式存在大气中的水分","example":"The air in the greenhouse keeps enough moisture for the seedlings.","exampleCN":"温室里的空气保持了足够幼苗生长的水汽。","why":"Air can hold water invisibly; when people speak of moisture in the air they mean this invisible load, not rain.","whyCN":"空气能看不见地含水；说空气中的 moisture，指的是这份看不见的含水，而不是下雨。"},{"no":"03","title":"Water stored in soil","titleCN":"土壤中储存的水分","definition":"water held between soil particles and available to plant roots","definitionCN":"保存在土壤颗粒之间、可供根系利用的水","example":"Mulch holds moisture in the soil through the dry months.","exampleCN":"覆盖物在干旱的月份里把水分留在土壤中。","why":"Soil is another surface that can hold small amounts of water, so the same word extends from rock to earth.","whyCN":"土壤也是能挽留少量水的表面，于是同一个词从岩石延伸到土地。"},{"no":"04","title":"Water content of food or material","titleCN":"食物或材料内部的含水量","definition":"the water contained inside a substance such as grain, wood or plaster","definitionCN":"谷物、木材、灰泥等物质内部所含的水","example":"The mill checks the moisture of every sack of grain before milling.","exampleCN":"磨坊在研磨前检查每一袋谷物的含水量。","why":"Here the water is inside, not on the surface, but it is still a measured quantity that the material holds.","whyCN":"这里的水在内部而不在表面，但仍然是材料所持有、可被计量的一份水。"},{"no":"05","title":"Water kept in living skin","titleCN":"皮肤中保住的水分","definition":"the water naturally held in skin or hair, often spoken of in cosmetics","definitionCN":"皮肤或头发中天然保持的水，常见于护肤语境","example":"This cream seals moisture into dry skin.","exampleCN":"这款乳霜把水分锁在干燥的皮肤里。","why":"Living tissue is a moist surface, so its water became the standard subject of the word in skin-care writing.","whyCN":"活体组织本身就是湿润的表面，因此护肤写作把皮肤里的水当成了这个词的固定对象。"},{"no":"06","title":"Condensation on a cold surface","titleCN":"遇冷凝结在表面上的水","definition":"droplets that form when warm damp air meets a cold surface","definitionCN":"暖湿空气遇到冷表面时凝结成的小水珠","example":"Moisture ran down the window in the warm kitchen.","exampleCN":"温暖的厨房里，水汽顺着窗玻璃往下流。","why":"This is the surface film again, but now produced by a temperature difference rather than by dew.","whyCN":"这仍是表面那层水膜，只是成因从露水变成了温差。"},{"no":"07","title":"A measured water ratio","titleCN":"作为仪器读数的含水率","definition":"the percentage of water in a material, measured for engineering or trade","definitionCN":"为工程或交易测定出的材料含水百分比","example":"Engineers record the moisture content of the concrete before pouring.","exampleCN":"工程师在浇筑前记录混凝土的含水率。","why":"Once a value can be weighed and printed, the word turns into a number on a gauge.","whyCN":"一旦这份水能被称量、打印出来，这个词就变成了仪表上的一个数字。"},{"no":"08","title":"Dampness as a building problem","titleCN":"建筑中造成损坏的潮气","definition":"unwanted water inside walls or floors that damages a building","definitionCN":"侵入墙体或地板、造成损坏的多余水分","example":"Moisture in the walls had softened the old plaster.","exampleCN":"墙里的潮气早把旧灰泥泡软了。","why":"The same water that keeps a plant alive ruins plaster; when the holder is a building, the word turns into a fault.","whyCN":"同一份水能养活植物，也能毁掉灰泥；当持有者是房屋时，这个词就变成了一个毛病。"}],"etymology":{"intro":{"en":"The word reached English through Old French, and its deeper Latin source is disputed. Dates are approximate and the contested step is marked.","cn":"这个词经古法语进入英语，更早的拉丁来源存在争议。年代为大致估计，存疑的一环已明确标注。"},"items":[{"era":"OLD FRENCH (c. 1300)","en":"Old French moistour 'moisture, dampness' was formed from moiste 'moist, wet' plus the noun suffix -our, from Latin -ura.","cn":"古法语 moistour「湿气、潮湿」由 moiste「湿的」加名词后缀 -our（出自拉丁 -ura）构成。"},{"era":"MIDDLE ENGLISH (14c)","en":"English borrowed the noun as moisture and used it first for dampness in air, soil and stored goods.","cn":"英语借入为 moisture，最早用于空气、土壤和储存货物中的潮气。"},{"era":"VULGAR LATIN (reconstructed form)","en":"The adjective behind moist is usually reconstructed as Vulgar Latin *muscidus 'mouldy', an altered form of Latin mucidus. This reconstruction is a hypothesis, not a recorded form.","cn":"moist 背后的形容词通常被重构为俗拉丁语 *muscidus「发霉的」，是拉丁语 mucidus 的变形。这一重构只是假说，并非有记录的形式。"},{"era":"CLASSICAL LATIN (alternative hypothesis)","en":"Some scholars instead connect the Romance words to Latin madere 'to be wet' and madidus 'wet'. The two explanations are usually listed side by side; the source of moist is marked as source uncertain.","cn":"也有学者把这一组罗曼语词联系到拉丁语 madere「潮湿」和 madidus「湿的」。两种解释通常并列，moist 的来源不确定。"},{"era":"MODERN ENGLISH (17c–19c)","en":"With the growth of agriculture, food processing and engineering, moisture came to mean a measurable water content rather than only a feeling of dampness.","cn":"随着农业、食品加工和工程的发展，moisture 逐渐指可测量的含水量，而不只是潮湿的感觉。"}]},"similar":{"note":{"en":"Group one holds forms that look or sound close to moisture; group two holds words that also name water held somewhere.","cn":"第一组是与 moisture 字形或读音接近的词；第二组是也指「某处所含的水」的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"moister","ipa":"/ˈmɔɪstə/","tag":"comparative of moist","definition":"The comparative of the adjective moist, meaning more damp. It belongs to the same family and adds -er, not -ure.","definitionCN":"形容词 moist 的比较级，表示更湿润。它属同一词族，词尾是 -er 而不是 -ure。"},{"word":"mixture","ipa":"/ˈmɪkstʃə/","tag":"unrelated","definition":"A combination of two or more substances. The middle consonant is -xt-, and the word comes from Latin miscere 'to mix', not from moist.","definitionCN":"两种或多种物质的混合物。中间是 -xt-，源自拉丁语 miscere「混合」，与 moist 无关。"},{"word":"moisturizer","ipa":"/ˈmɔɪstʃəraɪzə/","tag":"derived noun","definition":"A cream that adds water to the skin; it is moisture plus -ize plus -er, so the ending is long and the meaning is a product.","definitionCN":"给皮肤补水的乳霜；由 moisture 加 -ize 再加 -er 构成，词尾更长，指的是产品。"}]},{"heading":"NEAR MEANING","entries":[{"word":"dampness","ipa":"/ˈdæmpnəs/","tag":"slight wetness","definition":"A mildly unpleasant wetness in air or in a material; it often carries a hint of discomfort that moisture does not.","definitionCN":"空气或材料中令人略感不适的微湿；常带 moisture 所没有的不适意味。"},{"word":"humidity","ipa":"/hjuːˈmɪdəti/","tag":"water in air","definition":"The amount of water vapour in the air, usually reported as a percentage; it is the technical measure of atmospheric moisture.","definitionCN":"空气中的水汽量，通常以百分比报告，是大气水分的技术指标。"},{"word":"condensation","ipa":"/ˌkɒndenˈseɪʃn/","tag":"water from vapour","definition":"The process by which vapour turns into liquid, or the drops produced; moisture on a window is its visible result.","definitionCN":"水汽变成液体的过程，或由此产生的水珠；窗上的水汽就是它的可见结果。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real suffixes and real compounds, not invented rhymes.","cn":"正常联想：使用真实的后缀与真实的复合词，不编造顺口溜。"},"normal":[{"en":"moist + -ure: -ure is a noun suffix seen in pressure and departure, so the adjective 'wet' becomes the noun 'wetness'.","cn":"moist + -ure：-ure 是名词后缀（如 pressure、departure），于是形容词「湿的」变成名词「湿气」。"},{"en":"moisten = moist + -en, the suffix that turns adjectives into verbs of making, as in widen and deepen.","cn":"moisten = moist + -en，这个后缀把形容词变成「使……」的动词，如 widen、deepen。"},{"en":"moisturize = moisture + -ize, 'to put moisture into', and a moisturizer is the thing that does it.","cn":"moisturize = moisture + -ize，意为「把水分放进去」；moisturizer 就是做这件事的东西。"},{"en":"moisture-proof = moisture + -proof 'resistant to', the same pattern as waterproof and fireproof.","cn":"moisture-proof = moisture + -proof「防……的」，与 waterproof、fireproof 同构。"},{"en":"The fixed phrases soil moisture and moisture content turn invisible water into something a farmer or engineer can measure.","cn":"固定搭配 soil moisture 与 moisture content 把看不见的水变成农民或工程师可以测量的东西。"}],"abstract":[{"en":"Abstractly, moisture is water that has stopped moving: no river, no wave, only a film clinging to a surface. Symbol: a grey stone with one shining skin.","cn":"抽象地看，moisture 是停止流动的水：不是河，不是浪，只是贴在表面上的一层膜。符号：一块灰石头上裹着一层发亮的薄皮。"},{"en":"The same film can live in air, in earth, in wood or in skin; the holder changes, the amount stays small.","cn":"同一层膜可以住在空气、泥土、木头或皮肤里；容器在变，量始终很小。"},{"en":"So moisture is not 'water' but 'water held'; the word always asks where it is kept and how much remains.","cn":"所以 moisture 不是「水」，而是「被留住的水」；这个词总在追问：它被存在哪里，还剩多少。"}]},"examples":[{"en":"A sealed jar keeps the moisture in the tobacco from escaping.","cn":"密封的罐子能防止烟草里的水分跑掉。"},{"en":"Farmers dig shallow pits to trap moisture during the dry season.","cn":"农民在旱季挖浅坑来留住水分。"},{"en":"The forecast warns that moisture from the gulf will bring heavy rain.","cn":"预报提醒来自墨西哥湾的水汽将带来大雨。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「抹湿的」：抹一下，表面就湿了 → moisture 湿气、水分","word":"moisture"},"root":"古法语 moistour「湿气」← moiste「湿的」；再往前通常重构为俗拉丁语 *muscidus「发霉的」，也有人联系拉丁语 madere「潮湿」，来源不确定。","sensesIntro":{"en":"Eight senses follow one idea: a small amount of water held by something. It starts on a surface, moves into air and soil, enters materials and skin, appears as condensation, becomes a measured ratio, and finally counts as damage.","cn":"八个义项围绕一个意思展开：被某物留住的一点点水。它从表面开始，进入空气与土壤，进入材料与皮肤，又以凝结水的形态出现，随后变成可测的比值，最后被视为一种损坏。"},"semanticMap":{"core":{"en":"CORE IMAGE: a little water that cannot flow away because a surface or a body holds it.","cn":"核心意象：一点无法流走的水，因为某个表面或物体把它留住了。"},"chain":["SURFACE FILM","AIR VAPOUR","SOIL WATER","MATERIAL CONTENT","LIVING TISSUE","MEASURED VALUE"],"branches":[{"senses":"01 · 06","en":"VISIBLE FILM: dew on rock and condensation on glass are the same skin of water, produced by two different causes.","cn":"可见水膜：岩石上的露与玻璃上的凝结水是同一层水皮，只是成因不同。"},{"senses":"02 · 03","en":"HIDDEN HOLDERS: air and soil carry water without showing it, one as vapour and one between particles.","cn":"隐形容器：空气与土壤都不显形地带着水，一个以水汽，一个在颗粒之间。"},{"senses":"04 · 07","en":"INSIDE A SUBSTANCE: grain and concrete hold water that trade and engineering want as a number.","cn":"物质内部：谷物与混凝土所含的水，是交易与工程想要的一个数字。"},{"senses":"05","en":"LIVING TISSUE: skin and hair hold water that cosmetics try to keep in place.","cn":"活体组织：皮肤与头发所含的水，是护肤品想留住的东西。"},{"senses":"08","en":"FAULT: the same water becomes a defect when the holder is a wall or a floor.","cn":"毛病：当容器是墙或地板时，同一份水就成了缺陷。"}]},"affixes":{"intro":{"en":"Moisture sits at the centre of a small family of suffixes: -ure makes the noun, -en and -ize make verbs, -ness makes a quality, and -proof makes a defence.","cn":"moisture 处在一个小词族的中心：-ure 造名词，-en 与 -ize 造动词，-ness 造性质名词，-proof 造防护形容词。"},"latinIntro":{"en":"Moist and moisture came through Old French, and the Latin step behind them is disputed. Because no Latin source can be stated safely, the Latin entry list is left empty on purpose.","cn":"moist 与 moisture 经古法语而来，其背后的拉丁环节存在争议。由于无法稳妥地给出拉丁来源，拉丁词条列表按设计留空。"},"items":[{"word":"moisture-proof","structure":"moisture + -proof (resistant to)","meaning":"made so that damp cannot get in or out","meaningCN":"防潮的（-proof 表示「防……的」）","example":"The seeds are packed in moisture-proof foil.","exampleCN":"种子被装在防潮的铝箔袋里。"},{"word":"moisture-wicking","structure":"moisture + wicking (drawing liquid away)","meaning":"able to pull sweat or water away from a surface","meaningCN":"吸湿排汗的（wick 指把液体吸走）","example":"Runners prefer moisture-wicking socks.","exampleCN":"跑者更爱穿吸湿排汗的袜子。"},{"word":"moisturize","structure":"moisture + -ize (verb-forming)","meaning":"to add water to the skin or hair","meaningCN":"给皮肤或头发补水（-ize 构成动词）","example":"She moisturizes her hands after every wash.","exampleCN":"她每次洗手后都会给手补水。"},{"word":"moisturizer","structure":"moisturize + -er (thing that does)","meaning":"a product that adds water to the skin","meaningCN":"保湿霜；润肤品（-er 表示做该动作的东西）","example":"Use a light moisturizer under sunscreen.","exampleCN":"防晒霜下面先涂一层清爽的保湿霜。"},{"word":"moisten","structure":"moist + -en (make)","meaning":"to make something slightly wet","meaningCN":"使微湿；沾湿（-en 表示「使……」）","example":"Moisten the clay before you shape it.","exampleCN":"塑形之前先把黏土弄湿。"},{"word":"moistness","structure":"moist + -ness (quality noun)","meaning":"the quality of being slightly wet","meaningCN":"湿润；潮湿（-ness 构成性质名词）","example":"The moistness of the cake depends on the flour.","exampleCN":"蛋糕的湿润程度取决于面粉。"},{"word":"moist","structure":"base adjective of the family","meaning":"slightly wet, often in a pleasant way","meaningCN":"微湿的（常带宜人的意味），是本词族的基础形容词","example":"The cake stays moist for three days.","exampleCN":"这块蛋糕能保持湿润三天。"},{"word":"soil moisture","structure":"soil + moisture (compound)","meaning":"water held in the ground, studied in farming and hydrology","meaningCN":"土壤水分（soil 与 moisture 构成的复合术语）","example":"Sensors log soil moisture every hour.","exampleCN":"传感器每小时记录一次土壤水分。"}],"latinEntries":[]}},{"word":"moist","ipa_uk":"/mɔɪst/","ipa_us":"/mɔɪst/","definition_zh":"微湿的；湿润的；潮湿的；（食物）湿润柔软的","definition_en":"slightly wet, especially in a soft or pleasant way rather than soaked","core_image":"刚拧过的毛巾还留着水痕，摸上去凉而柔，却不会滴下水来","scene":"面包师把一块微湿的布盖在面团上，布面只是潮潮的。The baker laid a moist cloth over the dough.","sceneCN":"这里该词指「带少量水、微湿而不滴水」（第 1 个义项：表面轻微湿润）；句意为面包师把一块微湿的布盖在面团上。","pos":[{"tag":"adj.","zh":"微湿的；湿润的；（气候）潮湿的；（食物）湿润柔软的"}],"collocations":[{"phrase":"moist soil","zh":"湿润的土壤"},{"phrase":"moist air","zh":"潮湿的空气"},{"phrase":"moist eyes","zh":"含着泪的眼睛"},{"phrase":"keep the cake moist","zh":"让蛋糕保持湿润"},{"phrase":"a moist cloth","zh":"一块湿布"},{"phrase":"moist heat","zh":"湿热（烹饪或理疗用语）"}],"forms":[{"label":"比较级","form":"moister"},{"label":"最高级","form":"moistest"},{"label":"动词（使湿润）","form":"moisten"},{"label":"名词（湿润）","form":"moistness"},{"label":"名词（湿气；水分）","form":"moisture"}],"derivatives":[{"word":"moisten","pos":"v.","zh":"使湿润；沾湿"},{"word":"moistness","pos":"n.","zh":"湿润；潮气"},{"word":"moisture","pos":"n.","zh":"湿气；水分；含水量"},{"word":"moisturize","pos":"v.","zh":"给皮肤补水"},{"word":"moisturizer","pos":"n.","zh":"保湿霜"}],"senses":[{"no":"01","title":"Slightly wet to the touch","titleCN":"摸上去微微湿润","definition":"slightly wet, with enough water to be felt but not enough to drip","definitionCN":"带有一点可被摸出的水，但还不到往下滴的程度","example":"The baker laid a moist cloth over the dough.","exampleCN":"面包师把一块微湿的布盖在面团上。","why":"Moist is the adjective of the moisture family, so it describes the state of holding a small amount of water, never being soaked.","whyCN":"moist 是 moisture 词族的形容词，描述「持有少量水」的状态，而不是被水浸透。"},{"no":"02","title":"Soil that holds water for roots","titleCN":"能保住水供根系吸收的土壤","definition":"soil that is damp enough for plants to draw water from it","definitionCN":"湿润到足以让植物从其中吸水生长的土壤","example":"Seedlings grow fastest in moist soil.","exampleCN":"幼苗在湿润的土壤里长得最快。","why":"A surface that holds the right amount of water is good ground; the same adjective follows the water into the earth.","whyCN":"恰好留住适量水的表面就是好土地；同一个形容词跟着水走进了泥土。"},{"no":"03","title":"Air carrying water vapour","titleCN":"带着水汽的空气","definition":"air that contains noticeable water vapour, often warm and heavy","definitionCN":"含有明显水汽、常显得温暖沉闷的空气","example":"A moist wind blew in from the sea.","exampleCN":"一阵潮湿的风从海上吹来。","why":"Air can be wet without being liquid, so moist here describes what the air holds rather than what it touches.","whyCN":"空气可以非液态地「湿」着，所以这里的 moist 描述空气所含之物，而不是它碰到的东西。"},{"no":"04","title":"Food with a soft, wet texture","titleCN":"口感柔软湿润的食物","definition":"food that is soft and retains water, usually said with approval","definitionCN":"柔软并保住了水的食物，通常带赞许意味","example":"The cake stays moist for three days.","exampleCN":"这块蛋糕能保持湿润三天。","why":"For bakers, dryness is the fault and moisture the virtue, so moist became a word of praise on a menu.","whyCN":"对烘焙者来说，干是缺点、湿是优点，于是 moist 成了菜单上的褒词。"},{"no":"05","title":"Eyes filled with tears","titleCN":"含着泪的眼睛","definition":"eyes that are wet because tears are rising in them","definitionCN":"因泪水涌起而显得湿的眼睛","example":"Her eyes grew moist when the letter was read aloud.","exampleCN":"信被大声念出来时，她的眼睛湿了。","why":"The body's own water shows an inner state; the adjective moves from weather and food to feeling.","whyCN":"身体里的水显露内心状态，这个形容词于是从天气与食物走到了情感。"},{"no":"06","title":"A damp climate or season","titleCN":"潮湿的气候或季节","definition":"a climate or season with persistently damp air","definitionCN":"空气长期潮湿的气候或季节","example":"The valley has a moist climate that suits ferns.","exampleCN":"这个山谷气候潮湿，很适合蕨类生长。","why":"When dampness lasts long enough to define a place, the word becomes a description of climate.","whyCN":"当潮湿持续得足以定义一个地方时，这个词就成了对气候的描述。"},{"no":"07","title":"Tissue kept from drying out","titleCN":"被保持不干的组织","definition":"in medicine and skin care, tissue kept in its natural damp state","definitionCN":"医学与护肤语境中，保持在天然湿润状态的组织","example":"Keep the wound moist while it heals.","exampleCN":"伤口愈合期间要保持湿润。","why":"Medical writers borrowed the plain adjective to mean 'not allowed to dry', the same idea applied to a patient.","whyCN":"医学写作借用了这个普通形容词，表示「不让变干」，只是把同一想法用到病人身上。"},{"no":"08","title":"Moist heat in cooking and therapy","titleCN":"烹饪与理疗中的湿热","definition":"heat carried by steam or water rather than by dry air","definitionCN":"由蒸汽或水而非干热空气传导的热","example":"Braising cooks the meat with moist heat.","exampleCN":"炖煮用湿热把肉做熟。","why":"Here moist does not describe an object but a medium: heat that travels with water.","whyCN":"这里的 moist 不描述物体，而描述介质：随水一起传导的热。"}],"etymology":{"intro":{"en":"Moist comes from Old French and its Latin background is contested. The reconstruction is labelled as a hypothesis; the word's deeper source is marked as source uncertain.","cn":"moist 来自古法语，其拉丁背景存在争议。重构形式已标注为假说；更深来源不确定。"},"items":[{"era":"OLD FRENCH (12c–13c)","en":"Old French moiste meant 'wet, damp, fresh', and also 'newly made, still soft', a range wider than the modern English word.","cn":"古法语 moiste 意为「湿的、潮湿的、新鲜的」，也有「刚做成、仍柔软的」义，范围比现代英语更宽。"},{"era":"MIDDLE ENGLISH (c. 1300)","en":"English took moiste as moist and used it for damp air, damp earth and food that had not dried out.","cn":"英语借入为 moist，用于潮湿的空气、湿润的土地和没有变干的食物。"},{"era":"VULGAR LATIN (reconstructed *muscidus)","en":"The common reconstruction is Vulgar Latin *muscidus 'mouldy', an altered form of Latin mucidus. The alteration is assumed, not attested.","cn":"常见重构是俗拉丁语 *muscidus「发霉的」，为拉丁语 mucidus 的变形。这一变形是假定，并无文献记录。"},{"era":"CLASSICAL LATIN (competing explanation)","en":"Other scholars link the Romance family to Latin madidus 'wet, soaked' and madere 'to be wet'. The two hypotheses are usually presented together rather than decided.","cn":"另一些学者把这一罗曼语词族联系到拉丁语 madidus「湿透的」与 madere「潮湿」。两种假说通常并列陈述，不作定论。"},{"era":"MODERN ENGLISH (16c–19c)","en":"The 'eyes wet with tears' use appears in the sixteenth century, and the approving culinary use became common in the nineteenth.","cn":"「眼睛含泪」的用法出现于十六世纪，带赞许意味的烹饪用法在十九世纪变得常见。"}]},"similar":{"note":{"en":"Group one holds short words that look or sound close to moist; group two holds adjectives that also describe water.","cn":"第一组是与 moist 字形或读音接近的短词；第二组是也描述水分的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"most","ipa":"/məʊst/","tag":"unrelated determiner","definition":"The superlative of much or many. It has a long vowel and ends in -st, and comes from Old English mǣst, not from the moist family.","definitionCN":"much 或 many 的最高级。元音较长，词尾是 -st，源自古英语 mǣst，与 moist 词族无关。"},{"word":"hoist","ipa":"/hɔɪst/","tag":"unrelated verb","definition":"To lift something with ropes or a machine. The vowel is /ɔɪ/ and the first consonant is h-, so the two words are not related.","definitionCN":"用绳索或机械把某物升起。元音是 /ɔɪ/，首辅音是 h-，两词没有词源关系。"},{"word":"must","ipa":"/mʌst/","tag":"unrelated modal","definition":"A modal verb of obligation, or the juice of crushed grapes. The vowel is /ʌ/ and the meaning has nothing to do with dampness.","definitionCN":"表示义务的情态动词，或压碎的葡萄汁。元音是 /ʌ/，意义与潮湿无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"damp","ipa":"/dæmp/","tag":"slightly wet","definition":"Slightly wet, usually in a way that feels cold or unpleasant; damp often criticises where moist may praise.","definitionCN":"微湿，通常带阴冷或不适感；damp 常带批评，而 moist 可能带赞许。"},{"word":"humid","ipa":"/ˈhjuːmɪd/","tag":"air with vapour","definition":"Describing air or weather that holds a lot of water vapour, usually oppressively so; it applies to air, rarely to cake.","definitionCN":"形容空气或天气含水汽多，常令人闷热；它用于空气，很少用于蛋糕。"},{"word":"wet","ipa":"/wet/","tag":"covered with water","definition":"Covered or soaked with liquid water; it is stronger than moist and implies visible water or a thorough soaking.","definitionCN":"被液态水覆盖或浸透；比 moist 更强，暗示可见的水或彻底浸湿。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real suffixes and real compounds, not invented rhymes.","cn":"正常联想：使用真实的后缀与真实的复合词，不编造顺口溜。"},"normal":[{"en":"moist is the adjective, moisture is the noun: remove the -ure noun ending and you are left with the describing word.","cn":"moist 是形容词，moisture 是名词：去掉名词后缀 -ure，就剩下那个描述性的词。"},{"en":"moisten adds -en 'make', the same pattern as deepen and strengthen, so it means 'make moist'.","cn":"moisten 加 -en「使……」，与 deepen、strengthen 同构，所以就是「使湿润」。"},{"en":"moistness is moist plus -ness, the standard suffix for a quality, as in kindness and darkness.","cn":"moistness 是 moist 加 -ness，这是表示性质的标准后缀，如 kindness、darkness。"},{"en":"moist heat is a real cooking term opposed to dry heat: braising and steaming use steam, roasting and grilling use dry air.","cn":"moist heat 是真实的烹饪术语，与 dry heat 相对：炖、蒸用蒸汽，烤、炙用干热空气。"},{"en":"moist eyes is a common written phrase for tears about to fall, linking a physical film of water to emotion.","cn":"moist eyes 是常见的书面搭配，指快要落下的眼泪，把一层水的物理薄膜与情绪连在一起。"}],"abstract":[{"en":"Abstractly, moist is water below the dripping point: enough to be felt, not enough to fall. Symbol: a towel that leaves a print on the table but no puddle.","cn":"抽象地看，moist 是还没到滴落点的水：足以被感觉到，却不足以落下来。符号：一条在桌上留下印子却没有积水的毛巾。"},{"en":"The same 'just enough water' can be praise in a cake, a warning in a wall, and tenderness in an eye.","cn":"同样的「恰好够的水」，在蛋糕里是赞美，在墙里是警告，在眼睛里是柔情。"},{"en":"So moist never means soaked; it always means a small, contained, often welcome amount.","cn":"所以 moist 从不表示浸透，而总是表示少量、被收住、往往还是受欢迎的一份水。"}]},"examples":[{"en":"Turn the soil while it is still moist but not muddy.","cn":"趁土还湿润但没变成泥的时候翻土。"},{"en":"A moist towel is better than a dry one for cleaning up dust.","cn":"擦灰时用湿毛巾比干毛巾好用。"},{"en":"The air felt moist before the storm arrived.","cn":"暴风雨来临前，空气显得潮乎乎的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「抹湿」：抹布一抹，桌面就湿了 → moist 微湿的","word":"moist"},"root":"古法语 moiste「湿的」；其拉丁来源有争议，通常重构为俗拉丁语 *muscidus（源自拉丁 mucidus「发霉的」），也有学者联系 madere「潮湿」，来源不确定。","sensesIntro":{"en":"Eight senses follow one idea: water just below the dripping point. The word starts at a surface, then enters soil, air, food, eyes, climate, healing tissue and finally a cooking medium.","cn":"八个义项围绕一个意思展开：还没到滴落点的水。这个词从表面开始，随后进入土壤、空气、食物、眼睛、气候、愈合中的组织，最后成为一种烹饪介质。"},"semanticMap":{"core":{"en":"CORE IMAGE: a surface that is cool and slightly dark with water but never drips.","cn":"核心意象：一块被水弄得发凉、颜色略深、却始终不滴水的表面。"},"chain":["SLIGHT WETNESS","PLANT GROUND","DAMP AIR","FOOD TEXTURE","TEARFUL EYES","DAMP CLIMATE"],"branches":[{"senses":"01 · 07","en":"A FILM OF WATER: plain touch and medical care both describe tissue that holds a little water.","cn":"一层水膜：日常触摸与医疗护理都在描述含着少量水的组织。"},{"senses":"02 · 03","en":"DAMP MEDIA: soil and air hold water invisibly, one for roots and one as vapour.","cn":"潮湿介质：土壤与空气都看不见地含水，一个为根系，一个以水汽。"},{"senses":"04 · 08","en":"WATER AS A MEDIUM: in baking it keeps food soft; in cooking it carries heat as steam.","cn":"水作介质：烘焙时它让食物柔软；烹饪时它以蒸汽搬运热量。"},{"senses":"05","en":"EMOTION: tears rising make the eye itself the moist surface.","cn":"情感：涌起的泪水让眼睛本身成了那块湿润的表面。"},{"senses":"06","en":"PLACE: lasting dampness becomes a climate, no longer a passing sensation.","cn":"地方：持久的潮湿变成一种气候，而不再是暂时的感觉。"}]},"affixes":{"intro":{"en":"Moist is the base adjective of a productive family: -en makes a verb, -ness a quality noun, -ure a mass noun, and -ize builds the cosmetics verb.","cn":"moist 是一个能产词族的基础形容词：-en 造动词，-ness 造性质名词，-ure 造物质名词，-ize 造护肤动词。"},"latinIntro":{"en":"The Latin background of moist is disputed and cannot be stated safely, so the Latin entry list is empty on purpose. The related words below are all English formations or Old French borrowings.","cn":"moist 的拉丁背景存在争议，无法稳妥陈述，因此拉丁词条列表按设计留空。下面的相关词都是英语构词或古法语借词。"},"items":[{"word":"moisten","structure":"moist + -en (make)","meaning":"to make something slightly wet","meaningCN":"使微湿；沾湿（-en 表示「使……」）","example":"Moisten the edge before sealing the envelope.","exampleCN":"封信封前先把边缘弄湿。"},{"word":"moistness","structure":"moist + -ness (quality)","meaning":"the state of being slightly wet","meaningCN":"湿润的状态（-ness 构成性质名词）","example":"The moistness of the air warned of rain.","exampleCN":"空气的湿润预示着要下雨。"},{"word":"moisture","structure":"moist + -ure (mass noun)","meaning":"water held in small amounts","meaningCN":"湿气；水分（-ure 构成物质名词）","example":"The soil loses moisture in July.","exampleCN":"七月里土壤会失去水分。"},{"word":"moisturize","structure":"moisture + -ize (verb)","meaning":"to add water to skin or hair","meaningCN":"给皮肤或头发补水（-ize 构成动词）","example":"Moisturize daily to prevent cracking.","exampleCN":"每天保湿以防干裂。"},{"word":"moisturizer","structure":"moisturize + -er (agent noun)","meaning":"a product used to add water to the skin","meaningCN":"保湿产品（-er 表示施动者）","example":"She keeps a moisturizer in her bag.","exampleCN":"她包里常备一支保湿霜。"},{"word":"moisture-proof","structure":"moisture + -proof (resistant to)","meaning":"sealed against damp","meaningCN":"防潮的（-proof 表示「防……的」）","example":"Store the salt in a moisture-proof jar.","exampleCN":"把盐存放在防潮罐里。"},{"word":"moist-heat","structure":"moist + heat (compound)","meaning":"heat carried by steam or water in cooking","meaningCN":"湿热（烹饪中由蒸汽或水传导的热）","example":"Moist-heat methods keep meat tender.","exampleCN":"湿热做法能让肉保持嫩。"},{"word":"moist-eyed","structure":"moist + eyed (compound adjective)","meaning":"having eyes wet with tears","meaningCN":"眼含泪水的（moist 与 eyed 构成的复合形容词）","example":"The audience sat moist-eyed at the end.","exampleCN":"结束时观众坐着，眼里含着泪。"}],"latinEntries":[]}},{"word":"precipitation","ipa_uk":"/ˌpresɪpɪˈteɪʃn/","ipa_us":"/ˌpresəpəˈteɪʃn/","definition_zh":"降水；降水量；（化学）沉淀；沉淀物；仓促","definition_en":"water that falls from clouds as rain, snow, hail or sleet, or a solid that forms out of a solution","core_image":"云里的小水滴越聚越多，云托不住，一齐落向地面","scene":"山脊上的雨量筒一夜之间就积满了水。Overnight precipitation filled the rain gauge on the ridge.","sceneCN":"这里该词指「从云中落到地面的水」（第 1 个义项：雨、雪、冰雹等从天而降的水）；句意为一夜之间的降水装满了山脊上的雨量筒。","pos":[{"tag":"n.","zh":"降水；降水量；（化学）沉淀；沉淀物；仓促"}],"collocations":[{"phrase":"annual precipitation","zh":"年降水量"},{"phrase":"heavy precipitation","zh":"强降水"},{"phrase":"average precipitation","zh":"平均降水量"},{"phrase":"precipitation in the form of snow","zh":"以降雪形式出现的降水"},{"phrase":"precipitation reaction","zh":"沉淀反应"},{"phrase":"acid precipitation","zh":"酸性降水；酸雨"}],"forms":[{"label":"不可数用法（气象义）","form":"precipitation（通常不可数）"},{"label":"动词（使沉淀；促成）","form":"precipitate"},{"label":"形容词（仓促的；鲁莽的）","form":"precipitate"},{"label":"名词（沉淀物）","form":"precipitate"},{"label":"形容词（陡峭的；急躁的）","form":"precipitous"}],"derivatives":[{"word":"precipitate","pos":"v./n./adj.","zh":"使沉淀；促成 / 沉淀物 / 仓促的"},{"word":"precipitous","pos":"adj.","zh":"陡峭的；急躁的"},{"word":"precipice","pos":"n.","zh":"悬崖；险境"},{"word":"precipitant","pos":"n./adj.","zh":"沉淀剂 / 仓促的"},{"word":"precipitator","pos":"n.","zh":"沉淀器；静电除尘器"}],"senses":[{"no":"01","title":"Water falling from clouds","titleCN":"从云中落下的水","definition":"water that falls from the atmosphere to the ground","definitionCN":"从大气降落到地面的水","example":"Overnight precipitation filled the rain gauge on the ridge.","exampleCN":"一夜之间的降水装满了山脊上的雨量筒。","why":"The Latin verb means 'to throw headlong'; the meteorologists' noun keeps that downward motion and applies it to water leaving the sky.","whyCN":"拉丁动词意为「头朝下抛落」；气象学的名词保留了这个向下动作，只是把落下的东西换成了离开天空的水。"},{"no":"02","title":"Snow, hail or sleet as forms of fall","titleCN":"雪、冰雹、雨夹雪等降落形式","definition":"any form in which water falls, whether liquid or frozen","definitionCN":"水降落的任何一种形态，无论液态还是冻结","example":"Winter precipitation in the mountains usually arrives as snow.","exampleCN":"山区的冬季降水通常以雪的形式到来。","why":"Rain is only the commonest case; the word covers the whole class, so frozen forms count as the same event.","whyCN":"雨只是最常见的一种；这个词覆盖整个类别，所以冻结形态也算同一种事件。"},{"no":"03","title":"The measured total","titleCN":"测得的降水总量","definition":"the amount of water that has fallen, usually measured in millimetres or inches","definitionCN":"已经落下的水量，通常以毫米或英寸计","example":"The desert receives less than ten inches of precipitation a year.","exampleCN":"这片沙漠每年降水不足十英寸。","why":"Once rain is caught in a gauge, the event turns into a quantity, and the same noun names the number.","whyCN":"一旦雨被雨量筒接住，事件就变成了数量，同一个名词也就用来指这个数字。"},{"no":"04","title":"A solid forming in a solution","titleCN":"溶液中析出固体","definition":"in chemistry, the process by which a dissolved substance becomes a solid","definitionCN":"化学中指溶解的物质变成固体的过程","example":"Adding the salt caused precipitation of the dissolved silver.","exampleCN":"加入这种盐使溶解的银发生了沉淀。","why":"A substance that was spread through a liquid suddenly stops being dissolved; it 'throws itself down' as a solid, the same image as rain leaving a cloud.","whyCN":"原本分散在液体里的物质忽然不再溶解，以固体的形态「把自己抛下来」，与雨离开云是同一个意象。"},{"no":"05","title":"The solid that comes out","titleCN":"析出的固体物质","definition":"the solid material produced by that chemical process","definitionCN":"该化学过程产生的固体物质","example":"The white precipitation was filtered off and dried.","exampleCN":"白色沉淀物被滤出并烘干。","why":"English uses the same word for the process and for its product, because the product is simply the process seen as a finished thing.","whyCN":"英语用同一个词既指过程也指产物，因为产物就是过程完成后被看作一个东西。"},{"no":"06","title":"A sudden onset of events","titleCN":"事件突然发生","definition":"the act of making something happen suddenly or too soon","definitionCN":"使某事突然或过早发生","example":"The report warns against precipitation of a trade war.","exampleCN":"报告警告不要贸然引发贸易战。","why":"The old sense 'throwing headlong' moved from bodies to events: a crisis that is precipitated falls on people all at once.","whyCN":"古老的「头朝下抛落」从身体移到了事件：被促成的危机一下子砸到人头上。"},{"no":"07","title":"Haste or rashness","titleCN":"仓促；鲁莽","definition":"the quality of acting too quickly, without enough thought","definitionCN":"行动过快、思虑不足的性质","example":"He acted with precipitation and lost the contract.","exampleCN":"他行事仓促，丢掉了那份合同。","why":"Someone who rushes is 'falling headlong' in behaviour rather than in body, so the metaphor becomes a judgement of character.","whyCN":"匆忙的人是行为上「头朝下栽」，而非身体上，于是这个比喻变成对人的评价。"},{"no":"08","title":"The meteorological process","titleCN":"气象学上的降水过程","definition":"the whole process by which water vapour condenses and falls","definitionCN":"水汽凝结并落下的整个过程","example":"Cold air over the lake increases precipitation along the shore.","exampleCN":"湖面上的冷空气增加了沿岸的降水。","why":"This sense names the mechanism rather than the result, the same event viewed as a chain of steps.","whyCN":"这个义项指机制而不是结果，是同一事件被看作一串步骤。"}],"etymology":{"intro":{"en":"Every sense goes back to one Latin verb meaning 'to throw headlong'. The word entered English through borrowed Latin, not through inheritance. Dates are approximate.","cn":"所有义项都回到同一个拉丁动词，意为「头朝下抛落」。这个词经拉丁语借入英语，而非本土传承。年代为大致估计。"},"items":[{"era":"CLASSICAL LATIN","en":"Latin praecipitatio meant 'a falling headlong' or 'haste', formed from praecipitare 'to throw down headlong'.","cn":"拉丁语 praecipitatio 意为「头朝下坠落」或「仓促」，由 praecipitare「头朝下抛落」构成。"},{"era":"LATIN STRUCTURE","en":"The verb joins prae- 'before, forth' with caput 'head' (stem capit-). The picture is someone diving forward, head first.","cn":"这个动词由 prae-「在前、向前」与 caput「头」（词干 capit-）组成。画面是一个人向前、头朝下地栽下去。"},{"era":"MEDIEVAL LATIN / EARLY ENGLISH (15c)","en":"Alchemical and medical Latin used praecipitatio for a substance settling out of a liquid, and English writers borrowed this technical sense.","cn":"中世纪拉丁语中的炼金术与医学用语用 praecipitatio 指物质从液体中沉降出来，英语作者借入了这一技术义。"},{"era":"EARLY MODERN ENGLISH (17c)","en":"Meteorologists applied the same noun to rain and snow falling from clouds, the modern everyday sense.","cn":"十七世纪的气象写作者把同一个名词用到从云中落下的雨雪上，形成现代日常义。"},{"era":"MODERN ENGLISH (19c–20c)","en":"Chemistry standardized precipitation for the formation of a solid, and climate science made it the standard word for measured rainfall and snowfall totals.","cn":"十九至二十世纪，化学把 precipitation 固定为固体析出的术语，气候科学则用它作为雨雪总量的标准词。"}]},"similar":{"note":{"en":"Group one holds longer words that share the -pitation shape; group two holds the everyday weather words it covers.","cn":"第一组是与该词共享 -pitation 词形的长词；第二组是它所涵盖的日常天气词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"participation","ipa":"/ˌpɑːtɪsɪˈpeɪʃn/","tag":"unrelated","definition":"Taking part in an activity. It comes from Latin particeps 'sharing', and the -cip- here is from capere 'to take', a different family.","definitionCN":"参与某项活动。源自拉丁语 particeps「分享」，其中的 -cip- 出自 capere「拿取」，属另一词族。"},{"word":"perception","ipa":"/pəˈsepʃn/","tag":"unrelated","definition":"The act of noticing or understanding something. It comes from percipere 'to seize wholly', not from praecipitare.","definitionCN":"察觉或理解某事的行为。源自 percipere「完全抓住」，并非出自 praecipitare。"},{"word":"preparation","ipa":"/prɪˌpærəˈʃn/","tag":"unrelated","definition":"The act of getting something ready. The base is parare 'to make ready', so the resemblance is only in length and rhythm.","definitionCN":"把某物准备好的行为。词基是 parare「准备」，相似之处只在词长与节奏。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rainfall","ipa":"/ˈreɪnfɔːl/","tag":"liquid only","definition":"Rain measured over a period; it excludes snow and hail, while precipitation includes every form.","definitionCN":"一段时间内测得的雨量；它不包括雪和冰雹，而 precipitation 包含一切形态。"},{"word":"snowfall","ipa":"/ˈsnəʊfɔːl/","tag":"frozen only","definition":"Snow that falls, or its measured amount; it is one member of the precipitation class.","definitionCN":"落下的雪或其测定量；它是降水这一大类中的一种。"},{"word":"condensation","ipa":"/ˌkɒndenˈseɪʃn/","tag":"vapour to liquid","definition":"The change from vapour to liquid that must happen before precipitation; it names the step, not the fall.","definitionCN":"降水发生前必须完成的水汽变液体；它指这一步，而不是落下。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin pieces, real chemistry terms, no invented stories.","cn":"正常联想：使用真实的拉丁构件与化学术语，不编故事。"},"normal":[{"en":"pre- 'before' + capit- 'head' + -ation: something that goes head first out of the sky or out of a solution.","cn":"pre-「在前」+ capit-「头」+ -ation：从天空或溶液里「头朝下」出来的东西。"},{"en":"precipitation and precipitate share one root; precipitation is the process, precipitate is the solid or the verb.","cn":"precipitation 与 precipitate 共享一个词根：前者是过程，后者是固体或动词。"},{"en":"precipitous 'steep' keeps the same image: a cliff where one false step sends you head first.","cn":"precipitous「陡峭的」保留同一意象：在悬崖上一步踏错就会头朝下栽下去。"},{"en":"acid precipitation is the technical name behind the everyday term acid rain.","cn":"acid precipitation 是日常说法 acid rain（酸雨）背后的技术名称。"},{"en":"The gauge phrase precipitation total pairs the event with its number, which is why the noun can mean both.","cn":"precipitation total 这一搭配把事件与数字配在一起，这正是该名词能同时指两者的原因。"}],"abstract":[{"en":"Abstractly, precipitation is anything that leaves a floating state and goes down: water leaving a cloud, a solid leaving a solution, a crisis leaving the future and landing in the present.","cn":"抽象地看，precipitation 是任何离开悬浮状态而向下落的东西：水离开云，固体离开溶液，危机离开未来而落到眼前。"},{"en":"The direction is always downward, and the agent is always something that can no longer stay suspended.","cn":"方向永远是向下，主体永远是那个再也悬浮不住的东西。"},{"en":"So the weather sense and the chemistry sense are one geometry: a ceiling gives way, and what was held falls.","cn":"所以天气义与化学义是同一个几何：顶托不住了，原本被托住的东西就落下来。"}]},"examples":[{"en":"The station records precipitation every morning at eight.","cn":"该站每天早上八点记录降水量。"},{"en":"Calcium carbonate precipitation sealed the cracks in the cave floor.","cn":"碳酸钙沉淀把洞底的裂缝封住了。"},{"en":"A sudden precipitation of events left the negotiators no time to consult.","cn":"事态的骤然爆发让谈判者来不及磋商。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「泼湿皮特」：天上泼下水，把皮特浇湿 → precipitation 降水","word":"precipitation"},"root":"拉丁语 praecipitatio「头朝下坠落」← praecipitare「抛落」，由 prae-「向前」+ caput「头」构成；与 precipice、precipitous 同族。","sensesIntro":{"en":"Eight senses share one downward motion. Water falls from a cloud, is counted in a gauge, takes frozen forms, then the same motion appears in a beaker as a solid, in public life as a sudden event, and in character as haste.","cn":"八个义项共享同一个向下动作。水从云里落下，被雨量筒计量，呈现冻结形态；随后同一动作出现在烧杯里成为固体，在公共生活中成为突发事件，在性格上成为仓促。"},"semanticMap":{"core":{"en":"CORE IMAGE: something held up by a ceiling suddenly gives way and falls head first.","cn":"核心意象：被一层顶托住的东西忽然失去支撑，头朝下坠落。"},"chain":["CLOUD WATER","FROZEN FORMS","GAUGE TOTAL","DISSOLVED SOLID","SUDDEN EVENT","HASTY ACT"],"branches":[{"senses":"01 · 02","en":"WHAT FALLS: liquid rain and frozen snow or hail are one class of falling water.","cn":"落下之物：液态的雨与冻结的雪、冰雹都属同一类落下的水。"},{"senses":"03","en":"HOW MUCH: a gauge turns the event into millimetres and inches.","cn":"落了多少：雨量筒把事件变成毫米与英寸。"},{"senses":"04 · 05","en":"CHEMISTRY: a dissolved substance leaves the liquid as a solid, and the solid takes the same name.","cn":"化学：溶解的物质离开液体成为固体，这个固体也用同一个名称。"},{"senses":"06 · 07","en":"HUMAN TIME: an event falls on people too soon, and the person who causes it is judged hasty.","cn":"人的时间：事件过早砸到人身上，促成它的人则被评判为仓促。"},{"senses":"08","en":"MECHANISM: meteorology names the whole condensation-and-fall chain.","cn":"机制：气象学用这个词命名凝结到落下的整条链条。"}]},"affixes":{"intro":{"en":"The family is built from Latin prae- plus caput. English adds -ation for the process, -ous for the steep version, and -or for an instrument.","cn":"这个词族由拉丁 prae- 加 caput 构成。英语加 -ation 表示过程，加 -ous 表示陡峭，加 -or 表示器具。"},"latinIntro":{"en":"The Latin entries below are the recorded ancestors and relatives of the family; they are listed as Latin, not as modern English words.","cn":"下面的拉丁条目是该词族有记录的祖先与亲属；它们按拉丁语列出，而不是现代英语词。"},"items":[{"word":"precipitate","structure":"praecipitare → precipitate (verb, noun, adjective)","meaning":"to cause a solid to form; the solid itself; hasty","meaningCN":"使固体析出；析出的固体；仓促的","example":"The reagent precipitates the metal as a salt.","exampleCN":"试剂使金属以盐的形式沉淀出来。"},{"word":"precipitous","structure":"praeceps 'headlong' + -ous (full of)","meaning":"extremely steep, like a cliff that drops away","meaningCN":"陡峭的，像骤然下落的悬崖（-ous 表示「充满……」）","example":"A precipitous path led down to the shore.","exampleCN":"一条陡峭的小路通向岸边。"},{"word":"precipice","structure":"praecipitium 'a steep place'","meaning":"a very steep cliff or a dangerous situation","meaningCN":"悬崖；险境","example":"The goats stood at the edge of the precipice.","exampleCN":"山羊站在悬崖边上。"},{"word":"precipitant","structure":"praecipitare + -ant (agent)","meaning":"a substance that causes another substance to precipitate","meaningCN":"沉淀剂（-ant 表示施动者）","example":"Add the precipitant slowly and stir.","exampleCN":"缓慢加入沉淀剂并搅拌。"},{"word":"precipitator","structure":"precipitate + -or (instrument)","meaning":"a device that removes particles from a gas by electrical attraction","meaningCN":"静电除尘器；沉淀器（-or 表示器具）","example":"The electrostatic precipitator catches the fly ash.","exampleCN":"静电除尘器捕集飞灰。"},{"word":"precipitation reaction","structure":"precipitation + reaction (compound term)","meaning":"a chemical reaction that produces an insoluble solid","meaningCN":"沉淀反应（生成不溶固体的化学反应）","example":"The lab demonstrates a precipitation reaction with silver nitrate.","exampleCN":"实验用硝酸银演示一个沉淀反应。"},{"word":"acid precipitation","structure":"acid + precipitation (compound term)","meaning":"rain or snow made acidic by dissolved pollutants","meaningCN":"酸性降水；酸雨（因溶解污染物而呈酸性的雨雪）","example":"Acid precipitation has damaged the lakes.","exampleCN":"酸性降水已经损害了这些湖泊。"},{"word":"precipitating","structure":"precipitate + -ing (participial form)","meaning":"the act or factor that causes something to happen or settle","meaningCN":"促成……的；正在沉淀的（-ing 分词形式）","example":"A poor harvest was the precipitating cause of the revolt.","exampleCN":"歉收是这场起义的直接诱因。"}],"latinEntries":[{"word":"praecipitatio","structure":"praecipitare → praecipitatio","meaning":"a falling headlong; haste","meaningCN":"头朝下坠落；仓促"},{"word":"praecipitare","structure":"prae- + caput (head)","meaning":"to throw down headlong; to hasten","meaningCN":"头朝下抛落；加速促成"},{"word":"praeceps","structure":"prae- + caput","meaning":"headlong, steep, rash","meaningCN":"头朝下的；陡峭的；鲁莽的"},{"word":"caput","structure":"root noun, stem capit-","meaning":"head","meaningCN":"头"}]}},{"word":"precipitate","ipa_uk":"/prɪˈsɪpɪteɪt/","ipa_us":"/prɪˈsɪpəteɪt/","definition_zh":"使沉淀；使突然发生；促成；猛地落下；仓促的；沉淀物","definition_en":"to cause a solid to form out of a solution, or to make an event happen suddenly and too soon","core_image":"澄清的溶液里浮着看不见的微粒，一滴试剂落下，它们忽然结成白色小块沉到杯底","scene":"实验员往澄清的溶液里滴入试剂，杯底很快出现白色粉末。A few drops of reagent precipitate a white powder at the bottom of the beaker.","sceneCN":"这里该词指「使溶解的物质析出成固体」（第 1 个义项：化学上使固体析出）；句意为几滴试剂使烧杯底部析出白色粉末。","pos":[{"tag":"vt.","zh":"使沉淀；使突然发生；促成"},{"tag":"vi.","zh":"沉淀；猛地落下"},{"tag":"adj.","zh":"仓促的；鲁莽的"},{"tag":"n.","zh":"沉淀物"}],"collocations":[{"phrase":"precipitate a crisis","zh":"促成一场危机"},{"phrase":"precipitate a reaction","zh":"引发反应；使反应发生"},{"phrase":"precipitate the collapse","zh":"加速崩溃"},{"phrase":"precipitate out","zh":"沉淀析出"},{"phrase":"a white precipitate","zh":"白色沉淀物"},{"phrase":"a precipitate decision","zh":"仓促的决定"}],"forms":[{"label":"三单（动词）","form":"precipitates"},{"label":"过去式","form":"precipitated"},{"label":"过去分词","form":"precipitated"},{"label":"现在分词","form":"precipitating"},{"label":"名词（过程）","form":"precipitation"},{"label":"形容词（陡峭的）","form":"precipitous"}],"derivatives":[{"word":"precipitation","pos":"n.","zh":"降水；沉淀；仓促"},{"word":"precipitous","pos":"adj.","zh":"陡峭的；急躁的"},{"word":"precipice","pos":"n.","zh":"悬崖；险境"},{"word":"precipitant","pos":"n./adj.","zh":"沉淀剂 / 仓促的"},{"word":"precipitator","pos":"n.","zh":"沉淀器；静电除尘器"}],"senses":[{"no":"01","title":"Cause a solid to form","titleCN":"使溶解物析出成固体","definition":"to cause a dissolved substance to come out of a solution as a solid","definitionCN":"使溶解的物质从溶液中以固体形态出来","example":"A few drops of reagent precipitate a white powder at the bottom of the beaker.","exampleCN":"几滴试剂使烧杯底部析出白色粉末。","why":"The Latin verb means 'throw headlong'; a solid that was invisibly dissolved is suddenly thrown down out of the liquid.","whyCN":"拉丁动词意为「头朝下抛落」；原本看不见地溶解着的固体，忽然被从液体里抛了下来。"},{"no":"02","title":"Settle out of a liquid","titleCN":"自行从液体中沉降","definition":"of a solid, to separate from a solution and settle","definitionCN":"固体从溶液中分离并沉降下来","example":"The salt precipitated out as the water evaporated.","exampleCN":"水分蒸发时，盐沉淀析出。","why":"When no agent is named, the subject is the solid itself doing the falling, so the verb turns intransitive.","whyCN":"当不点明施动者时，主语就是固体自己在落下，于是动词转为不及物。"},{"no":"03","title":"Make an event happen suddenly","titleCN":"使事件突然发生","definition":"to cause an event to happen suddenly or earlier than expected","definitionCN":"使事件突然、或比预期更早地发生","example":"The border incident precipitated a full diplomatic crisis.","exampleCN":"边境事件骤然引发了一场全面的外交危机。","why":"A crisis that was suspended in the future is thrown into the present; the downward image becomes a jump in time.","whyCN":"原本悬在未来的危机被抛进现在；向下的意象变成了时间上的跳跃。"},{"no":"04","title":"Hasten a process","titleCN":"加速某个过程","definition":"to make a process happen faster than it otherwise would","definitionCN":"使某个过程比原本更快地发生","example":"Poor drainage precipitated the collapse of the embankment.","exampleCN":"排水不良加速了堤岸的崩塌。","why":"This is the same causal push as the previous sense, but the focus is on speed rather than suddenness.","whyCN":"这与上一个义项是同一种因果推力，只是焦点在速度而非突然性。"},{"no":"05","title":"Hasty or rash","titleCN":"仓促的；鲁莽的","definition":"done too quickly, without proper thought","definitionCN":"做得过快、缺乏周全考虑的","example":"They regretted their precipitate sale of the land.","exampleCN":"他们后悔仓促卖掉了那块地。","why":"An adjective born from 'headlong': a person who acts this way is diving before looking.","whyCN":"这个形容词出自「头朝下」：这样行事的人还没看清就往下栽。"},{"no":"06","title":"The solid deposit","titleCN":"沉淀下来的固体","definition":"the solid substance produced by precipitation, used as a noun","definitionCN":"沉淀过程产生的固体物质，作名词使用","example":"Filter off the precipitate and wash it twice.","exampleCN":"把沉淀物滤出并洗涤两次。","why":"The process and its product share one form: what has been thrown down is the precipitate.","whyCN":"过程与产物共用一个形式：被抛下来的东西就是 precipitate。"},{"no":"07","title":"Throw down headlong","titleCN":"使头朝下坠落","definition":"in older writing, to throw a person or thing down from a height","definitionCN":"在旧时文本中，把人或物从高处抛下","example":"The old account says the guards precipitated him from the tower.","exampleCN":"旧记载说卫兵把他从塔上抛了下去。","why":"This literal bodily sense is the source of all the others and now survives mainly in historical writing.","whyCN":"这个字面的身体义是其余义项的源头，如今主要保存在历史文本中。"},{"no":"08","title":"Fall as rain or snow","titleCN":"以雨或雪的形式降落","definition":"of water, to fall from the sky as rain, snow or hail","definitionCN":"指水从天空以雨、雪或冰雹的形式落下","example":"Moist air rose, cooled, and began to precipitate over the hills.","exampleCN":"湿空气抬升、冷却，开始在山丘上空降水。","why":"The meteorological use keeps the literal falling but drops the human agent; the sky itself is the thrower.","whyCN":"气象用法保留了字面的落下，却去掉了人的施动者；抛落者变成了天空本身。"}],"etymology":{"intro":{"en":"Precipitate came into English from Latin as a learned word and then split into chemical and everyday uses. Dates are approximate.","cn":"precipitate 作为学术词从拉丁语进入英语，随后分出化学义与日常义。年代为大致估计。"},"items":[{"era":"CLASSICAL LATIN","en":"Latin praecipitare meant 'to throw down headlong, to hasten', with the participle praecipitatus 'thrown down'.","cn":"拉丁语 praecipitare 意为「头朝下抛落、加速促成」，分词为 praecipitatus「被抛下的」。"},{"era":"LATIN STRUCTURE","en":"The verb is prae- 'before, forth' plus caput 'head'. A person or thing goes over an edge and falls head first.","cn":"该动词是 prae-「在前、向前」加 caput「头」。人或物越过边缘，头朝下坠落。"},{"era":"MIDDLE ENGLISH (15c)","en":"Alchemy and medicine borrowed the word for a substance settling out of a liquid, since the solid seemed to fall out of the solution.","cn":"炼金术与医学借这个词指物质从液体中沉降出来，因为固体看起来像是从溶液里掉了出来。"},{"era":"EARLY MODERN ENGLISH (16c–17c)","en":"The adjective developed the sense 'hasty, rash', judging conduct by the same headlong image.","cn":"形容词发展出「仓促、鲁莽」义，用同一个头朝下的意象来评判行为。"},{"era":"MODERN ENGLISH (19c–20c)","en":"Chemistry fixed the verb and noun for solid formation, while journalism kept the sense of causing an event too soon.","cn":"十九至二十世纪，化学把这个动词与名词固定为固体析出义，新闻写作则保留了「使事件过早发生」的用法。"}]},"similar":{"note":{"en":"Group one separates the look-alikes, including two true relatives; group two holds verbs with overlapping meanings.","cn":"第一组分辨形近词，其中两个是真正的同族词；第二组是意义重叠的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"participate","ipa":"/ˌpɑːtɪsɪˈpeɪt/","tag":"unrelated","definition":"To take part. It goes back to Latin particeps 'sharing', with a different root; only the ending sounds similar.","definitionCN":"参加。它追溯到拉丁语 particeps「分享」，词根不同；只有词尾听起来相近。"},{"word":"precipitous","ipa":"/prɪˈsɪpɪtəs/","tag":"same family, adjective","definition":"Very steep, or done with too much haste. It is a true relative, so the -ous ending marks an adjective, not a verb.","definitionCN":"陡峭的，或过于仓促的。它是真正的同族词，-ous 词尾表示形容词而不是动词。"},{"word":"precipice","ipa":"/ˈpresɪpɪs/","tag":"same family, noun","definition":"A cliff or a dangerous position. It is a true relative from Latin praecipitium, and it names the edge rather than the fall.","definitionCN":"悬崖或险境。它是出自拉丁语 praecipitium 的真正同族词，指边缘而不是坠落。"}]},{"heading":"NEAR MEANING","entries":[{"word":"hasten","ipa":"/ˈhæstn/","tag":"speed up","definition":"To make something happen sooner; it stresses speed and carries no idea of falling.","definitionCN":"使某事更早发生；强调速度，不含坠落的意象。"},{"word":"trigger","ipa":"/ˈtrɪɡə/","tag":"set off","definition":"To cause an event to begin, usually a sudden reaction; it images a catch being released, not a body falling.","definitionCN":"引发事件开始，通常指突然反应；意象是扳机被松开，而不是身体坠落。"},{"word":"deposit","ipa":"/dɪˈpɒzɪt/","tag":"solid left behind","definition":"Material that has settled or been left on a surface; it can be the result of precipitation but is not the chemical process itself.","definitionCN":"沉降或留在表面上的物质；可以是沉淀的结果，但不指化学过程本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin pieces and real chemistry usage, no invented links.","cn":"正常联想：使用真实的拉丁构件与真实的化学用法，不编造联系。"},"normal":[{"en":"prae- 'before' + capit- 'head': the word pictures someone diving over an edge, head first.","cn":"prae-「在前」+ capit-「头」：这个词描绘一个人越过边缘、头朝下栽下去。"},{"en":"precipitate is both verb and noun in chemistry: the reagent precipitates the solid, and the solid is the precipitate.","cn":"precipitate 在化学里既是动词又是名词：试剂把固体沉淀出来，那个固体就是沉淀物。"},{"en":"precipitation is the noun of the process, built with -ation, exactly like preparation and evaporation.","cn":"precipitation 是用 -ation 构成的过程名词，与 preparation、evaporation 完全同构。"},{"en":"precipitous keeps the same root but describes a cliff, so steepness and haste are two readings of 'headlong'.","cn":"precipitous 保留同一词根却形容悬崖，于是「陡」与「急」是 headlong 的两种读法。"},{"en":"a precipitate decision is a decision made as if falling: fast, uncontrolled, hard to stop.","cn":"a precipitate decision 是像坠落一样做出的决定：快、失控、难停住。"}],"abstract":[{"en":"Abstractly, precipitate is any force that removes something from a suspended state: a reagent, a border incident, a bad decision.","cn":"抽象地看，precipitate 是任何把某物从悬浮状态中移除的力：一滴试剂、一起边境事件、一个糟糕的决定。"},{"en":"The common shape is a threshold crossed too fast, after which the thing can no longer stay where it was.","cn":"共同的形状是一个被过快越过的门槛，越过之后，那东西再也留不在原处。"},{"en":"So the word moves between beakers, calendars and personalities without changing its geometry: over the edge, head first.","cn":"于是这个词在烧杯、日历与性格之间移动，而几何不变：越过边缘，头朝下。"}]},"examples":[{"en":"Cooling the mixture will precipitate the dissolved crystals.","cn":"让混合物冷却会使溶解的晶体沉淀出来。"},{"en":"The announcement precipitated a sharp fall in the currency.","cn":"这项声明导致货币急剧下跌。"},{"en":"It was a precipitate move that no one had time to review.","cn":"那是一个谁都没时间复核的仓促举动。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"拆读「pre-（前）+ cipit（头）」：头朝前栽下去 → precipitate 使沉淀、使骤然发生","word":"precipitate"},"root":"拉丁语 praecipitare「头朝下抛落；加速」← prae-「向前」+ caput「头」；分词 praecipitatus 进入英语为 precipitate，与 precipitation、precipice、precipitous 同族。","sensesIntro":{"en":"Eight senses keep one motion: something goes over an edge. It happens in a beaker as a solid, in a solution as a settling, in history as a sudden event, in a schedule as haste, in grammar as an adjective, a noun and finally as falling weather.","cn":"八个义项保留同一个动作：某物越过边缘。它在烧杯里成为固体，在溶液里成为沉降，在历史中成为突发事件，在日程上成为加速，在语法上成为形容词与名词，最后成为落下的天气。"},"semanticMap":{"core":{"en":"CORE IMAGE: a substance held in suspension suddenly crosses a threshold and falls out.","cn":"核心意象：悬浮着的物质忽然越过一个门槛，掉了出来。"},"chain":["MIXED SOLUTION","SOLID FORMS","DEPOSIT SETTLES","SUDDEN EVENT","RASH JUDGEMENT","FALLING WATER"],"branches":[{"senses":"01 · 02","en":"CHEMISTRY, ACTIVE AND PASSIVE: an agent can throw the solid down, or the solid can fall by itself.","cn":"化学的主动与被动：可以由试剂把固体抛下，也可以由固体自己落下。"},{"senses":"03 · 04","en":"TIME PUSHED FORWARD: an event is brought into the present, either abruptly or merely faster.","cn":"时间被向前推：事件被拉进现在，或骤然发生，或只是更快。"},{"senses":"05","en":"CHARACTER: a mind that dives before looking is called precipitate.","cn":"性格：还没看清就往下扎的心智，被叫作 precipitate。"},{"senses":"06","en":"PRODUCT: what has fallen out is a deposit with a name of its own.","cn":"产物：落出来的东西是一个有自己名字的沉淀物。"},{"senses":"07 · 08","en":"THE LITERAL FALL: a body thrown from a height, and water thrown down by the sky.","cn":"字面坠落：被从高处抛下的身体，以及被天空抛下的水。"}]},"affixes":{"intro":{"en":"Precipitate carries the Latin pieces prae- and capit-. English then adds -ation, -ous, -ice, -ant and -or to build the rest of the family.","cn":"precipitate 带着拉丁构件 prae- 与 capit-。英语再加 -ation、-ous、-ice、-ant、-or 构成其余词族。"},"latinIntro":{"en":"The Latin entries are recorded forms of the family; the base noun caput is given because it explains why 'headlong' is inside every derivative.","cn":"下面的拉丁条目是该词族有记录的形式；列出基础名词 caput，是因为它解释了为什么每个派生词里都藏着「头朝下」。"},"items":[{"word":"precipitation","structure":"praecipitare + -ation (process noun)","meaning":"the process of falling, or of a solid forming","meaningCN":"降落的过程；固体析出的过程（-ation 构成过程名词）","example":"Precipitation removes the metal from the wastewater.","exampleCN":"沉淀法把金属从废水中去除。"},{"word":"precipitous","structure":"praeceps + -ous (full of)","meaning":"very steep; also rash","meaningCN":"极陡的；也有仓促义（-ous 表示「充满……」）","example":"The trail turned precipitous after the ridge.","exampleCN":"过了山脊之后，小路变得陡峭。"},{"word":"precipice","structure":"praecipitium (steep place)","meaning":"a cliff face or a dangerous brink","meaningCN":"悬崖；危险的边缘","example":"One more step would take him over the precipice.","exampleCN":"再走一步他就会跌下悬崖。"},{"word":"precipitant","structure":"precipitate + -ant (agent)","meaning":"a reagent that makes a solid settle out","meaningCN":"使固体沉降的沉淀剂（-ant 表示施动者）","example":"Alum is a common precipitant in water treatment.","exampleCN":"明矾是水处理中常见的沉淀剂。"},{"word":"precipitator","structure":"precipitate + -or (instrument)","meaning":"an apparatus that collects particles from a gas","meaningCN":"从气体中捕集颗粒的器具（-or 表示器具）","example":"The precipitator removes dust from the smokestack.","exampleCN":"除尘器把烟囱里的粉尘除掉。"},{"word":"precipitate out","structure":"precipitate + out (phrasal verb)","meaning":"to separate from a solution and settle","meaningCN":"从溶液中析出并沉降（out 表示「出来」）","example":"The crystals precipitate out when the solution cools.","exampleCN":"溶液冷却时晶体会析出。"},{"word":"precipitation reaction","structure":"precipitation + reaction","meaning":"a reaction whose product is an insoluble solid","meaningCN":"产物为不溶固体的沉淀反应","example":"A precipitation reaction produced the blue solid.","exampleCN":"一个沉淀反应生成了蓝色固体。"},{"word":"precipitately","structure":"precipitate + -ly (adverb)","meaning":"in a hasty, headlong way","meaningCN":"仓促地；鲁莽地（-ly 构成副词）","example":"He left precipitately before the vote.","exampleCN":"投票前他仓促离开了。"}],"latinEntries":[{"word":"praecipitare","structure":"prae- + caput (head)","meaning":"to throw down headlong; to hasten","meaningCN":"头朝下抛落；加速促成"},{"word":"praecipitatus","structure":"past participle of praecipitare","meaning":"thrown down headlong","meaningCN":"被头朝下抛下的"},{"word":"praeceps","structure":"prae- + caput","meaning":"headlong, steep, rash","meaningCN":"头朝下的；陡峭的；鲁莽的"},{"word":"caput","structure":"root noun, stem capit-","meaning":"head","meaningCN":"头"}]}},{"word":"rainfall","ipa_uk":"/ˈreɪnfɔːl/","ipa_us":"/ˈreɪnfɔːl/","definition_zh":"降雨；降雨量；一场雨","definition_en":"rain falling from the sky, or the amount of rain measured over a period","core_image":"云底压得很低，雨线密密地垂到地面，量筒里的水一寸寸升高","scene":"雨下了一整夜，气象站的量筒里积起半尺深的水。Heavy rainfall overnight raised the water in the gauge by half a foot.","sceneCN":"这里该词指「落下的雨水」（第 1 个义项：降雨这一事件）；句意为夜间的大雨使量筒里的水升高了半英尺。","pos":[{"tag":"n.","zh":"降雨；降雨量；（一场）雨"}],"collocations":[{"phrase":"annual rainfall","zh":"年降雨量"},{"phrase":"heavy rainfall","zh":"强降雨；大雨"},{"phrase":"average rainfall","zh":"平均降雨量"},{"phrase":"low rainfall","zh":"降雨稀少"},{"phrase":"rainfall totals","zh":"降雨总量"},{"phrase":"a season of abundant rainfall","zh":"雨水充沛的季节"}],"forms":[{"label":"不可数用法（总量）","form":"rainfall（通常不可数）"},{"label":"复数（多场降雨或多次读数）","form":"rainfalls"},{"label":"组成词一","form":"rain（雨）"},{"label":"组成词二","form":"fall（落下）"},{"label":"同义学术说法","form":"precipitation（降水）"}],"derivatives":[{"word":"rain","pos":"n./v.","zh":"雨；下雨"},{"word":"rainy","pos":"adj.","zh":"多雨的"},{"word":"rainfall pattern","pos":"n.","zh":"降雨格局"},{"word":"rainfall total","pos":"n.","zh":"降雨总量"},{"word":"precipitation","pos":"n.","zh":"降水（涵盖雨雪冰雹）"}],"senses":[{"no":"01","title":"Rain coming down","titleCN":"雨正在落下","definition":"the fall of rain from clouds","definitionCN":"雨从云中落下这一事件","example":"Heavy rainfall overnight raised the water in the gauge by half a foot.","exampleCN":"夜间的大雨使量筒里的水升高了半英尺。","why":"Rain plus fall names the event directly: the first element is the substance, the second is its motion.","whyCN":"rain 加 fall 直接命名事件：前者是物质，后者是它的运动。"},{"no":"02","title":"The measured depth","titleCN":"测得的雨量深度","definition":"the depth of rain that has fallen, measured in millimetres or inches","definitionCN":"已经落下的雨的深度，以毫米或英寸计","example":"The city recorded forty millimetres of rainfall in one hour.","exampleCN":"这座城市一小时内记录到四十毫米降雨量。","why":"A gauge converts a shower into a depth, and the compound takes on that measured reading.","whyCN":"量筒把一场雨变成一段深度，这个复合词也就承担了这一读数。"},{"no":"03","title":"The yearly total","titleCN":"全年降雨总量","definition":"the total rain a place receives in a year","definitionCN":"某地一年所获得的总雨量","example":"The island's annual rainfall supports dense forest.","exampleCN":"这座岛的年降雨量足以养活茂密的森林。","why":"Climate description needs a period, so rainfall becomes an annual figure rather than a single storm.","whyCN":"气候描述需要一个周期，于是 rainfall 成为年度数字，而不是一场暴雨。"},{"no":"04","title":"A season's rain","titleCN":"某一季的雨水","definition":"the rain belonging to a particular season or month","definitionCN":"属于某个季节或月份的雨","example":"Most of the region's rainfall arrives between June and September.","exampleCN":"该地区大部分降雨集中在六月到九月之间。","why":"Once totals are grouped by month, the word also names the rain attached to a stretch of the calendar.","whyCN":"一旦总量按月分组，这个词也指附着在某段日历上的雨水。"},{"no":"05","title":"Water supply for farming","titleCN":"农业依赖的雨水来源","definition":"rain considered as the water source for crops and pastures","definitionCN":"被视为作物与牧场水源的雨水","example":"Dry farming depends entirely on natural rainfall.","exampleCN":"旱作农业完全依赖自然降雨。","why":"For a farmer, rain is not weather but input; the word shifts from the sky to the water budget.","whyCN":"对农民来说，雨不是天气而是投入；这个词于是从天空转到水量收支。"},{"no":"06","title":"Liquid precipitation as a category","titleCN":"作为类别的液态降水","definition":"in climate science, the liquid form of precipitation as opposed to snow","definitionCN":"气候科学中与降雪相对的液态降水","example":"The model separates rainfall from snowfall in mountain zones.","exampleCN":"模型在山地分区中把降雨与降雪分开处理。","why":"Classification needs a label for the liquid member, and rainfall supplies it.","whyCN":"分类需要给液态成员一个标签，rainfall 提供了这个标签。"},{"no":"07","title":"Rain in a particular place","titleCN":"某地特有的雨水","definition":"the characteristic rain of a named region, as in tropical or coastal rainfall","definitionCN":"某一特定地区的典型雨水，如热带或沿海降雨","example":"Coastal rainfall keeps the valleys green long into summer.","exampleCN":"沿海降雨让山谷一直绿到盛夏。","why":"Place adjectives attach naturally, because rain is one of the first things people notice about a region.","whyCN":"地点形容词自然附着其上，因为雨是人最先注意到的地方特征之一。"},{"no":"08","title":"Rain produced by cloud seeding","titleCN":"人工增雨产生的降雨","definition":"rain that has been encouraged to fall by human intervention","definitionCN":"经人工干预而促使其落下的雨","example":"The province counts on seeded rainfall during drought years.","exampleCN":"该省在干旱年份依靠人工增雨。","why":"When people can trigger the fall, the same noun names the product of an intervention.","whyCN":"当人能触发这场落下时，同一个名词也指干预的产物。"}],"etymology":{"intro":{"en":"Rainfall is a modern English compound of two native Old English words. The compound itself is recent, while both halves are ancient. Dates are approximate.","cn":"rainfall 是由两个英语本土的古英语词构成的现代复合词。复合词本身很新，两个构件却很古老。年代为大致估计。"},"items":[{"era":"OLD ENGLISH","en":"Rain goes back to Old English regn, from Proto-Germanic *regna-, a word shared by most Germanic languages.","cn":"rain 源自古英语 regn，出自原始日耳曼语 *regna-，为多数日耳曼语言共有。"},{"era":"OLD ENGLISH","en":"Fall goes back to Old English feallan 'to fall', from Proto-Germanic *fallan, and has always meant a downward movement.","cn":"fall 源自古英语 feallan「落下」，出自原始日耳曼语 *fallan，一直表示向下的运动。"},{"era":"MODERN ENGLISH (19c)","en":"The compound rainfall appears in nineteenth-century writing, when weather observation became systematic and totals needed a short name.","cn":"复合词 rainfall 出现于十九世纪文献，当时天气观测走向系统化，总量需要一个简短名称。"},{"era":"MODERN ENGLISH (mid-19c)","en":"Rain gauges and agricultural yearbooks spread the measured sense, so that a place could be described by how much rainfall it received rather than by how often it rained.","cn":"雨量筒与农业年鉴推广了测量义，于是描述一个地方可以靠它接收多少降雨量，而不是靠下雨的次数。"},{"era":"MODERN ENGLISH (20c)","en":"The measured sense expanded with national weather services and the phrase annual rainfall became standard in geography textbooks.","cn":"随着国家气象机构的建立，其测量义扩展，annual rainfall 成为地理教科书的固定说法。"}]},"similar":{"note":{"en":"Group one holds compounds built on the same word rain; group two holds words for water falling in other ways.","cn":"第一组是以同一个 rain 构成的复合词；第二组是表示水以其他方式落下的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"raindrop","ipa":"/ˈreɪndrɒp/","tag":"same family","definition":"A single drop of rain; it names one piece, while rainfall names the whole event or total.","definitionCN":"一滴雨；它指单个水滴，而 rainfall 指整个事件或总量。"},{"word":"rainbow","ipa":"/ˈreɪnbəʊ/","tag":"same family","definition":"The coloured arc seen when sunlight passes through drops; it is a sight caused by rain, not the rain itself.","definitionCN":"阳光穿过水滴时看到的彩色弧；它是雨造成的景象，而不是雨本身。"},{"word":"rainstorm","ipa":"/ˈreɪnstɔːm/","tag":"same family","definition":"A storm with heavy rain; it adds the idea of wind and violence that rainfall does not carry.","definitionCN":"夹带大雨的风暴；它多了风与猛烈之意，而 rainfall 没有这层意思。"}]},{"heading":"NEAR MEANING","entries":[{"word":"precipitation","ipa":"/ˌpresɪpɪˈteɪʃn/","tag":"all forms","definition":"Falling water of every kind, including snow and hail; it is the technical category to which rainfall belongs.","definitionCN":"各种形式落下的水，包括雪与冰雹；它是 rainfall 所属的技术类别。"},{"word":"drizzle","ipa":"/ˈdrɪzl/","tag":"light rain","definition":"Very light rain made of tiny drops; it describes an intensity, not an amount over a season.","definitionCN":"由细小水滴构成的毛毛雨；它描述强度，而非一段时间内的总量。"},{"word":"downpour","ipa":"/ˈdaʊnpɔː/","tag":"heavy rain","definition":"A sudden heavy fall of rain; it stresses the burst, while rainfall can be calm and cumulative.","definitionCN":"突然而降的大雨；它强调爆发，而 rainfall 可以是平缓累积的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the compound is transparent, and its partners are real weather terms.","cn":"正常联想：这个复合词的意义一目了然，搭配也都是真实的天气术语。"},"normal":[{"en":"rain + fall: the substance plus its motion, exactly like snowfall and moonlight.","cn":"rain + fall：物质加运动，与 snowfall、moonlight 完全同构。"},{"en":"rainfall total is the phrase used when the event is converted into a number.","cn":"rainfall total 是把事件换算成数字时使用的搭配。"},{"en":"annual rainfall is the standard geography phrase for a place's yearly water supply.","cn":"annual rainfall 是地理学中描述某地年度水量的标准说法。"},{"en":"rainfall and snowfall split the same idea by temperature, and precipitation is the umbrella term.","cn":"rainfall 与 snowfall 按温度把同一想法分开，precipitation 则是统称。"},{"en":"rain gauge is the instrument that turns rainfall into a reading, pairing the compound with its tool.","cn":"rain gauge 是把 rainfall 变成读数的仪器，把这个复合词与工具配在一起。"}],"abstract":[{"en":"Abstractly, rainfall is water leaving the sky on a schedule no one controls; the compound names both the leaving and the amount left behind.","cn":"抽象地看，rainfall 是按无人能控制的日程离开天空的水；这个复合词同时命名离开与留下的量。"},{"en":"The same word can be a moment (a heavy fall) or a decade (an annual average), because a gauge can measure either.","cn":"同一个词既可是一刻（一场大雨），也可是十年（年均值），因为量筒两者都能测。"},{"en":"So rainfall is rain viewed as supply: something that arrives, accumulates and must be counted.","cn":"所以 rainfall 是把雨看作供给：它到来、累积，并且必须被计量。"}]},"examples":[{"en":"The northern slope receives twice the rainfall of the southern slope.","cn":"北坡的降雨量是南坡的两倍。"},{"en":"A week of steady rainfall replenished the reservoirs.","cn":"一周持续的降雨补足了水库。"},{"en":"Gardeners time their planting by the expected rainfall.","cn":"园丁按预期的降雨安排种植时间。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"rain（雨）+ fall（落下）：雨从天上落下来 → rainfall 降雨、降雨量","word":"rainfall"},"root":"rain 源自古英语 regn（原始日耳曼语 *regna-），fall 源自古英语 feallan（原始日耳曼语 *fallan）；复合词 rainfall 于十九世纪出现。","sensesIntro":{"en":"Eight senses follow water from sky to ledger: the event of falling, the depth measured, the yearly total, the seasonal share, the farm supply, the liquid category, the regional character and the artificially seeded shower.","cn":"八个义项让水从天空走到账本：落下的事件、测得的深度、全年总量、季节份额、农业供给、液态类别、地方特征以及人工催下的雨。"},"semanticMap":{"core":{"en":"CORE IMAGE: water leaves the sky and is caught, first as an event and then as a depth in a gauge.","cn":"核心意象：水离开天空并被接住，先是一个事件，然后成为量筒里的一段深度。"},"chain":["FALLING EVENT","MEASURED DEPTH","SEASONAL SHARE","YEARLY TOTAL","WATER SUPPLY","LIQUID CATEGORY"],"branches":[{"senses":"01 · 02","en":"EVENT AND READING: the shower and the number it leaves in the gauge are one noun.","cn":"事件与读数：一场雨与它在量筒里留下的数字共用一个名词。"},{"senses":"03 · 04","en":"CALENDAR: grouped by season or by year, rain becomes a schedule.","cn":"日历：按季节或按年份分组，雨就变成一张时间表。"},{"senses":"05","en":"SUPPLY: for farming, the same water is an input in the budget.","cn":"供给：对农业而言，同一份水是收支表里的投入。"},{"senses":"06","en":"CATEGORY: climate science sets the liquid member beside snow.","cn":"类别：气候科学把液态成员与雪并列。"},{"senses":"07 · 08","en":"PLACE AND INTERVENTION: rain belongs to a region, and can also be made to fall.","cn":"地方与干预：雨属于某个地区，也可以被人为催下。"}]},"affixes":{"intro":{"en":"Rainfall is a native compound, so its family grows by compounding rather than by Latin suffixes: rain + drop, bow, coat, storm, water and gauge.","cn":"rainfall 是英语本土复合词，其词族靠复合而非拉丁后缀扩展：rain 加 drop、bow、coat、storm、water、gauge。"},"latinIntro":{"en":"Both halves are Germanic, with no Latin ancestor; the Latin entry list is empty on purpose.","cn":"两个构件都属日耳曼语，没有拉丁语祖先；拉丁词条列表按设计留空。"},"items":[{"word":"raindrop","structure":"rain + drop","meaning":"a single drop of rain","meaningCN":"一滴雨","example":"A raindrop splashed on the hot stone.","exampleCN":"一滴雨落在滚烫的石头上溅开了。"},{"word":"rainbow","structure":"rain + bow (arched shape)","meaning":"the coloured arc formed by sunlight in raindrops","meaningCN":"阳光在雨滴中形成的彩色弧（bow 指弓形）","example":"A rainbow rose over the wet field.","exampleCN":"湿漉漉的田野上升起一道彩虹。"},{"word":"raincoat","structure":"rain + coat","meaning":"a waterproof coat worn in rain","meaningCN":"雨天穿的防水外套","example":"He folded his raincoat into the bag.","exampleCN":"他把雨衣折好放进包里。"},{"word":"rainstorm","structure":"rain + storm","meaning":"a storm accompanied by heavy rain","meaningCN":"伴随大雨的风暴","example":"The rainstorm closed the mountain road.","exampleCN":"暴雨封住了山路。"},{"word":"rainwater","structure":"rain + water","meaning":"water that has fallen as rain, often collected for use","meaningCN":"落下的雨水，常被收集利用","example":"The barrel stores rainwater for the garden.","exampleCN":"桶里存着浇园用的雨水。"},{"word":"rain gauge","structure":"rain + gauge","meaning":"an instrument that measures rainfall","meaningCN":"测量降雨量的仪器","example":"The rain gauge was read at dawn.","exampleCN":"雨量筒在黎明时读数。"},{"word":"rainfall total","structure":"rainfall + total","meaning":"the summed rainfall over a period","meaningCN":"一段时间内累计的降雨总量","example":"The monthly rainfall total broke a record.","exampleCN":"月降雨总量破了纪录。"},{"word":"acid rain","structure":"acid + rain","meaning":"rain made acidic by dissolved pollutants","meaningCN":"因溶解污染物而呈酸性的雨，即酸雨","example":"Acid rain stripped the leaves from the trees.","exampleCN":"酸雨把树叶打落了。"}],"latinEntries":[]}},{"word":"rainfall pattern","ipa_uk":"/ˈreɪnfɔːl ˈpætən/","ipa_us":"/ˈreɪnfɔːl ˈpætərn/","definition_zh":"降雨格局；降水分布型；雨季规律","definition_en":"the way rain is distributed across a region or through the year","core_image":"同一座山谷，东坡湿绿、西坡枯黄，界线年复一年都落在同一处","scene":"同一座山谷里，东坡多雨、西坡少雨，这一分别年年如此。The rainfall pattern of the valley has stayed the same for decades.","sceneCN":"这里该词指「降雨在空间上的固定分布」（第 1 个义项：一个地区内雨量分布的方式）；句意为这座山谷的降雨格局几十年来一直未变。","pos":[{"tag":"n.","zh":"降雨格局；降水分布型；雨季规律"}],"collocations":[{"phrase":"seasonal rainfall pattern","zh":"季节性降雨格局"},{"phrase":"a shift in the rainfall pattern","zh":"降雨格局的变化"},{"phrase":"regional rainfall pattern","zh":"区域降雨格局"},{"phrase":"annual rainfall pattern","zh":"年度降雨格局"},{"phrase":"the rainfall pattern of the tropics","zh":"热带地区的降雨格局"},{"phrase":"changing rainfall patterns","zh":"不断变化的降雨格局"}],"forms":[{"label":"单数","form":"rainfall pattern（一种格局）"},{"label":"复数","form":"rainfall patterns（多种格局）"},{"label":"组成词一","form":"rainfall（降雨；降雨量）"},{"label":"组成词二","form":"pattern（模式；格局）"},{"label":"同义学术说法","form":"precipitation pattern（降水格局）"}],"derivatives":[{"word":"rainfall","pos":"n.","zh":"降雨；降雨量"},{"word":"pattern","pos":"n./v.","zh":"模式；格局 / 形成图案"},{"word":"precipitation pattern","pos":"n.","zh":"降水格局"},{"word":"rainfall distribution","pos":"n.","zh":"降雨分布"},{"word":"rainfall regime","pos":"n.","zh":"降雨情势；降雨型"}],"senses":[{"no":"01","title":"Rain spread across a region","titleCN":"雨量在一个地区内的分布","definition":"the way rain is unevenly distributed over a landscape","definitionCN":"雨水在一片地景上不均匀分布的方式","example":"The rainfall pattern of the valley has stayed the same for decades.","exampleCN":"这座山谷的降雨格局几十年来一直未变。","why":"Pattern here means a repeated arrangement, and rainfall supplies what is arranged: the two words together describe geography.","whyCN":"这里的 pattern 指重复出现的排列，rainfall 提供被排列的东西：两个词合起来描述地理。"},{"no":"02","title":"Rain timed through the seasons","titleCN":"雨在四季中的时间分配","definition":"the timing of rain across the seasons of a year","definitionCN":"一年四季中雨水出现的时间安排","example":"The seasonal rainfall pattern brings a short wet season and a long dry one.","exampleCN":"这种季节性降雨格局带来一个短雨季和一个长旱季。","why":"When the arrangement is in time rather than space, the same phrase describes a calendar of wet and dry months.","whyCN":"当排列发生在时间而非空间上，同一短语就描述湿月与干月的日历。"},{"no":"03","title":"The monthly curve","titleCN":"逐月降雨曲线","definition":"the shape of monthly rainfall totals plotted over a year","definitionCN":"一年内逐月降雨总量绘出的形状","example":"The station's rainfall pattern peaks in July and bottoms out in January.","exampleCN":"该站的降雨格局在七月达到峰值，在一月降到最低。","why":"Drawn on a chart, the arrangement becomes a curve with peaks and troughs, and the word pattern fits exactly.","whyCN":"画到图上，这种排列变成有峰有谷的曲线，pattern 一词正好贴合。"},{"no":"04","title":"A climate classification clue","titleCN":"气候分类的依据","definition":"the distribution of rain used to define a climate type","definitionCN":"用来界定某种气候类型的雨水分布","example":"A summer rainfall pattern separates this zone from the Mediterranean coast.","exampleCN":"夏季降雨格局把这一带与地中海沿岸区分开。","why":"Climate types are defined by when rain comes, so the pattern becomes diagnostic rather than descriptive.","whyCN":"气候类型由雨何时来界定，于是这种格局成了诊断依据而不只是描述。"},{"no":"05","title":"A long-term shift","titleCN":"长期的格局改变","definition":"a change in the established distribution of rain over decades","definitionCN":"几十年间既定雨水分布所发生的变化","example":"Farmers report a shifting rainfall pattern that delays the planting season.","exampleCN":"农民反映降雨格局正在变化，使播种季推迟。","why":"A pattern is expected to repeat; when it stops repeating, the phrase itself carries the news of change.","whyCN":"格局本应重复；当它不再重复时，这个短语本身就承载了变化的消息。"},{"no":"06","title":"A regional comparison","titleCN":"区域之间的对比","definition":"the difference in rain distribution between two places","definitionCN":"两地之间雨水分布的差异","example":"The coastal and inland rainfall patterns differ by a factor of three.","exampleCN":"沿海与内陆的降雨格局相差三倍。","why":"Two places can be held side by side, and their arrangements compared as two patterns.","whyCN":"两个地方可以并排摆开，把各自的排列当作两种格局来比较。"},{"no":"07","title":"A guide for planting","titleCN":"安排农事的依据","definition":"the expected rain distribution used to plan crops and irrigation","definitionCN":"用来安排作物与灌溉的预期雨水分布","example":"Growers choose their varieties by the local rainfall pattern.","exampleCN":"种植者按当地降雨格局选择品种。","why":"Once the arrangement is known to repeat, it becomes a planning tool rather than a curiosity.","whyCN":"一旦知道这种排列会重复，它就变成规划工具，而不只是趣闻。"},{"no":"08","title":"A mapped or charted shape","titleCN":"地图或图表上的形态","definition":"the visual shape of rain distribution on a map or graph","definitionCN":"降雨分布在地图或图表上呈现的可见形状","example":"The atlas shows the rainfall pattern as bands of colour.","exampleCN":"地图册用色带显示出降雨格局。","why":"Pattern also means a visible design, so a map of isohyets is literally a rainfall pattern.","whyCN":"pattern 也指可见的图案，所以等雨量线地图字面上就是一幅降雨图案。"}],"etymology":{"intro":{"en":"The phrase joins a nineteenth-century weather compound with a much older word for a model. Dates are approximate.","cn":"这个短语把十九世纪的天气复合词与一个古老得多的「范型」词结合在一起。年代为大致估计。"},"items":[{"era":"OLD ENGLISH","en":"Rain and fall are native Germanic words: regn 'rain' and feallan 'to fall'.","cn":"rain 与 fall 是本土日耳曼词：regn「雨」与 feallan「落下」。"},{"era":"MODERN ENGLISH (19c)","en":"Rainfall was coined when weather stations began recording totals and needed a compact term.","cn":"rainfall 在气象站开始记录总量、需要一个简短术语时被造出。"},{"era":"OLD FRENCH (12c–13c)","en":"Pattern came from Old French patron, meaning a model or an example to be copied.","cn":"pattern 来自古法语 patron，意为可供模仿的范型或样板。"},{"era":"CLASSICAL LATIN","en":"Old French patron goes back to Latin patronus 'protector, patron', from pater 'father'. The sense 'model' grew through the idea of a patron as an exemplar.","cn":"古法语 patron 追溯到拉丁语 patronus「保护人、赞助人」，出自 pater「父亲」。「范型」义经由「赞助人是效仿对象」这一想法发展而来。"},{"era":"MODERN ENGLISH (20c)","en":"Climate science fixed rainfall pattern as the standard phrase for the distribution of rain in space and time.","cn":"二十世纪的气候科学把 rainfall pattern 固定为描述雨水时空分布的标准短语。"}]},"similar":{"note":{"en":"Group one holds phrases with a neighbouring shape; group two holds other pattern phrases used in climate writing.","cn":"第一组是形式相近的短语；第二组是气候写作中其他 pattern 短语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"rainfall","ipa":"/ˈreɪnfɔːl/","tag":"single word","definition":"The rain itself or its total; without pattern it says nothing about distribution.","definitionCN":"雨本身或其总量；不带 pattern 时并不说明分布。"},{"word":"rain pattern","ipa":"/reɪn ˈpætən/","tag":"near phrase","definition":"An informal phrase for the rhythm of rain; the technical term prefers rainfall because it includes measured amounts.","definitionCN":"对雨水节奏的非正式说法；技术文献更常用 rainfall，因为它包含测得的量。"},{"word":"rainfall amount","ipa":"/ˈreɪnfɔːl əˈmaʊnt/","tag":"near phrase","definition":"A single quantity of rain; it answers how much, while pattern answers how it is arranged.","definitionCN":"单次的雨量；它回答「多少」，而 pattern 回答「如何分布」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"precipitation pattern","ipa":"/ˌpresɪpɪˈteɪʃn ˈpætən/","tag":"wider term","definition":"The distribution of all falling water, including snow; it is the umbrella term for rainfall pattern.","definitionCN":"包括雪在内一切降水的分布；它是 rainfall pattern 的统称。"},{"word":"climate pattern","ipa":"/ˈklaɪmət ˈpætən/","tag":"wider term","definition":"A recurring arrangement of temperature, wind and rain together, of which rain is only one part.","definitionCN":"温度、风与雨共同形成的重复排列，雨只是其中一部分。"},{"word":"seasonal distribution","ipa":"/ˈsiːzənl ˌdɪstrɪˈbjuːʃn/","tag":"time focus","definition":"How something is spread across the seasons; it names only the time axis, while the rainfall phrase can also cover space.","definitionCN":"某物在四季中的分布方式；它只涉时间轴，而降雨格局还可涵盖空间。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: both halves are transparent, and the compounds are real climate terms.","cn":"正常联想：两个构件意义清楚，搭配也都是真实的气候术语。"},"normal":[{"en":"rainfall + pattern: the first half is what moves, the second half is how it repeats.","cn":"rainfall + pattern：前半是移动的东西，后半是它重复的方式。"},{"en":"precipitation pattern replaces rainfall pattern when snow and hail must be included.","cn":"需要把雪与冰雹算进来时，用 precipitation pattern 替换 rainfall pattern。"},{"en":"seasonal rainfall pattern puts the pattern on the calendar, and regional rainfall pattern puts it on the map.","cn":"seasonal rainfall pattern 把格局放到日历上，regional rainfall pattern 把它放到地图上。"},{"en":"a shift in the rainfall pattern is the standard phrase in climate reports for a change in the usual distribution.","cn":"a shift in the rainfall pattern 是气候报告中表示常年分布发生改变的标准说法。"},{"en":"pattern itself means a repeated design, which is why the phrase needs no extra word for 'distribution'.","cn":"pattern 本身就有「重复图案」之意，所以这个短语不必另加表示「分布」的词。"}],"abstract":[{"en":"Abstractly, the phrase is a grid laid over a landscape, with a number of rain written into every cell.","cn":"抽象地看，这个短语是一张铺在地景上的网格，每一格里都写着一个雨量数字。"},{"en":"The grid can be turned sideways into a calendar, which is why space and time share one phrase.","cn":"这张网格可以侧过来变成日历，这正是空间与时间共用同一个短语的原因。"},{"en":"So the phrase is not rain and not pattern alone, but the repeatable arrangement of the two.","cn":"所以这个短语既不是雨，也不只是模式，而是两者可重复的排列关系。"}]},"examples":[{"en":"Deforestation can alter the rainfall pattern of an entire basin.","cn":"森林砍伐会改变整个流域的降雨格局。"},{"en":"The two islands share a latitude but not a rainfall pattern.","cn":"这两座岛纬度相同，降雨格局却不同。"},{"en":"Long records are needed to detect a change in the rainfall pattern.","cn":"要发现降雨格局的变化，需要长期记录。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"rainfall（降雨）+ pattern（图案）：把雨量画成一张图 → rainfall pattern 降雨格局","word":"rainfall pattern"},"root":"rainfall 为 rain（古英语 regn）与 fall（古英语 feallan）的现代复合词；pattern 经古法语 patron 出自拉丁 patronus「保护人、范型」。","sensesIntro":{"en":"Eight senses treat rain as an arrangement: across space, through seasons, along a monthly curve, as a climate clue, as a changing trend, as a regional contrast, as a farming guide and as a shape on a map.","cn":"八个义项把雨当作一种排列：在空间上、在四季中、在逐月曲线上、作为气候线索、作为变化趋势、作为区域对比、作为农事指南，以及作为地图上的形状。"},"semanticMap":{"core":{"en":"CORE IMAGE: a grid of rain values laid over a place and over a year, repeating the same shape.","cn":"核心意象：一张覆盖某地与某年的雨量网格，重复着同一个形状。"},"chain":["SPATIAL DIFFERENCE","SEASONAL RHYTHM","MONTHLY CURVE","CLIMATE CLUE","LONG-TERM SHIFT","PLAN AND MAP"],"branches":[{"senses":"01 · 06","en":"SPACE: the arrangement across a landscape and the contrast between two regions are the same grid read at two scales.","cn":"空间：一片地景上的排列与两个区域之间的对比，是同一张网格在两个尺度上的读法。"},{"senses":"02 · 03 · 04","en":"TIME: season, month and climate type all read the schedule of rain.","cn":"时间：季节、月份与气候类型都在读雨的时间表。"},{"senses":"05","en":"CHANGE: when the repetition fails, the pattern becomes news.","cn":"变化：当重复失效时，这种格局就成了新闻。"},{"senses":"07","en":"USE: a known pattern is a planning instrument for farmers.","cn":"用途：已知的格局是农民的规划工具。"},{"senses":"08","en":"IMAGE: the same arrangement drawn as bands on a map.","cn":"图像：同一种排列被画成地图上的色带。"}]},"affixes":{"intro":{"en":"The phrase is built from two families: rainfall compounds and pattern compounds. Its affix-style entries are therefore compounds and fixed collocations, not suffixes.","cn":"这个短语由两个词族构成：rainfall 系复合词与 pattern 系复合词。因此这里的词缀式条目是复合词与固定搭配，而不是后缀。"},"latinIntro":{"en":"Only pattern has a Latin line, through Old French patron from Latin patronus. Rainfall is wholly Germanic. The Latin entry below is the recorded ancestor.","cn":"只有 pattern 有拉丁线索：经古法语 patron 出自拉丁 patronus。rainfall 完全是日耳曼语。下面的拉丁条目是有记录的祖先。"},"items":[{"word":"seasonal rainfall pattern","structure":"seasonal + rainfall pattern","meaning":"the way rain is timed across the seasons","meaningCN":"雨在四季间的时间分布方式","example":"The seasonal rainfall pattern decides when rice is planted.","exampleCN":"季节性降雨格局决定何时插秧。"},{"word":"regional rainfall pattern","structure":"regional + rainfall pattern","meaning":"the distribution of rain within one region","meaningCN":"一个区域内部的雨水分布","example":"The regional rainfall pattern follows the mountain ridges.","exampleCN":"区域降雨格局沿着山脊展开。"},{"word":"rainfall distribution","structure":"rainfall + distribution","meaning":"the spread of rain over an area or period","meaningCN":"雨水在空间或时间上的分布","example":"Maps show the rainfall distribution month by month.","exampleCN":"地图逐月显示降雨分布。"},{"word":"rainfall regime","structure":"rainfall + regime","meaning":"the characteristic seasonal rain system of a place","meaningCN":"某地特有的季节性降雨情势","example":"The monsoon creates a summer rainfall regime.","exampleCN":"季风形成了夏季降雨型。"},{"word":"precipitation pattern","structure":"precipitation + pattern","meaning":"the distribution of all falling water, frozen forms included","meaningCN":"包含冻结形态在内的一切降水的分布","example":"The precipitation pattern includes both rain and snow.","exampleCN":"降水格局同时包含雨与雪。"},{"word":"weather pattern","structure":"weather + pattern","meaning":"a recurring arrangement of weather systems","meaningCN":"天气系统重复出现的排列","example":"A blocked weather pattern kept the storm in place.","exampleCN":"受阻的天气格局让风暴停在原地。"},{"word":"pattern shift","structure":"pattern + shift","meaning":"a change in a repeated arrangement","meaningCN":"重复排列所发生的变化","example":"The pattern shift showed up in the lake levels.","exampleCN":"格局变化在湖面水位上显现出来。"},{"word":"isohyet map","structure":"isohyet (equal-rain line) + map","meaning":"a map joining points of equal rainfall, the visual form of a rainfall pattern","meaningCN":"把雨量相同的点连起来的地图，是降雨格局的可视形态","example":"The isohyet map made the coastal band obvious.","exampleCN":"等雨量线地图让沿海那条带一目了然。"}],"latinEntries":[{"word":"patronus","structure":"pater 'father' → patronus","meaning":"protector, patron, model to be copied","meaningCN":"保护人；赞助人；可供效仿的范型"},{"word":"patron","structure":"Old French patron ← Latin patronus","meaning":"a supporter, or a model or pattern","meaningCN":"赞助人；范型、样板"}]}},{"word":"snowfall","ipa_uk":"/ˈsnəʊfɔːl/","ipa_us":"/ˈsnoʊfɔːl/","definition_zh":"降雪；降雪量；一场雪","definition_en":"snow falling from the sky, or the amount of snow that has fallen","core_image":"云层低垂，大片雪花静静落下，村口的木凳一点点被埋进白色","scene":"一夜大雪，村口的木凳被埋进厚厚一层白色。A heavy snowfall buried the bench outside the village gate.","sceneCN":"这里该词指「落下的雪」（第 1 个义项：降雪这一事件）；句意为一场大雪把村门外的木凳埋住了。","pos":[{"tag":"n.","zh":"降雪；降雪量；（一场）雪"}],"collocations":[{"phrase":"heavy snowfall","zh":"大雪；强降雪"},{"phrase":"annual snowfall","zh":"年降雪量"},{"phrase":"average snowfall","zh":"平均降雪量"},{"phrase":"record snowfall","zh":"创纪录的降雪"},{"phrase":"snowfall totals","zh":"降雪总量"},{"phrase":"a light snowfall","zh":"一场小雪"}],"forms":[{"label":"不可数用法（总量）","form":"snowfall（通常不可数）"},{"label":"复数（多场降雪或多次读数）","form":"snowfalls"},{"label":"组成词一","form":"snow（雪）"},{"label":"组成词二","form":"fall（落下）"},{"label":"同义学术说法","form":"precipitation（降水）"}],"derivatives":[{"word":"snow","pos":"n./v.","zh":"雪；下雪"},{"word":"snowy","pos":"adj.","zh":"多雪的；被雪覆盖的"},{"word":"snowfall total","pos":"n.","zh":"降雪总量"},{"word":"snowfall pattern","pos":"n.","zh":"降雪格局"},{"word":"precipitation","pos":"n.","zh":"降水（涵盖雨雪冰雹）"}],"senses":[{"no":"01","title":"Snow coming down","titleCN":"雪正在落下","definition":"the fall of snow from clouds","definitionCN":"雪从云中落下这一事件","example":"A heavy snowfall buried the bench outside the village gate.","exampleCN":"一场大雪把村门外的木凳埋住了。","why":"Snow plus fall states the substance and its motion, exactly parallel to rainfall.","whyCN":"snow 加 fall 点明物质与运动，与 rainfall 完全平行。"},{"no":"02","title":"The measured depth","titleCN":"测得的积雪深度","definition":"the depth of snow that has fallen, measured in centimetres or inches","definitionCN":"已经落下的雪的深度，以厘米或英寸计","example":"The station reported a snowfall of thirty centimetres.","exampleCN":"气象站报告降雪三十厘米。","why":"A ruler in an open field turns the event into a depth, and the compound carries that reading.","whyCN":"空地上的量尺把事件变成深度，这个复合词就承载这一读数。"},{"no":"03","title":"One bout of snow","titleCN":"一场降雪过程","definition":"a single continuous period of snow","definitionCN":"一段连续的降雪过程","example":"The morning snowfall stopped before noon.","exampleCN":"早晨那场雪在中午前停了。","why":"Weather writing needs to count separate events, so a countable snowfall becomes a bout with a beginning and an end.","whyCN":"天气写作需要数出一个个事件，于是可数的 snowfall 成为有始有终的一场。"},{"no":"04","title":"The season's total","titleCN":"整个雪季的总量","definition":"the total snow a place receives in a season or year","definitionCN":"某地一季或一年获得的总雪量","example":"The resort's seasonal snowfall exceeds four metres.","exampleCN":"这个度假地的季度降雪超过四米。","why":"For a ski area, one storm matters less than the accumulated season, so the word becomes an annual figure.","whyCN":"对滑雪场来说，一场暴雪不如整季的累积重要，于是这个词成了年度数字。"},{"no":"05","title":"Stored water in the mountains","titleCN":"山中的储水","definition":"snow considered as a reservoir that will melt into streams","definitionCN":"被视为将融成溪流的储水库的雪","example":"The winter snowfall supplies most of the valley's summer water.","exampleCN":"冬季降雪提供了山谷夏季的大部分用水。","why":"Snow is rain postponed; water managers read the snowfall as next year's river.","whyCN":"雪是被推迟的雨；水务管理者把降雪读作明年的河。"},{"no":"06","title":"The frozen member of precipitation","titleCN":"降水中的冻结成员","definition":"in climate science, the frozen form of precipitation as opposed to rain","definitionCN":"气候科学中与降雨相对的冻结降水形态","example":"The model tracks snowfall and rainfall separately.","exampleCN":"模型把降雪与降雨分开追踪。","why":"Classification pairs snowfall with rainfall under the umbrella term precipitation.","whyCN":"分类把 snowfall 与 rainfall 配在 precipitation 这一统称之下。"},{"no":"07","title":"A regional or altitude pattern","titleCN":"随地区与海拔变化的分布","definition":"the characteristic distribution of snow across a region or up a mountain","definitionCN":"雪在一个地区或沿山坡分布的典型方式","example":"The snowfall increases sharply above the tree line.","exampleCN":"林线以上的降雪急剧增加。","why":"Snow depends on altitude and exposure, so the word regularly takes regional and vertical adjectives.","whyCN":"雪取决于海拔与朝向，所以这个词常带区域与垂直方向的修饰语。"},{"no":"08","title":"Snow as a disruption","titleCN":"造成交通中断的降雪","definition":"snowfall viewed as a hazard that closes roads and delays travel","definitionCN":"被视为封闭道路、延误行程的危害的降雪","example":"The overnight snowfall closed the mountain pass.","exampleCN":"夜间的降雪封住了山口。","why":"For a transport office, the same weather is an operational problem, and the word shifts into risk language.","whyCN":"对交通部门而言，同样的天气是运行问题，这个词就转入风险语言。"}],"etymology":{"intro":{"en":"Snowfall is a modern compound of two native Germanic words. Dates are approximate.","cn":"snowfall 是由两个本土日耳曼词构成的现代复合词。年代为大致估计。"},"items":[{"era":"OLD ENGLISH","en":"Snow goes back to Old English snaw, from Proto-Germanic *snaiwaz and PIE *sniegwh- 'to snow'.","cn":"snow 源自古英语 snaw，出自原始日耳曼语 *snaiwaz 与原始印欧语 *sniegwh-「下雪」。"},{"era":"OLD ENGLISH","en":"Fall comes from feallan 'to fall', a strong verb whose past tense feoll survives as fell.","cn":"fall 出自 feallan「落下」，这是一个强变化动词，其过去式 feoll 仍留在 fell 中。"},{"era":"MODERN ENGLISH (19c)","en":"The compound snowfall appears in the nineteenth century, when weather stations began keeping systematic records.","cn":"复合词 snowfall 出现于十九世纪，当时气象站开始系统记录。"},{"era":"MODERN ENGLISH (mid-19c)","en":"Snow boards and mountain weather logs made the compound common, and a single storm could now be recorded as an amount of snowfall rather than only as a sight.","cn":"测雪板与山地气象日志让这个复合词流行起来，一场雪现在可以记为一定量的降雪，而不只是一种景象。"},{"era":"MODERN ENGLISH (20c)","en":"Seasonal snowfall totals became standard measures for water supply, ski resorts and mountain hydrology.","cn":"季节性降雪总量成为供水、滑雪场与山地水文学的标准指标。"}]},"similar":{"note":{"en":"Group one holds snow compounds that are easily swapped for the word; group two holds other words for falling water.","cn":"第一组是容易被替换使用的雪类复合词；第二组是其他表示落下之水的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"snowflake","ipa":"/ˈsnəʊfleɪk/","tag":"same family","definition":"One crystal of snow; it counts pieces, while snowfall counts events and totals.","definitionCN":"一片雪的晶体；它数的是个体，而 snowfall 数的是事件与总量。"},{"word":"snowstorm","ipa":"/ˈsnəʊstɔːm/","tag":"same family","definition":"A storm with snow and wind; it adds violence and visibility loss that snowfall alone does not imply.","definitionCN":"夹雪带风的风暴；它多了猛烈与能见度下降之意，而单说 snowfall 并无这层含义。"},{"word":"snowdrift","ipa":"/ˈsnəʊdrɪft/","tag":"same family","definition":"A bank of snow piled up by wind; it names the result after the fall, not the fall itself.","definitionCN":"被风堆起的雪堆；它指落下之后的结果，而不是落下本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"precipitation","ipa":"/ˌpresɪpɪˈteɪʃn/","tag":"all forms","definition":"Falling water of every kind; snowfall is its frozen member.","definitionCN":"一切形式落下的水；snowfall 是其中的冻结成员。"},{"word":"blizzard","ipa":"/ˈblɪzəd/","tag":"severe storm","definition":"A snowstorm with strong wind and very poor visibility, defined by conditions rather than by amount.","definitionCN":"风大、能见度极差的暴风雪，按气象条件而非雪量界定。"},{"word":"sleet","ipa":"/sliːt/","tag":"mixed fall","definition":"A mixture of rain and snow, or partly melted snow; it is neither pure snowfall nor pure rain.","definitionCN":"雨雪混合或半融的雪；既不是纯降雪，也不是纯降雨。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the compound is transparent and its partners are real snow terms.","cn":"正常联想：复合词意义清楚，搭配都是真实的雪类术语。"},"normal":[{"en":"snow + fall: substance plus motion, the exact twin of rainfall.","cn":"snow + fall：物质加运动，与 rainfall 是完全的孪生结构。"},{"en":"snowfall total and annual snowfall are the phrases that turn the event into a figure.","cn":"snowfall total 与 annual snowfall 是把事件变成数字的搭配。"},{"en":"snowfall and rainfall divide precipitation by temperature, and sleet sits between them.","cn":"snowfall 与 rainfall 按温度划分降水，sleet 则位于两者之间。"},{"en":"a light snowfall is countable, while the same word without an article usually means the total.","cn":"a light snowfall 是可数的「一场」，而不加冠词的同一词通常指总量。"},{"en":"the snowpack is the stored form of snowfall, which is why water managers watch the winter total.","cn":"snowpack 是 snowfall 的储存形态，所以水务管理者关注冬季总量。"}],"abstract":[{"en":"Abstractly, snowfall is rain that has been delayed and stored; it arrives as weather and leaves as river.","cn":"抽象地看，snowfall 是被推迟并储存起来的雨；它以天气到来，以河流离开。"},{"en":"The same noun covers a minute (one shower) and a season (a total), because snow can be counted either way.","cn":"同一个名词既覆盖一分钟（一场雪），也覆盖一季（总量），因为雪两种数法都成立。"},{"en":"So snowfall is water on credit: it falls now and is paid out at the thaw.","cn":"所以 snowfall 是赊账的水：现在落下，解冻时才付清。"}]},"examples":[{"en":"The mountain village averages two metres of snowfall a year.","cn":"这个山村年平均降雪两米。"},{"en":"A dry winter brought little snowfall to the upper valley.","cn":"干燥的冬天给上游山谷带来很少降雪。"},{"en":"Snowfall in April is rare at this altitude.","cn":"在这个海拔，四月降雪很少见。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"snow（雪）+ fall（落下）：雪从天上落下来 → snowfall 降雪、降雪量","word":"snowfall"},"root":"snow 源自古英语 snaw（原始日耳曼语 *snaiwaz，原始印欧语 *sniegwh-），fall 源自古英语 feallan；复合词 snowfall 于十九世纪出现。","sensesIntro":{"en":"Eight senses follow snow from cloud to consequence: the event, the measured depth, one bout, the season total, the stored water, the frozen category, the regional pattern and the closed road.","cn":"八个义项让雪从云走到后果：事件、测得的深度、单独一场、整季总量、储存的水、冻结类别、区域格局以及被封住的路。"},"semanticMap":{"core":{"en":"CORE IMAGE: white crystals leave the sky, are measured in a field, and wait to become water again.","cn":"核心意象：白色晶体离开天空，在空地上被量出深度，然后等待重新变成水。"},"chain":["FALLING SNOW","MEASURED DEPTH","SINGLE BOUT","SEASON TOTAL","STORED WATER","FROZEN CATEGORY"],"branches":[{"senses":"01 · 03","en":"EVENT: the continuous fall and the separate bout are one process counted in two ways.","cn":"事件：连续的落下与单独的一场，是同一过程两种数法。"},{"senses":"02 · 04","en":"MEASURE: a ruler gives a depth, and a season adds those depths into a total.","cn":"计量：量尺给出深度，一个雪季把这些深度相加成总量。"},{"senses":"05","en":"STORAGE: mountain snow is water held until spring.","cn":"储存：山上的雪是被留到春天的水。"},{"senses":"06 · 07","en":"CLASSIFICATION: the frozen member of precipitation, distributed by latitude and height.","cn":"分类：降水的冻结成员，按纬度与高度分布。"},{"senses":"08","en":"HAZARD: the same fall becomes a closed pass and a delayed train.","cn":"危害：同一场雪变成封闭的山口与延误的列车。"}]},"affixes":{"intro":{"en":"Snowfall belongs to the snow- compound family; English builds these by joining snow to a short noun or verb, not by adding Latin suffixes.","cn":"snowfall 属于 snow 系复合词族；英语靠把 snow 与简短名词或动词拼接来构词，而不是加拉丁后缀。"},"latinIntro":{"en":"Latin does have a cognate: nix 'snow' comes from the same PIE root, so the Latin entries below are true relatives rather than ancestors.","cn":"拉丁语确有同源词：nix「雪」出自同一原始印欧语词根，所以下面的拉丁条目是真正的同源词，而不是祖先。"},"items":[{"word":"snowflake","structure":"snow + flake (small flat piece)","meaning":"a single crystal of snow","meaningCN":"一片雪的晶体（flake 指小薄片）","example":"A snowflake settled on the dark sleeve.","exampleCN":"一片雪花落在深色衣袖上。"},{"word":"snowstorm","structure":"snow + storm","meaning":"a storm with heavy snow","meaningCN":"夹带大雪的风暴","example":"The snowstorm shut the airport.","exampleCN":"暴风雪使机场关闭。"},{"word":"snowdrift","structure":"snow + drift (piled material)","meaning":"a mound of snow heaped by wind","meaningCN":"被风堆起的雪堆","example":"The road vanished under a snowdrift.","exampleCN":"道路消失在一个雪堆下。"},{"word":"snowpack","structure":"snow + pack (pressed mass)","meaning":"the accumulated snow on the ground, especially in mountains","meaningCN":"地面上累积的积雪，尤指山地雪层","example":"The snowpack holds most of the spring runoff.","exampleCN":"积雪层蓄着大部分春季径流。"},{"word":"snowfield","structure":"snow + field","meaning":"a wide area permanently covered with snow","meaningCN":"常年被雪覆盖的广阔地带","example":"The snowfield stretched to the horizon.","exampleCN":"雪原一直延伸到地平线。"},{"word":"snowplow","structure":"snow + plow","meaning":"a vehicle or blade that clears snow from roads","meaningCN":"清扫道路积雪的车辆或铲刀","example":"The snowplow reached the pass by noon.","exampleCN":"扫雪车中午前赶到了山口。"},{"word":"snow-blind","structure":"snow + blind","meaning":"temporarily unable to see because of glare from snow","meaningCN":"因雪面强光而暂时失明的","example":"Without goggles they went snow-blind.","exampleCN":"没戴护目镜，他们得了雪盲。"},{"word":"snowfall total","structure":"snowfall + total","meaning":"the summed snowfall over a period","meaningCN":"一段时间内累计的降雪总量","example":"The snowfall total doubled the monthly average.","exampleCN":"降雪总量是月平均值两倍。"}],"latinEntries":[{"word":"nix","structure":"Latin nix, stem niv-","meaning":"snow","meaningCN":"雪"},{"word":"nival","structure":"nix, niv- + -al (relating to)","meaning":"relating to snow, as in a nival zone","meaningCN":"与雪有关的，如 nival zone（雪带）"},{"word":"niveous","structure":"nix, niv- + -eous","meaning":"snow-white","meaningCN":"雪白的"}]}},{"word":"snowflake","ipa_uk":"/ˈsnəʊfleɪk/","ipa_us":"/ˈsnoʊfleɪk/","definition_zh":"雪花；雪片；（口语）过度敏感的人；装饰用仿雪花","definition_en":"a single crystal of snow, or a small flat piece of something","core_image":"一片六角冰晶落到深色衣袖上，边缘的枝杈还看得清，转眼化成一点水","scene":"孩子伸出手套，一片雪花落在毛线上，转眼就化了。A single snowflake landed on the mitten and melted at once.","sceneCN":"这里该词指「一片雪晶体」（第 1 个义项：单个雪花）；句意为一片雪花落在手套上，立刻融化了。","pos":[{"tag":"n.","zh":"雪花；雪片；（口语）过度敏感的人；装饰用仿雪花"}],"collocations":[{"phrase":"a single snowflake","zh":"一片雪花"},{"phrase":"no two snowflakes are alike","zh":"没有两片雪花完全相同"},{"phrase":"snowflake shape","zh":"雪花形状"},{"phrase":"paper snowflakes","zh":"纸剪的雪花装饰"},{"phrase":"snowflake crystal","zh":"雪花晶体"},{"phrase":"a snowflake ornament","zh":"雪花挂饰"}],"forms":[{"label":"复数","form":"snowflakes"},{"label":"组成词一","form":"snow（雪）"},{"label":"组成词二","form":"flake（小薄片）"},{"label":"形容词（雪的）","form":"snowy（多雪的）"},{"label":"相关动词（下雪）","form":"snow（下雪）"}],"derivatives":[{"word":"snow","pos":"n./v.","zh":"雪；下雪"},{"word":"snowy","pos":"adj.","zh":"多雪的；雪白的"},{"word":"snowfall","pos":"n.","zh":"降雪；降雪量"},{"word":"snowflake pattern","pos":"n.","zh":"雪花图案"},{"word":"flaky","pos":"adj.","zh":"易碎的；薄片状的；（口语）不可靠的"}],"senses":[{"no":"01","title":"One crystal of snow","titleCN":"一片雪晶体","definition":"a single ice crystal that falls as snow","definitionCN":"作为雪落下的单个冰晶","example":"A single snowflake landed on the mitten and melted at once.","exampleCN":"一片雪花落在手套上，立刻融化了。","why":"Snow names the mass; the compound singles out one visible piece of that mass.","whyCN":"snow 指整片雪体；这个复合词把其中可见的一个个体单独拎出来。"},{"no":"02","title":"The six-armed shape","titleCN":"六角枝杈的形状","definition":"the six-sided branching form of an ice crystal","definitionCN":"冰晶形成的六角分枝形态","example":"Each snowflake showed a six-armed pattern under the lens.","exampleCN":"在放大镜下，每片雪花都显出六角枝杈的图案。","why":"The word is also used for the shape itself, because the shape is what makes a flake recognizable.","whyCN":"这个词也指形状本身，因为正是形状让一片雪花可被认出。"},{"no":"03","title":"A flake in flight","titleCN":"正在飘落的一片","definition":"a visible piece of snow seen falling through the air","definitionCN":"在空中飘落时可见的一片雪","example":"A few snowflakes drifted past the window.","exampleCN":"几片雪花从窗前飘过。","why":"In flight, individual pieces are what the eye catches, so the count noun fits the falling moment.","whyCN":"飘落时，眼睛捕捉的是个体，所以可数名词适合这一刻。"},{"no":"04","title":"Falling snow as a mass","titleCN":"成片飘落的雪","definition":"snowflakes in the plural, meaning light falling snow","definitionCN":"复数形式指轻轻飘落的雪","example":"Snowflakes began to fill the dark air.","exampleCN":"雪花开始充满昏暗的空中。","why":"Many counted pieces add up to an uncountable mass, so the plural can describe the weather itself.","whyCN":"许多可数的个体相加成不可数的整体，所以复数也能描述天气本身。"},{"no":"05","title":"The uniqueness metaphor","titleCN":"独一无二的比喻","definition":"a symbol of something individual and unrepeatable","definitionCN":"象征独特、不可复制之物的意象","example":"No two snowflakes are alike, and neither are two students.","exampleCN":"没有两片雪花相同，两个学生也一样。","why":"The visible symmetry plus the visible difference made the flake a ready emblem for individuality.","whyCN":"可见的对称加上可见的差异，让雪花成为「个体性」现成的象征。"},{"no":"06","title":"Informal: an over-sensitive person","titleCN":"口语：过度敏感的人","definition":"slang, often derogatory, for someone regarded as too easily offended","definitionCN":"常带贬义的口语，指被认为太容易被冒犯的人","example":"The comment was aimed at people the speaker called snowflakes.","exampleCN":"那番话针对的是说话者所谓的「玻璃心」。","why":"The metaphor reverses the flake: something lovely and fragile is recast as something that melts under slight heat.","whyCN":"这个比喻把雪花反过来用：原本可爱脆弱之物，被说成一遇热就化。"},{"no":"07","title":"A decorative imitation","titleCN":"装饰用的仿雪花","definition":"a paper, plastic or glass ornament shaped like a snowflake","definitionCN":"纸、塑料或玻璃制成的雪花形装饰物","example":"Paper snowflakes hung from the ceiling in every classroom.","exampleCN":"每间教室的天花板都挂着纸剪的雪花。","why":"When the shape is copied, the word follows the shape rather than the frozen material.","whyCN":"当形状被复制时，这个词跟着形状走，而不再跟着冰冷的材质。"},{"no":"08","title":"A classified crystal type","titleCN":"分类学上的晶体类型","definition":"in meteorology, one of the named crystal habits such as a stellar dendrite","definitionCN":"气象学中有专名的晶体形态，如星状枝晶","example":"The plate snowflake forms at a different temperature from the needle.","exampleCN":"板状雪花形成的温度与针状雪花不同。","why":"Scientific classification needs names for habits, and snowflake serves as the everyday base of those names.","whyCN":"科学分类需要给各类形态命名，snowflake 就成了这些名称的日常词基。"}],"etymology":{"intro":{"en":"Snowflake joins two native words. Snow is ancient and well attested; the origin of flake is disputed and is marked as uncertain.","cn":"snowflake 由两个本土词构成。snow 古老且有充分记录；flake 的来源有争议，已标注为存疑。"},"items":[{"era":"OLD ENGLISH","en":"Snow comes from Old English snaw, from Proto-Germanic *snaiwaz and PIE *sniegwh-.","cn":"snow 源自古英语 snaw，出自原始日耳曼语 *snaiwaz 与原始印欧语 *sniegwh-。"},{"era":"MIDDLE ENGLISH (14c–15c)","en":"Flake appears in Middle English for a loose piece or a thin layer, especially of snow; its earlier history is marked as source uncertain.","cn":"flake 在中古英语中表示松散的一片或薄薄一层，尤指雪；其更早历史来源不确定。"},{"era":"OLD NORSE (possible source)","en":"One common suggestion is Old Norse flak 'loose piece, snowflake', but the Norse and English forms do not match cleanly, so this is only a hypothesis.","cn":"一种常见推测是古诺斯语 flak「松散的一片、雪花」，但诺斯语与英语形式并不完全吻合，因此只是假说。"},{"era":"MODERN ENGLISH (18c–19c)","en":"The compound snowflake becomes common in the eighteenth and nineteenth centuries, helped by the microscope and by printed winter illustrations.","cn":"复合词 snowflake 在十八至十九世纪变得常见，显微镜与印刷的冬季插图起了推动作用。"},{"era":"MODERN ENGLISH (20c–21c)","en":"The meteorology sense is formalized in the twentieth century, and the slang sense for a sensitive person spreads in the twenty-first.","cn":"气象义在二十世纪被正式化，指「过度敏感者」的俚语义则在二十一世纪传播开来。"}]},"similar":{"note":{"en":"Group one sets apart words for pieces and masses of snow; group two holds the scientific and everyday neighbours.","cn":"第一组区分「雪的个体与整体」相关词；第二组是科学与日常的近邻词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"snowfall","ipa":"/ˈsnəʊfɔːl/","tag":"same family","definition":"The fall of snow or its total; it counts events, not individual crystals.","definitionCN":"落雪或其总量；它数事件，不数单个晶体。"},{"word":"flake","ipa":"/fleɪk/","tag":"base word","definition":"A small flat piece of any material, such as paint or cereal; without snow it has nothing to do with weather.","definitionCN":"任何材料的小薄片，如漆片或麦片；不带 snow 时与天气无关。"},{"word":"snowbank","ipa":"/ˈsnəʊbæŋk/","tag":"same family","definition":"A long heap of snow at the roadside; it names an accumulation, not a single crystal.","definitionCN":"路边长长的雪堆；它指堆积物，而不是单个晶体。"}]},{"heading":"NEAR MEANING","entries":[{"word":"crystal","ipa":"/ˈkrɪstl/","tag":"material form","definition":"A solid with a regular internal arrangement of atoms; a snowflake is one kind of ice crystal.","definitionCN":"原子内部规则排列的固体；雪花是冰晶体的一种。"},{"word":"sleet","ipa":"/sliːt/","tag":"mixed fall","definition":"Rain and snow mixed, or partly melted snow; it is a slushy fall rather than a clean crystal.","definitionCN":"雨雪混合或半融的雪；是泥泞的降落，而不是干净的晶体。"},{"word":"hailstone","ipa":"/ˈheɪlstəʊn/","tag":"frozen pellet","definition":"A pellet of ice from a thunderstorm; it is rounded and layered, not six-armed like a snowflake.","definitionCN":"雷暴中落下的冰粒；它圆而分层，不像雪花那样六角分枝。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the compound is literal, and the science terms are real.","cn":"正常联想：复合词是字面组合，所引科学术语也都真实。"},"normal":[{"en":"snow + flake: a flake of snow, just as a flake of paint is a thin piece of paint.","cn":"snow + flake：一片雪，正如 a flake of paint 是一片薄漆。"},{"en":"snowfall is the mass or the event, and snowflake is the single piece inside it.","cn":"snowfall 是整体或事件，snowflake 是其中单个个体。"},{"en":"the phrase no two snowflakes are alike is the standard way the uniqueness idea is expressed.","cn":"no two snowflakes are alike 是表达「独一无二」这一想法的标准说法。"},{"en":"stellar dendrite is the scientific name for the familiar six-armed snowflake shape.","cn":"stellar dendrite 是熟悉的那种六角枝状雪花的科学名称。"},{"en":"snowflake ornament is the phrase used when the shape is copied in paper or glass.","cn":"snowflake ornament 是形状被纸或玻璃复制时使用的说法。"}],"abstract":[{"en":"Abstractly, a snowflake is order that appears for a moment and then dissolves: six arms, one instant, then water.","cn":"抽象地看，雪花是短暂出现又消失的秩序：六条枝、一个瞬间，然后变成水。"},{"en":"Its symmetry comes from physics, its difference from history, which is why it can stand for both pattern and individuality.","cn":"它的对称来自物理，它的差异来自经历，所以它既能代表规律，也能代表个体。"},{"en":"So the word moves easily from weather to metaphor to slang without changing its shape.","cn":"于是这个词从天气滑向比喻再滑向俚语，而形状始终不变。"}]},"examples":[{"en":"She caught a snowflake on her tongue and laughed.","cn":"她用舌头接住一片雪花，笑了。"},{"en":"The children cut paper snowflakes for the window.","cn":"孩子们剪了纸雪花贴在窗上。"},{"en":"Under the microscope the snowflake revealed fine branching.","cn":"在显微镜下，这片雪花显出精细的分枝。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"snow（雪）+ flake（薄片）：雪的一片薄片 → snowflake 雪花","word":"snowflake"},"root":"snow 源自古英语 snaw（原始日耳曼语 *snaiwaz，原始印欧语 *sniegwh-）；flake 指松散薄片，更早来源不确定，或与古诺斯语 flak 有关。","sensesIntro":{"en":"Eight senses grow from one crystal: its shape, its flight, its mass, its use as a sign of uniqueness, its slang life, its paper copy and its scientific type.","cn":"八个义项从一片晶体长出：它的形状、飘落、整体、作为独特性的象征、俚语用法、纸质复制品以及科学类型。"},"semanticMap":{"core":{"en":"CORE IMAGE: a six-armed piece of ice, visible for a moment, then gone.","cn":"核心意象：一片六角冰晶，可见一瞬，随即消失。"},"chain":["SINGLE CRYSTAL","SIX ARMS","FLYING PIECE","FALLING MASS","UNIQUENESS","SOCIAL LABEL"],"branches":[{"senses":"01 · 03","en":"THE PIECE: one crystal, whether resting on a sleeve or drifting past a window.","cn":"个体：一片晶体，无论停在衣袖上还是飘过窗前。"},{"senses":"02 · 08","en":"THE SHAPE: the six-armed habit is both a familiar picture and a classified type.","cn":"形状：六角形态既是一幅熟悉的图像，也是一个分类类型。"},{"senses":"04","en":"THE MASS: many counted pieces become the weather called falling snow.","cn":"整体：许多可数个体变成名为「飘雪」的天气。"},{"senses":"05 · 06","en":"THE SYMBOL: uniqueness in praise, fragility in insult.","cn":"象征：赞美时指独一无二，贬损时指脆弱易化。"},{"senses":"07","en":"THE COPY: the shape survives in paper and glass after the ice is gone.","cn":"复制：冰消失之后，形状仍留在纸与玻璃上。"}]},"affixes":{"intro":{"en":"Snowflake is a snow- compound; the wider family is built by joining snow to nouns for landforms, tools and weather.","cn":"snowflake 是 snow 系复合词；更大的词族靠把 snow 与地貌、工具、天气名词拼接而成。"},"latinIntro":{"en":"Snow has a true Latin cognate in nix (stem niv-), from the same PIE root. Flake has no Latin relative, so this line explains only half the compound.","cn":"snow 在拉丁语中有真正的同源词 nix（词干 niv-），出自同一原始印欧语词根。flake 没有拉丁亲属，因此这条线索只解释复合词的一半。"},"items":[{"word":"snowfall","structure":"snow + fall","meaning":"the fall of snow, or its measured total","meaningCN":"降雪，或其测得的总量","example":"The snowfall lasted all night.","exampleCN":"这场雪下了一整夜。"},{"word":"snowstorm","structure":"snow + storm","meaning":"a storm with heavy snow","meaningCN":"夹带大雪的风暴","example":"A snowstorm cancelled the flights.","exampleCN":"一场暴风雪使航班取消。"},{"word":"snowbank","structure":"snow + bank (mound)","meaning":"a long heap of snow, especially at a road edge","meaningCN":"长长的雪堆，尤指路边雪堤","example":"The plow pushed a snowbank across the driveway.","exampleCN":"铲雪车在车道口堆起一道雪堤。"},{"word":"snowcap","structure":"snow + cap","meaning":"permanent snow on a mountain top","meaningCN":"山顶的常年积雪","example":"The snowcap glowed at sunset.","exampleCN":"山顶积雪在日落时发亮。"},{"word":"snowdrift","structure":"snow + drift","meaning":"snow piled by the wind","meaningCN":"被风堆起的雪","example":"A snowdrift blocked the gate.","exampleCN":"一个雪堆堵住了大门。"},{"word":"snowpack","structure":"snow + pack","meaning":"the accumulated snow layer on the ground","meaningCN":"地面累积的积雪层","example":"The snowpack is deeper than last year.","exampleCN":"积雪层比去年更厚。"},{"word":"snowplow","structure":"snow + plow","meaning":"a machine that clears snow from roads","meaningCN":"清除道路积雪的机械","example":"The snowplow cleared the main road first.","exampleCN":"扫雪车先清理了主路。"},{"word":"snowflake pattern","structure":"snowflake + pattern","meaning":"a design shaped like a six-armed crystal","meaningCN":"六角晶体形状的图案","example":"The scarf carries a snowflake pattern.","exampleCN":"这条围巾上有雪花图案。"}],"latinEntries":[{"word":"nix","structure":"Latin nix, stem niv-","meaning":"snow","meaningCN":"雪"},{"word":"nival","structure":"niv- + -al","meaning":"relating to snow","meaningCN":"与雪有关的"},{"word":"niveous","structure":"niv- + -eous","meaning":"snow-white","meaningCN":"雪白的"}]}},{"word":"hail","ipa_uk":"/heɪl/","ipa_us":"/heɪl/","definition_zh":"冰雹；一阵冰雹；下冰雹；如雹般袭来；（同形异源）招呼、欢呼","definition_en":"frozen pellets of ice that fall from a thunderstorm, or to fall as such pellets","core_image":"乌云压顶，豆大的冰粒砸在铁皮棚顶上，噼啪作响，滚得满地都是","scene":"豆大的冰粒砸在铁皮棚顶上，噼啪作响。Hail rattled on the tin roof like gravel.","sceneCN":"这里该词指「从天落下的冰粒」（第 1 个义项：冰雹这一冻结降水）；句意为冰雹砸在铁皮屋顶上，响声像碎石。","pos":[{"tag":"n.","zh":"冰雹；一阵冰雹"},{"tag":"vi.","zh":"下冰雹；如雹般落下"},{"tag":"vt.","zh":"向……招呼；欢呼（同形异源的另一词）"}],"collocations":[{"phrase":"heavy hail","zh":"大冰雹"},{"phrase":"a hail storm","zh":"冰雹风暴"},{"phrase":"hail damage","zh":"冰雹造成的损坏"},{"phrase":"hail the size of peas","zh":"豌豆大小的冰雹"},{"phrase":"a hail of stones","zh":"如雹般砸来的石块"},{"phrase":"hail a taxi","zh":"招呼一辆出租车"}],"forms":[{"label":"不可数用法（冰雹物质）","form":"hail（通常不可数）"},{"label":"三单（动词）","form":"hails"},{"label":"过去式","form":"hailed"},{"label":"过去分词","form":"hailed"},{"label":"现在分词","form":"hailing"},{"label":"复合名词（冰雹风暴）","form":"hailstorm"}],"derivatives":[{"word":"hailstone","pos":"n.","zh":"一颗冰雹"},{"word":"hailstorm","pos":"n.","zh":"冰雹风暴"},{"word":"haily","pos":"adj.","zh":"冰雹的；多冰雹的（较少用）"},{"word":"hail shower","pos":"n.","zh":"一阵冰雹"},{"word":"hailing","pos":"n./adj.","zh":"下冰雹；如雹般袭来的"}],"senses":[{"no":"01","title":"Frozen pellets falling","titleCN":"从天落下的冰粒","definition":"frozen balls of ice that fall from a thunderstorm","definitionCN":"从雷暴云中落下的冻结冰球","example":"Hail rattled on the tin roof like gravel.","exampleCN":"冰雹砸在铁皮屋顶上，响声像碎石。","why":"Hail is ice that grew in strong updraughts and became too heavy to stay in the cloud, so it arrives as hard pellets rather than flakes.","whyCN":"冰雹在强上升气流中长大，重到云托不住，所以它以硬颗粒而不是薄片落地。"},{"no":"02","title":"A shower of hail","titleCN":"一阵冰雹","definition":"a single episode of hail falling","definitionCN":"一次冰雹落下的过程","example":"A sudden hail drove everyone under the awning.","exampleCN":"一阵突如其来的冰雹把大家赶到了雨棚下。","why":"Weather reports count separate episodes, so the mass noun also appears with an article as one bout.","whyCN":"天气报告要数出一次次过程，所以这个物质名词也能加冠词表示一场。"},{"no":"03","title":"The pellets themselves","titleCN":"冰雹颗粒本身","definition":"the individual ice pellets, considered as material","definitionCN":"作为物质来看的一颗颗冰粒","example":"Hail covered the field in a layer of white pellets.","exampleCN":"冰雹给田野盖上一层白色颗粒。","why":"As a mass noun, the word names the substance lying on the ground after the fall.","whyCN":"作为物质名词，这个词指落下后堆在地面上的那种东西。"},{"no":"04","title":"Impact damage","titleCN":"砸击造成的损坏","definition":"hail considered as a force that breaks glass, crops and roofs","definitionCN":"被视为能砸破玻璃、毁坏庄稼与屋顶的力量","example":"The storm's hail punched holes in the greenhouse panels.","exampleCN":"风暴的冰雹把温室板砸出了洞。","why":"Because a pellet hits with concentrated force, the word regularly appears in damage reports.","whyCN":"因为颗粒以集中的力撞击，这个词常出现在损坏报告里。"},{"no":"05","title":"To fall as hail","titleCN":"下冰雹","definition":"used as a verb meaning that hail is falling","definitionCN":"作动词，表示正在下冰雹","example":"It hailed for ten minutes and then cleared.","exampleCN":"下了十分钟冰雹，然后放晴了。","why":"The verb simply turns the weather event into a process, as with rain and snow.","whyCN":"动词只是把天气事件变成一个过程，与 rain、snow 的用法相同。"},{"no":"06","title":"A hail storm","titleCN":"冰雹风暴","definition":"a storm whose main product is hail","definitionCN":"主要产物为冰雹的风暴","example":"The hail storm stripped leaves from the vines.","exampleCN":"冰雹风暴把葡萄藤的叶子打光了。","why":"Compound naming separates the storm from the pellets; the storm is the system, hail is what it drops.","whyCN":"复合命名把风暴与冰粒分开：风暴是系统，冰雹是它落下的东西。"},{"no":"07","title":"A volley of flying objects","titleCN":"如雹般飞来的东西","definition":"a large number of objects thrown or fired at once, like falling hail","definitionCN":"一次抛来或射来的大量物体，如同落下的冰雹","example":"A hail of stones met the advancing line.","exampleCN":"如雹般的石块砸向推进的队伍。","why":"The metaphor keeps only the density and the downward strike: many hard things arriving at once.","whyCN":"这个比喻只保留密度与向下砸击：许多硬东西同时到来。"},{"no":"08","title":"To greet or call out","titleCN":"招呼；欢呼（另一词）","definition":"to greet someone or call to them, as in hailing a taxi","definitionCN":"向某人招呼或呼喊，如招呼出租车","example":"She hailed the driver from the corner of the street.","exampleCN":"她在街角招呼司机。","why":"This is a different word that happens to share the spelling; it comes from a Germanic root meaning 'healthy, whole', not from ice.","whyCN":"这是一个碰巧同形的另一个词，出自意为「健康、完整」的日耳曼词根，与冰无关。"}],"etymology":{"intro":{"en":"English has two words spelled hail. The ice word and the greeting word have separate Germanic origins and are not related; the entry keeps them apart.","cn":"英语有两个拼作 hail 的词。冰雹词与招呼词各有独立的日耳曼来源，彼此无关；本条目把它们分开处理。"},"items":[{"era":"OLD ENGLISH","en":"The ice word is Old English hægl, from Proto-Germanic *haglaz, with cognates in German Hagel and Dutch hagel.","cn":"冰雹词是古英语 hægl，出自原始日耳曼语 *haglaz，同源词有德语 Hagel 与荷兰语 hagel。"},{"era":"PROTO-INDO-EUROPEAN","en":"The usual reconstruction is PIE *kaghlo- 'pebble', which also gives Greek kakhlex 'round pebble'. The link is generally accepted but the exact form is a reconstruction.","cn":"通常重构为原始印欧语 *kaghlo-「小石子」，希腊语 kakhlex「圆石子」也出自此。此联系一般被接受，但确切形式属重构。"},{"era":"OLD ENGLISH (second word)","en":"The greeting word is a different verb, from Proto-Germanic *hailjan 'to greet', related to whole, heal and health; its older sense is 'be whole, be well'.","cn":"招呼词是另一个动词，出自原始日耳曼语 *hailjan「致意」，与 whole、heal、health 同族；其更早义为「完整、安好」。"},{"era":"MIDDLE ENGLISH","en":"Both words survive into Middle English, and because they sound identical they are now written alike, though their histories remain separate.","cn":"两个词都进入中古英语；由于读音相同，如今拼写也相同，但各自的历史仍然分开。"},{"era":"MODERN ENGLISH (19c–20c)","en":"The figurative 'hail of bullets' is a nineteenth-century extension of the ice image, while 'hail a taxi' extends the greeting word.","cn":"比喻性的「弹雨」是十九世纪对冰雹意象的延伸，而「招呼出租车」则延伸了招呼词。"}]},"similar":{"note":{"en":"Group one separates the spelling neighbours, including two true homographs; group two holds other frozen falls.","cn":"第一组分辨拼写相近的词，其中两个是真正的同形词；第二组是其他冻结降水。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hale","ipa":"/heɪl/","tag":"sound-alike, different word","definition":"Healthy and strong, as in hale and hearty; also an old verb meaning to drag. It is spelled with no i and is unrelated to ice or greeting.","definitionCN":"健壮的，如 hale and hearty；也有古动词义「拖拽」。拼写无 i，与冰雹及招呼都无关。"},{"word":"heel","ipa":"/hiːl/","tag":"sound-alike","definition":"The back part of the foot; the vowel is long /iː/, so it is heard as a different word from hail.","definitionCN":"脚后跟；元音是长音 /iː/，听起来与 hail 不同。"},{"word":"hall","ipa":"/hɔːl/","tag":"near sound","definition":"A large room or a corridor; the vowel is /ɔː/ and the final consonant is -ll, clearly different from hail.","definitionCN":"大厅或走廊；元音是 /ɔː/，词尾是 -ll，与 hail 明显不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sleet","ipa":"/sliːt/","tag":"mixed fall","definition":"Rain and snow mixed, or ice pellets in American usage; it is softer or wetter than hail.","definitionCN":"雨雪混合，美式英语中也指冰粒；比冰雹更软或更湿。"},{"word":"graupel","ipa":"/ˈɡrɔːpəl/","tag":"soft pellets","definition":"Snowflakes coated with rime, forming soft white pellets; hail is harder and built in stronger updraughts.","definitionCN":"被雾凇包裹的雪片形成的软白颗粒；冰雹更硬，形成于更强的上升气流。"},{"word":"hailstone","ipa":"/ˈheɪlstəʊn/","tag":"one pellet","definition":"A single pellet of hail; the mass noun names the material, the count noun names one piece.","definitionCN":"一颗冰雹；物质名词指材料，可数名词指一个个体。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real compounds and a real homograph split, no invented links.","cn":"正常联想：使用真实复合词与真实的同形词区分，不编造联系。"},"normal":[{"en":"hail + stone = hailstone, one pellet; hail + storm = hailstorm, the system that drops them.","cn":"hail + stone = hailstone，一颗冰雹；hail + storm = hailstorm，落下它们的天气系统。"},{"en":"a hail of bullets borrows the density and impact of falling ice, not its cold.","cn":"a hail of bullets 借用了落冰的密集与冲击，而不借它的寒冷。"},{"en":"hail a taxi belongs to the greeting word, whose old sense is 'be well'; it has nothing to do with weather.","cn":"hail a taxi 属于招呼词，其旧义为「安好」，与天气无关。"},{"en":"hail-fellow-well-met uses the greeting word and means too friendly in a false way.","cn":"hail-fellow-well-met 用的是招呼词，指虚情假意地过分亲热。"},{"en":"the phrase hale and hearty contains the healthy word, which is why it is spelled without i.","cn":"hale and hearty 里用的是「健壮」那个词，所以拼写没有 i。"}],"abstract":[{"en":"Abstractly, hail is the sky throwing hard little stones; the metaphor survives whenever many objects arrive at once.","cn":"抽象地看，hail 是天空扔下的小硬石；只要许多物体同时到来，这个比喻就仍在使用。"},{"en":"The ice word and the greeting word meet only in spelling, like two strangers sharing a coat.","cn":"冰雹词与招呼词只在拼写上相遇，就像两个陌生人共用一件外套。"},{"en":"So hail covers both a violent fall and a friendly call, and the context alone decides which word is being used.","cn":"所以 hail 既指猛烈的坠落，也指友善的呼唤，只有语境能决定用的是哪个词。"}]},"examples":[{"en":"The vineyard lost half its grapes to a single hail storm.","cn":"葡萄园因一场冰雹风暴损失了一半葡萄。"},{"en":"Hail the size of golf balls dented the car roof.","cn":"高尔夫球大小的冰雹把车顶砸出了凹坑。"},{"en":"He hailed a passing bus and climbed aboard.","cn":"他招呼了一辆路过的公交车，上了车。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「嗨哟」：天上砸下冰粒，人喊一声「嗨哟」 → hail 冰雹","word":"hail"},"root":"冰雹义为古英语 hægl（原始日耳曼语 *haglaz，原始印欧语 *kaghlo-「小石子」）；招呼义为另一词，出自原始日耳曼语 *hailjan「致意」，与 whole、heal 同族。","sensesIntro":{"en":"Eight senses start with hard ice pellets and follow their force: one pellet, one shower, the mass, the damage, the verb, the storm, the metaphor of a volley, and finally the unrelated greeting word that shares the spelling.","cn":"八个义项从硬冰粒开始，沿着它的力量展开：一颗、一阵、整片物质、造成的损坏、动词、风暴、齐射的比喻，最后是同形而无关的招呼词。"},"semanticMap":{"core":{"en":"CORE IMAGE: hard ice pellets driven down by a storm, striking whatever lies below.","cn":"核心意象：风暴驱赶着硬冰粒向下砸，打在下面的一切东西上。"},"chain":["ICE PELLET","SHOWER","GROUND LAYER","IMPACT","STORM SYSTEM","FLYING VOLLEY"],"branches":[{"senses":"01 · 03","en":"MATERIAL: one pellet and the layer it forms are the same substance at two scales.","cn":"物质：一颗冰雹与它铺成的一层，是同一物质的两个尺度。"},{"senses":"02 · 06","en":"EVENT AND SYSTEM: a shower is the fall, a storm is the machine that produces it.","cn":"事件与系统：一阵是落下本身，风暴是产生它的机器。"},{"senses":"04 · 07","en":"FORCE: concentrated impact breaks glass, and the same image turns stones or bullets into a hail.","cn":"力量：集中的撞击砸破玻璃，同一意象又让石块或子弹变成一阵「雹」。"},{"senses":"05","en":"PROCESS: the verb simply reports that the pellets are coming down.","cn":"过程：动词只是报告冰粒正在落下。"},{"senses":"08","en":"HOMOGRAPH: the greeting word shares only spelling, coming from a root meaning 'whole, healthy'.","cn":"同形词：招呼词只共享拼写，出自意为「完整、健康」的词根。"}]},"affixes":{"intro":{"en":"Hail builds almost all its family by compounding with nouns for pieces and storms; the greeting homograph builds a separate small set of idioms.","cn":"hail 的冰雹义几乎全靠与「颗粒」「风暴」类名词复合来扩展词族；同形的招呼义则形成另一小组习语。"},"latinIntro":{"en":"There is no Latin ancestor. Latin grando 'hail' is a semantic parallel only, not a cognate, so the Latin entry list is empty.","cn":"这里没有拉丁语祖先。拉丁语 grando「冰雹」只是语义对照，并非同源词，因此拉丁词条列表留空。"},"items":[{"word":"hailstone","structure":"hail + stone","meaning":"a single pellet of hail","meaningCN":"一颗冰雹（stone 指硬块）","example":"A hailstone cracked the windscreen.","exampleCN":"一颗冰雹把挡风玻璃砸裂了。"},{"word":"hailstorm","structure":"hail + storm","meaning":"a storm that produces hail","meaningCN":"产生冰雹的风暴","example":"The hailstorm lasted twenty minutes.","exampleCN":"这场冰雹风暴持续了二十分钟。"},{"word":"hail shower","structure":"hail + shower","meaning":"a short fall of hail","meaningCN":"一阵短促的冰雹","example":"A hail shower passed over the town.","exampleCN":"一阵冰雹掠过镇上。"},{"word":"hail damage","structure":"hail + damage","meaning":"loss caused by falling pellets","meaningCN":"冰雹造成的损失","example":"Insurance claims for hail damage doubled.","exampleCN":"冰雹损坏的保险索赔翻了一番。"},{"word":"hail cloud","structure":"hail + cloud","meaning":"the towering storm cloud in which hail grows","meaningCN":"冰雹在其中生成的高耸雷暴云","example":"Radar showed a hail cloud over the ridge.","exampleCN":"雷达显示山脊上空有一团冰雹云。"},{"word":"hail a taxi","structure":"hail (greet) + a taxi","meaning":"to signal a taxi to stop","meaningCN":"招手叫停出租车（此处 hail 为招呼义）","example":"We hailed a taxi outside the station.","exampleCN":"我们在车站外叫了一辆出租车。"},{"word":"hail from","structure":"hail (greet/origin) + from","meaning":"to come from a place of origin","meaningCN":"来自某地；原籍是（hail 的另一个同形词用法）","example":"She hails from a fishing village.","exampleCN":"她来自一个渔村。"},{"word":"Hail Mary","structure":"hail (greet) + Mary","meaning":"a prayer, or a desperate last attempt in sport","meaningCN":"万福马利亚祈祷；体育中指孤注一掷的最后一投","example":"The team tried a Hail Mary at the buzzer.","exampleCN":"球队在终场哨响时孤注一掷。"}],"latinEntries":[]}},{"word":"sleet","ipa_uk":"/sliːt/","ipa_us":"/sliːt/","definition_zh":"雨夹雪；半融的雪；（美式）冰粒；下冻雨","definition_en":"a mixture of rain and snow, or partly melted snow falling","core_image":"灰白的雨线里混着半融的雪，落在挡风玻璃上立刻摊成一层薄冰","scene":"雨夹着半融的雪落在挡风玻璃上，很快摊成一层薄冰。Sleet froze into a thin sheet as it struck the windscreen.","sceneCN":"这里该词指「雨与半融的雪混合落下」（第 1 个义项：雨雪混合降水）；句意为雨夹雪打在挡风玻璃上，很快冻成一层薄冰。","pos":[{"tag":"n.","zh":"雨夹雪；半融的雪；（美式）冰粒"},{"tag":"vi.","zh":"下雨夹雪；下冻雨"}],"collocations":[{"phrase":"sleet and snow","zh":"雨夹雪"},{"phrase":"a sleet shower","zh":"一阵雨夹雪"},{"phrase":"freezing sleet","zh":"冻雨夹雪"},{"phrase":"sleet warnings","zh":"雨夹雪预警"},{"phrase":"sleet on the road","zh":"路上的雨夹雪"},{"phrase":"a mixture of rain and sleet","zh":"雨与雨夹雪的混合"}],"forms":[{"label":"不可数用法","form":"sleet（通常不可数）"},{"label":"复数（少见，指多次过程）","form":"sleets"},{"label":"三单（动词）","form":"sleets"},{"label":"过去式","form":"sleeted"},{"label":"现在分词","form":"sleeting"},{"label":"形容词","form":"sleety"}],"derivatives":[{"word":"sleety","pos":"adj.","zh":"雨夹雪的；湿冷的"},{"word":"sleet shower","pos":"n.","zh":"一阵雨夹雪"},{"word":"sleeting","pos":"n./adj.","zh":"下冻雨；冻雨般的"},{"word":"sleet warning","pos":"n.","zh":"雨夹雪预警"},{"word":"wintry mix","pos":"n.","zh":"冬季混合降水（近义表达）"}],"senses":[{"no":"01","title":"Rain mixed with snow","titleCN":"雨与雪混合落下","definition":"a fall of rain and snow together, typical of a thaw","definitionCN":"雨与雪同时落下，常见于解冻时节","example":"Sleet froze into a thin sheet as it struck the windscreen.","exampleCN":"雨夹雪打在挡风玻璃上，很快冻成一层薄冰。","why":"Sleet names the halfway state between rain and snow, when flakes are melting as they fall.","whyCN":"sleet 命名雨与雪之间的中间状态：雪花在下落途中正在融化。"},{"no":"02","title":"Partly melted snow","titleCN":"半融的雪","definition":"snow that has begun to melt on its way down or on the ground","definitionCN":"在下落途中或落地后开始融化的雪","example":"The yard was covered in grey sleet by noon.","exampleCN":"到中午，院子已盖上一层灰色的半融雪。","why":"The same slush can be described from the snow side rather than from the rain side.","whyCN":"同一摊雪泥既可从雨的一侧描述，也可从雪的一侧描述。"},{"no":"03","title":"American: ice pellets","titleCN":"美式：冰粒","definition":"in American usage, small ice pellets that bounce when they land","definitionCN":"美式用法中指落地会弹起的小冰粒","example":"Sleet ticked against the windows all morning.","exampleCN":"整个上午冰粒都在敲窗。","why":"American weather services use sleet for frozen pellets rather than for a rain-snow mixture, a regional split in the word.","whyCN":"美国气象部门用 sleet 指冻结冰粒，而不是雨雪混合物，这是该词的地域分化。"},{"no":"04","title":"The glaze left behind","titleCN":"留在地面的薄冰","definition":"the thin ice sheet that forms when sleet or freezing rain lands","definitionCN":"雨夹雪或冻雨落地后形成的薄冰层","example":"Sleet on the steps made the whole stairway a slide.","exampleCN":"台阶上的雨夹雪把整段楼梯变成了滑梯。","why":"The result is named by the same word because the fall and its frozen residue are hard to separate.","whyCN":"结果也用同一个词命名，因为落下与它冻成的残留难以分开。"},{"no":"05","title":"A driving hazard","titleCN":"行车危险","definition":"sleet considered as a road condition that reduces grip","definitionCN":"被视为降低抓地力的路面状况","example":"Sleet closed the highway for two hours.","exampleCN":"雨夹雪使高速公路封闭了两小时。","why":"Transport reports turn weather into a state of the road, and the word follows that shift.","whyCN":"交通报告把天气变成路况，这个词也跟着这一转变。"},{"no":"06","title":"To fall as sleet","titleCN":"下雨夹雪","definition":"used as a verb meaning that sleet is falling","definitionCN":"作动词，表示正在下雨夹雪","example":"It sleeted all afternoon and never turned to snow.","exampleCN":"整个下午都在下雨夹雪，始终没转成雪。","why":"As with rain and snow, the weather noun supplies a impersonal verb.","whyCN":"与 rain、snow 一样，这个天气名词也派生出无人称动词。"},{"no":"07","title":"A category in forecasts","titleCN":"预报中的降水类别","definition":"one of the named precipitation types in a weather forecast","definitionCN":"天气预报中被命名的降水类型之一","example":"The forecast listed sleet between rain and snow.","exampleCN":"预报把雨夹雪列在雨与雪之间。","why":"Forecasts need discrete labels, so the continuum between rain and snow is cut into named categories.","whyCN":"预报需要离散标签，于是雨与雪之间的连续过渡被切成有名字的类别。"},{"no":"08","title":"The sign of a thaw","titleCN":"解冻的征兆","definition":"sleet as the weather that marks the change from deep winter to thaw","definitionCN":"标志严冬转向解冻的天气","example":"The first sleet of March told the farmers winter was ending.","exampleCN":"三月的第一场雨夹雪告诉农民冬天要结束了。","why":"Because sleet sits at the melting point, it naturally becomes a seasonal signal.","whyCN":"因为雨夹雪正处在融点，它自然成了一种季节信号。"}],"etymology":{"intro":{"en":"Sleet has no recorded Old English form and its deeper origin is uncertain. The main hypotheses are listed side by side without choosing one.","cn":"sleet 没有可考的古英语形式，更深来源不确定。主要假说并列列出，不作取舍。"},"items":[{"era":"MIDDLE ENGLISH (14c)","en":"Sleet appears in Middle English as slete, naming a mixture of rain and snow.","cn":"sleet 在中古英语中写作 slete，指雨与雪的混合物。"},{"era":"OLD ENGLISH (unattested)","en":"No Old English form is recorded. The word is often assumed to have existed, but the assumption cannot be verified, so the Old English stage is marked as source uncertain.","cn":"没有记录到古英语形式。人们常假定它曾经存在，但这一假定无法核实，因此古英语阶段来源不确定。"},{"era":"GERMANIC COMPARISON (hypothesis one)","en":"One common view connects it with Middle Low German slote 'hail' and German Schloße 'hailstone', which would make it a northern Germanic word.","cn":"一种常见观点把它与中古低地德语 slote「冰雹」、德语 Schloße「冰雹」联系起来，若是如此则属北日耳曼词。"},{"era":"GERMANIC COMPARISON (hypothesis two)","en":"Others treat it as a native formation related to the base of slush and sludge, though the sound correspondences are not clean. Neither explanation is settled.","cn":"另一些人把它视为与 slush、sludge 词基相关的本土构词，但音对应并不整齐。两种解释都未定论。"},{"era":"MODERN ENGLISH (19c–20c)","en":"British usage keeps 'rain and snow mixed'; American usage specializes it to ice pellets, and both senses now appear in international forecasts.","cn":"英式用法保留「雨雪混合」义，美式用法专指冰粒，两种义项如今都出现在国际预报中。"}]},"similar":{"note":{"en":"Group one holds words with a similar shape but another meaning; group two holds frozen and mixed precipitation.","cn":"第一组是字形相近而意义不同的词；第二组是冻结与混合降水。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"sleep","ipa":"/sliːp/","tag":"near sound","definition":"To rest with eyes closed; the vowel is the same but the final consonant is -p, and the meaning is unrelated.","definitionCN":"闭眼休息；元音相同，但词尾是 -p，意义无关。"},{"word":"fleet","ipa":"/fliːt/","tag":"near sound","definition":"A group of ships or vehicles; the first consonant is fl-, so only the rhyme is shared.","definitionCN":"船队或车队；首辅音是 fl-，只共享韵脚。"},{"word":"slate","ipa":"/sleɪt/","tag":"near spelling","definition":"A fine-grained rock used for roofs, or a list of candidates; the vowel is /eɪ/ and the meaning is unrelated.","definitionCN":"用于屋顶的细粒岩石，或候选人名单；元音是 /eɪ/，意义无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"hail","ipa":"/heɪl/","tag":"hard pellets","definition":"Frozen pellets from a thunderstorm; hail is harder and more violent than sleet.","definitionCN":"雷暴中落下的冻结冰粒；冰雹比雨夹雪更硬、更猛烈。"},{"word":"freezing rain","ipa":"/ˈfriːzɪŋ reɪn/","tag":"liquid that glazes","definition":"Rain that stays liquid in cold air and freezes on contact; it is a glaze, not a mixture.","definitionCN":"在冷空气中保持液态、触物即冻的雨；它形成冰壳，而不是混合物。"},{"word":"slush","ipa":"/slʌʃ/","tag":"melting snow","definition":"Snow and water mixed on the ground; it is the result on the pavement rather than the fall from the sky.","definitionCN":"地面上雪与水混合的泥雪；它是路面上的结果，而不是从天而降的过程。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real weather terms and real compounds, no invented etymology.","cn":"正常联想：使用真实的天气术语与真实复合词，不编造词源。"},"normal":[{"en":"sleet + -y = sleety, the adjective for cold wet weather with mixed precipitation.","cn":"sleet + -y = sleety，形容又冷又湿、夹着雨雪的天气。"},{"en":"sleet shower is a real forecast phrase for a short burst of mixed precipitation.","cn":"sleet shower 是预报中表示一阵短促混合降水的真实说法。"},{"en":"wintry mix is the broadcast term that covers sleet, freezing rain and snow together.","cn":"wintry mix 是气象播报中统称雨夹雪、冻雨与雪的术语。"},{"en":"in British usage sleet is rain plus snow; in American usage it is ice pellets, a genuine regional split.","cn":"英式用法中 sleet 是雨加雪；美式用法中它是冰粒，这是真实的地域分化。"},{"en":"freezing rain differs from sleet: the rain stays liquid until it touches a cold surface.","cn":"freezing rain 与 sleet 不同：雨在碰到冷表面之前一直保持液态。"}],"abstract":[{"en":"Abstractly, sleet is weather caught in transition: neither the clean crystal of snow nor the plain drop of rain.","cn":"抽象地看，sleet 是正在过渡中的天气：既不是干净的雪花，也不是单纯的水滴。"},{"en":"Its identity is defined by mixture, which is why forecasts need a separate box for it.","cn":"它的身份由「混合」定义，这正是预报要为它单设一格的原因。"},{"en":"So sleet is the melting point made visible, a state that exists only while one thing becomes another.","cn":"所以 sleet 是可见的融点，是一种只在一物变成另一物时存在的状态。"}]},"examples":[{"en":"The forecast warned of sleet on the passes after midnight.","cn":"预报提醒午夜后山口有雨夹雪。"},{"en":"Sleet had polished the pavement into a mirror.","cn":"雨夹雪把路面冻得像镜子一样亮。"},{"en":"It sleeted briefly before the sky cleared.","cn":"天空放晴前下了一小阵雨夹雪。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「湿粒」：又湿又冷的雪粒 → sleet 雨夹雪、冰粒","word":"sleet"},"root":"中古英语 slete「雨雪混合」，古英语形式无记录，更早来源不确定；一说与中古低地德语 slote、德语 Schloße「冰雹」有关，另一说与 slush 词基相关，均未定论。","sensesIntro":{"en":"Eight senses describe the halfway weather: rain mixed with snow, half-melted snow, American ice pellets, the glaze left behind, the road hazard, the verb, the forecast category and the first sign of a thaw.","cn":"八个义项描述这种「半路天气」：雨雪混合、半融的雪、美式冰粒、留下的冰壳、路面危险、动词、预报类别，以及解冻的第一个征兆。"},"semanticMap":{"core":{"en":"CORE IMAGE: precipitation at the melting point, neither clean snow nor plain rain.","cn":"核心意象：处在融点的降水，既不是干净的雪，也不是单纯的水。"},"chain":["RAIN AND SNOW","HALF MELTED","ICE PELLETS","SURFACE GLAZE","ROAD HAZARD","SEASONAL SIGN"],"branches":[{"senses":"01 · 02","en":"MIXTURE: the same slush is described once from the rain side and once from the snow side.","cn":"混合物：同一摊雪泥，一次从雨的一侧描述，一次从雪的一侧描述。"},{"senses":"03 · 07","en":"CLASSIFICATION: American pellets and the forecast box are two attempts to pin down the middle state.","cn":"分类：美式冰粒义与预报中的一格，是固定这一中间状态的两种努力。"},{"senses":"04","en":"RESULT: when the mixture lands, it becomes a glaze.","cn":"结果：混合物落地后变成一层冰壳。"},{"senses":"05","en":"CONSEQUENCE: the glaze turns into a closed road.","cn":"后果：冰壳变成封闭的道路。"},{"senses":"06 · 08","en":"PROCESS AND SEASON: the verb records the fall, and the timing marks the turn toward spring.","cn":"过程与季节：动词记录落下，出现的时间则标志转向春天。"}]},"affixes":{"intro":{"en":"Sleet is a small family: -y makes the adjective, and compound phrases name the shower, the warning and the mixed forecast.","cn":"sleet 的词族很小：-y 构成形容词，复合短语命名阵性降水、预警与混合预报。"},"latinIntro":{"en":"There is no Latin ancestor. Latin grando 'hail' and nix 'snow' are semantic neighbours, not relatives, so the Latin entry list is empty.","cn":"这里没有拉丁语祖先。拉丁语 grando「冰雹」与 nix「雪」只是语义邻居，并非亲属，因此拉丁词条列表留空。"},"items":[{"word":"sleety","structure":"sleet + -y (having the quality of)","meaning":"cold and wet with mixed rain and snow","meaningCN":"又冷又湿、夹着雨雪的（-y 表示「具有……性质的」）","example":"A sleety wind blew off the bay.","exampleCN":"一阵夹着雨雪的冷风从海湾吹来。"},{"word":"sleet shower","structure":"sleet + shower","meaning":"a short burst of mixed precipitation","meaningCN":"一阵短促的雨夹雪","example":"A sleet shower passed before dawn.","exampleCN":"黎明前下过一阵雨夹雪。"},{"word":"sleet warning","structure":"sleet + warning","meaning":"an official alert for slippery mixed precipitation","meaningCN":"针对湿滑混合降水的官方预警","example":"The sleet warning covered three counties.","exampleCN":"雨夹雪预警覆盖了三个县。"},{"word":"freezing sleet","structure":"freezing + sleet","meaning":"mixed precipitation that freezes on contact","meaningCN":"触物即冻的雨夹雪","example":"Freezing sleet sealed the car doors.","exampleCN":"冻雨夹雪把车门冻住了。"},{"word":"sleeting","structure":"sleet + -ing (participial noun)","meaning":"the ongoing fall of sleet","meaningCN":"正在下的雨夹雪（-ing 构成动名词）","example":"Sleeting kept the children indoors.","exampleCN":"雨夹雪让孩子们待在屋里。"},{"word":"wintry mix","structure":"wintry + mix","meaning":"a broadcast term for sleet, freezing rain and snow together","meaningCN":"气象播报中统称雨夹雪、冻雨与雪的术语","example":"The wintry mix made the morning commute slow.","exampleCN":"混合降水让早高峰变得缓慢。"},{"word":"ice pellet","structure":"ice + pellet","meaning":"the small frozen ball that American usage calls sleet","meaningCN":"美式用法称作 sleet 的小冰粒","example":"Ice pellets bounced off the hood.","exampleCN":"冰粒在引擎盖上弹跳。"},{"word":"slush","structure":"related Germanic word for melting snow","meaning":"snow and water mixed on the ground","meaningCN":"地面上雪与水混合的泥雪","example":"Slush filled the gutter by noon.","exampleCN":"到中午，排水沟里满是泥雪。"}],"latinEntries":[]}},{"word":"frost","ipa_uk":"/frɒst/","ipa_us":"/frɑːst/","definition_zh":"霜；霜冻；严寒期；结霜；糖霜；（态度）冷淡","definition_en":"a thin layer of white ice crystals that forms on cold surfaces, or a period of freezing weather","core_image":"清晨草叶上覆着一层白色冰晶，脚印一踩就留下深色的痕","scene":"一夜之间，草叶全被白霜盖住了。Frost had turned the grass white overnight.","sceneCN":"这里该词指「物体表面结成的白色冰晶」（第 1 个义项：霜层）；句意为一夜之间霜把草地变成了白色。","pos":[{"tag":"n.","zh":"霜；霜冻；严寒期；（蛋糕上的）糖霜"},{"tag":"vt.","zh":"使结霜；在蛋糕上撒糖霜"},{"tag":"vi.","zh":"结霜；受冻"}],"collocations":[{"phrase":"heavy frost","zh":"厚霜；重霜"},{"phrase":"a frost warning","zh":"霜冻预警"},{"phrase":"frost damage","zh":"霜害"},{"phrase":"a killing frost","zh":"致死霜冻"},{"phrase":"frost on the window","zh":"窗上的霜"},{"phrase":"a frosty morning","zh":"霜冷的早晨"}],"forms":[{"label":"不可数用法（霜层）","form":"frost（通常不可数）"},{"label":"复数（多次霜冻）","form":"frosts"},{"label":"形容词（霜冻的；冷淡的）","form":"frosty"},{"label":"动词（使结霜；去霜）","form":"frost / defrost"},{"label":"三单（动词）","form":"frosts"},{"label":"现在分词","form":"frosting"}],"derivatives":[{"word":"frosty","pos":"adj.","zh":"霜冻的；结霜的；冷淡的"},{"word":"frosting","pos":"n.","zh":"糖霜；结霜"},{"word":"frostbite","pos":"n.","zh":"冻伤"},{"word":"defrost","pos":"v.","zh":"除霜；解冻"},{"word":"frost-free","pos":"adj.","zh":"无霜的（冰箱等）"}],"senses":[{"no":"01","title":"White ice crystals on a surface","titleCN":"表面结出的白色冰晶","definition":"a thin white deposit of ice crystals formed when damp air freezes on a cold surface","definitionCN":"湿空气在冷表面上冻结时形成的薄薄白色冰晶层","example":"Frost had turned the grass white overnight.","exampleCN":"一夜之间，霜把草地变成了白色。","why":"Frost is not falling ice but grown ice: water vapour in the air crystallizes directly onto whatever is coldest.","whyCN":"霜不是落下的冰，而是长出来的冰：空气中的水汽直接在最冷的物体表面结晶。"},{"no":"02","title":"A period of freezing weather","titleCN":"一段严寒天气","definition":"a spell of weather cold enough to freeze water at night","definitionCN":"夜间冷到足以使水结冰的一段天气","example":"A late frost ruined the peach blossoms.","exampleCN":"一场晚霜毁了桃花。","why":"The deposit is evidence of a cold night, so the word also names the cold period that produced it.","whyCN":"霜层是寒夜的证据，所以这个词也指产生它的那段寒冷天气。"},{"no":"03","title":"The act of freezing","titleCN":"结冰这一过程","definition":"the process by which water turns to ice on a surface","definitionCN":"水在表面上变成冰的过程","example":"Frost begins in the hollows before it reaches the open field.","exampleCN":"霜先在洼地出现，然后才蔓延到开阔地。","why":"Cold air sinks into low ground, so the process is often described by where it starts.","whyCN":"冷空气沉入低地，所以这一过程常按它开始的地方来描述。"},{"no":"04","title":"A coating inside a freezer","titleCN":"冰箱内壁的霜层","definition":"the layer of ice that builds up on the inside of a freezer","definitionCN":"在冷冻室内壁逐渐积起的冰层","example":"Frost had sealed the freezer drawer shut.","exampleCN":"霜把冷冻抽屉封死了。","why":"The same process that whitens grass also coats cold machinery, so household ice inherits the name.","whyCN":"让草变白的同一过程也会覆盖冷机器，于是家用冰层继承了这一名称。"},{"no":"05","title":"Plant-killing cold","titleCN":"冻死植物的严寒","definition":"frost severe enough to damage or kill crops","definitionCN":"严重到能损害或冻死作物的霜冻","example":"The orchard lost its crop to a single hard frost.","exampleCN":"果园的收成毁于一场严霜。","why":"For growers, the word is a hazard measured by damage, not by beauty.","whyCN":"对种植者来说，这个词是按损失而非美景来衡量的危害。"},{"no":"06","title":"Icing on a cake","titleCN":"蛋糕上的糖霜","definition":"a sweet white coating spread on a cake, named for its likeness to frost","definitionCN":"涂在蛋糕上的白色甜涂层，因形似霜而得名","example":"She spread a thin frost of sugar over the cake.","exampleCN":"她在蛋糕上撒了一层薄薄的糖霜。","why":"The sugar looks like the ice deposit, so the same word was borrowed for the kitchen.","whyCN":"糖看起来像那层冰，于是同一个词被借到了厨房里。"},{"no":"07","title":"A cold manner","titleCN":"冷淡的态度","definition":"a cold, unfriendly reception or manner in a person","definitionCN":"人身上冷淡、不友好的接待或态度","example":"His suggestion met with a frost from the committee.","exampleCN":"他的建议遭到委员会冷冰冰的对待。","why":"The physical cold becomes social cold: a greeting that freezes the air is called a frost.","whyCN":"物理的冷变成社交的冷：把空气冻住的问候被称为 a frost。"},{"no":"08","title":"Ice on an aircraft","titleCN":"飞机表面的冰层","definition":"in aviation, ice that forms on wings and surfaces in freezing cloud","definitionCN":"航空中指在过冷云中于机翼和表面形成的冰","example":"Frost on the leading edge can spoil the airflow.","exampleCN":"机翼前缘的冰会破坏气流。","why":"The technical sense narrows the same deposit to a safety problem in flight.","whyCN":"技术义把这个同样的沉积物缩小成飞行中的安全问题。"}],"etymology":{"intro":{"en":"Frost is a native Germanic word with a well-attested history. Its PIE root is reconstructed, and the Latin cognates below are relatives rather than ancestors.","cn":"frost 是历史记录充分的日耳曼本土词。其原始印欧语词根属重构形式，下面的拉丁同源词是亲属而非祖先。"},"items":[{"era":"OLD ENGLISH","en":"Old English had both forst and frost, from Proto-Germanic *frustaz, and the word already meant both the ice deposit and the cold spell.","cn":"古英语同时有 forst 与 frost，出自原始日耳曼语 *frustaz，当时已兼指冰霜与寒潮。"},{"era":"PROTO-GERMANIC","en":"The noun belongs to the same family as freeze, from *freusan 'to freeze'; German Frost and Dutch vorst are its close cousins.","cn":"这个名词与 freeze 同族，出自 *freusan「冻结」；德语 Frost 与荷兰语 vorst 是近亲。"},{"era":"PROTO-INDO-EUROPEAN (reconstructed)","en":"The usual reconstruction is PIE *preus- 'to freeze, burn with cold', which also yields Latin pruina 'hoarfrost'.","cn":"通常重构为原始印欧语 *preus-「冻结、冻得发疼」，拉丁语 pruina「白霜」也出自此。"},{"era":"MIDDLE ENGLISH","en":"Middle English kept frost for weather and also used frosty for the look of a cold morning.","cn":"中古英语保留 frost 指天气，也用 frosty 形容寒冷早晨的样子。"},{"era":"MODERN ENGLISH (16c–19c)","en":"The culinary sense 'icing' appears in the sixteenth century, and the figurative 'cold reception' develops in the same period.","cn":"烹饪义「糖霜」出现于十六世纪，比喻义「冷淡接待」也在同一时期发展出来。"},{"era":"MODERN ENGLISH (20c)","en":"Aviation and refrigeration gave the word precise technical uses: airframe icing and the frost line in a freezer.","cn":"航空与制冷给这个词带来了精确的技术用法：机体结冰与冷冻室里的霜线。"}]},"similar":{"note":{"en":"Group one holds words that look or sound close to frost; group two holds other forms of frozen water on surfaces.","cn":"第一组是与 frost 字形或读音接近的词；第二组是表面上其他形态的冻结水。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"forest","ipa":"/ˈfɒrɪst/","tag":"near spelling","definition":"A large area of trees. It has an extra -e- and comes from Latin foris 'outside', a completely different family.","definitionCN":"大片树林。它多一个 -e-，出自拉丁语 foris「外面」，属完全不同的词族。"},{"word":"froth","ipa":"/frɒθ/","tag":"near spelling","definition":"A mass of small bubbles on a liquid; the ending is -th, and the word comes from a root for foam.","definitionCN":"液体表面的一层小气泡；词尾是 -th，词根意为泡沫。"},{"word":"front","ipa":"/frʌnt/","tag":"near sound","definition":"The forward part of something, or a weather boundary; the vowel is /ʌ/ and the final cluster is -nt.","definitionCN":"某物的前部，或气象锋面；元音是 /ʌ/，词尾是 -nt。"}]},{"heading":"NEAR MEANING","entries":[{"word":"hoarfrost","ipa":"/ˈhɔːfrɒst/","tag":"white crystal deposit","definition":"A white feathery frost formed by direct crystallization of vapour; it is the precise term for what frost often means loosely.","definitionCN":"水汽直接结晶形成的白色羽状霜；它是 frost 常被笼统指称之物的精确术语。"},{"word":"rime","ipa":"/raɪm/","tag":"wind-blown ice","definition":"Frozen fog deposited on windward surfaces; it is rougher and forms only in moving cloud.","definitionCN":"冻雾沉积在迎风面上的冰；它更粗糙，只在流动的云雾中形成。"},{"word":"freeze","ipa":"/friːz/","tag":"the process","definition":"To turn to ice, or a period of freezing; frost names the deposit and the cold spell, freeze names the change of state.","definitionCN":"变成冰，或一段严寒期；frost 指沉积物与寒潮，freeze 指状态变化。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Germanic relatives and real English compounds.","cn":"正常联想：使用真实的日耳曼亲属词与真实英语复合词。"},"normal":[{"en":"frost, freeze and frozen share one Germanic root: the noun names the result, the verb names the change.","cn":"frost、freeze、frozen 共享一个日耳曼词根：名词指结果，动词指变化。"},{"en":"frosty = frost + -y, the adjective for a morning that looks like frost.","cn":"frosty = frost + -y，形容早晨看上去像结了霜。"},{"en":"defrost = de- (remove) + frost, the setting that clears the freezer.","cn":"defrost = de-「去除」+ frost，即清除冷冻室积霜的档位。"},{"en":"frostbite = frost + bite: cold biting the skin until tissue is damaged.","cn":"frostbite = frost + bite：寒冷咬住皮肤，直到组织受损。"},{"en":"the frost line is the depth to which ground freezes in winter, a real engineering term.","cn":"frost line 是冬季土壤冻结的深度，是真实的工程术语。"}],"abstract":[{"en":"Abstractly, frost is cold made visible: invisible water vapour turns into a white script written on every surface.","cn":"抽象地看，frost 是变得可见的寒冷：看不见的水汽变成写在各表面上的白色字迹。"},{"en":"The same white layer can be beauty on grass, damage on a peach, ice in a freezer, or cold in a greeting.","cn":"同一层白色，在草上是美，在桃上是损失，在冷冻室是冰，在问候里则是冷淡。"},{"en":"So frost always marks a boundary where warm meets cold, whether in air, in food or in manners.","cn":"所以 frost 总标记着暖与冷相遇的边界，无论在空气里、食物里还是礼节里。"}]},"examples":[{"en":"The windows were covered with fern-like frost.","cn":"窗上覆着蕨叶状的霜。"},{"en":"Gardeners cover young plants when a frost is forecast.","cn":"预报有霜冻时，园丁会给幼苗盖上防护。"},{"en":"Her reply was polite but had a frost in it.","cn":"她的回答很客气，却透着冷淡。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「弗罗斯特」：清晨草上白白的冰晶 → frost 霜","word":"frost"},"root":"古英语 forst/frost，出自原始日耳曼语 *frustaz，与 freeze 同族；更早重构为原始印欧语 *preus-「冻结」，与拉丁语 pruina「白霜」同源。","sensesIntro":{"en":"Eight senses follow cold made visible: the crystal deposit, the cold spell, the freezing process, the freezer coating, the crop killer, the icing on a cake, the cold manner and the ice on a wing.","cn":"八个义项沿着「可见的寒冷」展开：冰晶层、寒潮、结冰过程、冷冻室霜层、冻死作物、蛋糕糖霜、冷淡态度，以及机翼上的冰。"},"semanticMap":{"core":{"en":"CORE IMAGE: water vapour crystallizing directly into white ice on the coldest surface.","cn":"核心意象：水汽在最冷的表面上直接结晶成白色冰。"},"chain":["ICE CRYSTALS","COLD SPELL","FREEZING PROCESS","SURFACE COATING","CROP DAMAGE","COLD MANNER"],"branches":[{"senses":"01 · 04","en":"DEPOSIT: the same crystal layer whitens grass and seals a freezer drawer.","cn":"沉积：同一层晶体让草变白，也把冷冻抽屉封住。"},{"senses":"02 · 03","en":"COLD AND ITS ACTION: the spell is the cause, the freezing is what it does.","cn":"寒冷与其作用：寒潮是原因，结冰是它做的事。"},{"senses":"05 · 08","en":"DAMAGE: the deposit kills blossoms on the ground and spoils airflow on a wing.","cn":"损害：这层沉积能冻死地上的花，也能破坏机翼上的气流。"},{"senses":"06","en":"LOOK-ALIKE COATING: sugar copies the white look for a cake.","cn":"形似的涂层：糖复制了这层白色外观，用在蛋糕上。"},{"senses":"07","en":"SOCIAL COLD: a frozen manner borrows the temperature of the weather.","cn":"社交的冷：冷淡的态度借用了天气的温度。"}]},"affixes":{"intro":{"en":"Frost is a Germanic base that takes native suffixes and compounds: -y and -ing build words, while de-, -bite and -free attach directly.","cn":"frost 是日耳曼词基，可接本土后缀与复合成分：-y 与 -ing 构词，de-、-bite、-free 直接附着。"},"latinIntro":{"en":"The Latin entries below are true cognates from PIE *preus-, not ancestors. Latin pruina 'hoarfrost' describes the same white deposit.","cn":"下面的拉丁条目是出自原始印欧语 *preus- 的真正同源词，而非祖先。拉丁语 pruina「白霜」描述同一种白色沉积。"},"items":[{"word":"frosty","structure":"frost + -y (having the quality)","meaning":"covered with frost, or cold in manner","meaningCN":"结霜的；态度冷淡的（-y 表示「具有……性质」）","example":"A frosty morning delayed the buses.","exampleCN":"霜冷的早晨使公交晚点。"},{"word":"frosting","structure":"frost + -ing (noun of result)","meaning":"icing on a cake, or a layer of frost","meaningCN":"蛋糕糖霜；结霜层（-ing 构成结果名词）","example":"The frosting cracked when the cake cooled.","exampleCN":"蛋糕冷却时糖霜裂开了。"},{"word":"frostbite","structure":"frost + bite","meaning":"injury to skin caused by extreme cold","meaningCN":"严寒造成的皮肤冻伤","example":"Frostbite turned his fingertips white.","exampleCN":"冻伤让他的指尖发白。"},{"word":"defrost","structure":"de- (remove) + frost","meaning":"to melt ice from a freezer or windscreen","meaningCN":"除霜；解冻（de- 表示「去除」）","example":"Defrost the chicken before roasting it.","exampleCN":"烤鸡之前先解冻。"},{"word":"frost-free","structure":"frost + -free (without)","meaning":"designed so that ice does not build up","meaningCN":"无霜的（设计上不积冰，-free 表示「没有」）","example":"A frost-free freezer saves electricity.","exampleCN":"无霜冰箱更省电。"},{"word":"hoarfrost","structure":"hoar (white, grey) + frost","meaning":"feathery white frost formed by direct crystallization","meaningCN":"由直接结晶形成的羽状白霜（hoar 表示「白、灰白」）","example":"Hoarfrost outlined every twig.","exampleCN":"白霜勾出了每根细枝的轮廓。"},{"word":"frost heave","structure":"frost + heave","meaning":"the lifting of soil caused by freezing water","meaningCN":"土壤水分冻结引起的抬升（冻胀）","example":"Frost heave cracked the road surface.","exampleCN":"冻胀把路面顶裂了。"},{"word":"frost line","structure":"frost + line","meaning":"the depth to which ground freezes in winter","meaningCN":"冬季土壤冻结达到的深度线","example":"Foundations must reach below the frost line.","exampleCN":"地基必须打到冻土线以下。"}],"latinEntries":[{"word":"pruina","structure":"Latin noun, PIE *preus-","meaning":"hoarfrost, rime","meaningCN":"白霜；雾凇"},{"word":"pruinosus","structure":"pruina + -osus (full of)","meaning":"covered with hoarfrost","meaningCN":"覆着白霜的"},{"word":"pruinose","structure":"Latin pruinosus → English adjective","meaning":"covered with a white frost-like bloom, as on a plum","meaningCN":"覆有白霜状粉层的，如李子表面的白霜"}]}},{"word":"freezing","ipa_uk":"/ˈfriːzɪŋ/","ipa_us":"/ˈfriːzɪŋ/","definition_zh":"结冰；冻结；冰点以下的；极冷的；冷冻保存","definition_en":"the process of turning into ice, or weather cold enough to freeze water","core_image":"清晨的水洼表面结成一层硬冰，下面的水还在，冰面却已能承住脚","scene":"清晨池塘边缘的水正在结冰。The pond was freezing at the edges by early morning.","sceneCN":"这里该词指「水正在变成冰的过程」（第 1 个义项：结冰过程）；句意为清晨池塘边缘正在结冰。","pos":[{"tag":"n.","zh":"结冰；冻结；冷冻保存"},{"tag":"adj.","zh":"冰点以下的；极冷的"},{"tag":"v.","zh":"freeze 的现在分词，表示正在冻结"}],"collocations":[{"phrase":"freezing point","zh":"冰点；凝固点"},{"phrase":"freezing weather","zh":"冰点以下的天气"},{"phrase":"freezing cold","zh":"冷得要命"},{"phrase":"freezing rain","zh":"冻雨"},{"phrase":"freezing temperatures","zh":"零下的气温"},{"phrase":"a freezing compartment","zh":"冷冻室"}],"forms":[{"label":"原形（动词）","form":"freeze"},{"label":"过去式","form":"froze"},{"label":"过去分词","form":"frozen"},{"label":"现在分词/名词/形容词","form":"freezing"},{"label":"名词（冷冻设备）","form":"freezer"},{"label":"形容词（冻结的）","form":"frozen"}],"derivatives":[{"word":"freeze","pos":"v./n.","zh":"结冰；冻结 / 冻结令"},{"word":"freezer","pos":"n.","zh":"冷冻柜；冰箱冷冻室"},{"word":"frozen","pos":"adj.","zh":"冰冻的；冻结的"},{"word":"freeze-dry","pos":"v.","zh":"冷冻干燥"},{"word":"anti-freeze","pos":"n.","zh":"防冻液"}],"senses":[{"no":"01","title":"Water turning to ice","titleCN":"水正在变成冰","definition":"the process by which liquid water becomes solid ice","definitionCN":"液态水变成固态冰的过程","example":"The pond was freezing at the edges by early morning.","exampleCN":"清晨池塘边缘正在结冰。","why":"The -ing form names an ongoing change of state, not the finished ice.","whyCN":"-ing 形式命名一个正在进行的状态变化，而不是已经完成的冰。"},{"no":"02","title":"Weather below zero","titleCN":"零下的天气","definition":"extremely cold weather, at or below the freezing point","definitionCN":"处于或低于冰点的极冷天气","example":"Freezing weather kept the harbour closed for a week.","exampleCN":"冰点以下的天气使港口关闭了一周。","why":"As an adjective the word describes air that would freeze water, so it works as a weather label.","whyCN":"作形容词时，它描述能把水冻住的空气，因此可用作天气标签。"},{"no":"03","title":"The freezing point","titleCN":"冰点","definition":"the temperature at which a liquid becomes solid","definitionCN":"液体变成固体的温度","example":"Salt lowers the freezing point of water below zero.","exampleCN":"盐把水的冰点降到零下。","why":"The process named by the participle supplies the fixed phrase for its threshold temperature.","whyCN":"分词所命名的过程，为其临界温度提供了固定短语。"},{"no":"04","title":"Preserving food by cold","titleCN":"用低温保存食物","definition":"storing food at temperatures low enough to stop spoilage","definitionCN":"在低到足以阻止腐败的温度下储存食物","example":"Freezing keeps the berries firm for a year.","exampleCN":"冷冻能让浆果紧实保存一年。","why":"Industry turned the physical process into a storage method and kept the participle as its name.","whyCN":"工业把这个物理过程变成储存方法，并保留了分词作为名称。"},{"no":"05","title":"An official freeze","titleCN":"官方的冻结令","definition":"a government or company order that wages, prices or funds may not change","definitionCN":"政府或公司规定工资、价格或资金不得变动的命令","example":"The freezing of rents lasted through the winter.","exampleCN":"租金冻结持续了整个冬天。","why":"Money that cannot move is imagined as water that cannot flow, so the cold image becomes economic policy.","whyCN":"不能流动的钱被想象成不能流动的水，于是寒冷的意象变成了经济政策。"},{"no":"06","title":"Frosty nights","titleCN":"有霜的夜晚","definition":"nights cold enough to leave frost on the ground","definitionCN":"冷到能在地面留下霜的夜晚","example":"Freezing nights have already hardened the soil.","exampleCN":"寒冷的夜晚已经把土壤冻硬了。","why":"The adjective extends from the temperature to the kind of night that produces visible frost.","whyCN":"这个形容词从温度延伸到会产生可见白霜的那种夜晚。"},{"no":"07","title":"Cold treatment in medicine","titleCN":"医学上的冷冻处理","definition":"the use of extreme cold to destroy or remove tissue","definitionCN":"用极低温破坏或去除组织的做法","example":"Freezing removes the wart without cutting.","exampleCN":"冷冻法不用刀就能去除疣。","why":"Medicine borrowed the process as a tool, naming the treatment after the cold itself.","whyCN":"医学把这个过程当作工具，用寒冷本身来命名治疗。"},{"no":"08","title":"Freeze-thaw weathering","titleCN":"冻融风化","definition":"the repeated freezing and thawing of water in rock cracks","definitionCN":"岩石裂缝中的水反复冻结与融化","example":"Freezing splits the limestone a little more each winter.","exampleCN":"每个冬天，冻结都让石灰岩多裂开一点。","why":"Water expands as it freezes, so the participle names the geological force that pries rock apart.","whyCN":"水结冰时膨胀，于是这个分词命名了把岩石撬开的地质力量。"}],"etymology":{"intro":{"en":"Freezing is the participle of freeze plus -ing. The verb is native Germanic; its PIE root is a reconstruction. Dates are approximate.","cn":"freezing 是 freeze 加分词后缀 -ing。动词是日耳曼本土词；其原始印欧语词根属重构形式。年代为大致估计。"},"items":[{"era":"OLD ENGLISH","en":"Freeze goes back to Old English freosan, a strong verb with past tense freas and participle froren.","cn":"freeze 源自古英语 freosan，是一个强变化动词，过去式为 freas，过去分词为 froren。"},{"era":"PROTO-GERMANIC","en":"The verb is reconstructed as *freusan, with German frieren and Dutch vriezen as close relatives.","cn":"该动词被重构为 *freusan，德语 frieren 与荷兰语 vriezen 是近亲。"},{"era":"PROTO-INDO-EUROPEAN (reconstructed)","en":"The standard reconstruction is PIE *preus- 'to freeze, burn with cold', also behind Latin pruina 'hoarfrost'.","cn":"标准重构为原始印欧语 *preus-「冻结、冻得发疼」，拉丁语 pruina「白霜」也出自此。"},{"era":"MIDDLE ENGLISH","en":"Middle English replaced the old participle with frozen, modelled on the past participle of strong verbs, and the -ing form became the regular participle.","cn":"中古英语以 frozen 取代旧分词，仿照强变化动词的过去分词形式，-ing 形式则成为规则分词。"},{"era":"MODERN ENGLISH (18c–19c)","en":"Freezing point is fixed as a scientific phrase in the eighteenth century, and industrial food freezing develops in the nineteenth.","cn":"freezing point 在十八世纪被固定为科学短语，工业食品冷冻在十九世纪发展起来。"},{"era":"MODERN ENGLISH (20c)","en":"The economic 'freeze' and the medical cold treatment both standardize the participle as a technical noun.","cn":"经济上的「冻结」与医学冷冻治疗都把这一分词固定为技术名词。"}]},"similar":{"note":{"en":"Group one holds words that look or sound close to freezing; group two holds adjectives for extreme cold.","cn":"第一组是与 freezing 字形或读音接近的词；第二组是表示极冷的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"frieze","ipa":"/friːz/","tag":"sound-alike","definition":"A decorative band along a wall, or a heavy woollen cloth; it is a noun with no idea of ice.","definitionCN":"墙面上的装饰带，或厚重毛呢；它是名词，与冰无关。"},{"word":"freebie","ipa":"/ˈfriːbi/","tag":"near sound","definition":"Something given for free; it comes from free, not from freeze.","definitionCN":"免费赠品；出自 free，而不是 freeze。"},{"word":"sneezing","ipa":"/ˈsniːzɪŋ/","tag":"same ending","definition":"The act of expelling air suddenly through the nose; only the -ing ending matches.","definitionCN":"突然从鼻子喷气的动作；只有 -ing 词尾相同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"frozen","ipa":"/ˈfrəʊzn/","tag":"finished state","definition":"Already turned to ice; it is the result, while freezing is the process.","definitionCN":"已经变成冰；它是结果，而 freezing 是过程。"},{"word":"icy","ipa":"/ˈaɪsi/","tag":"covered with ice","definition":"Covered with ice or very cold in manner; it describes a surface or a tone, not a process.","definitionCN":"覆着冰的，或态度冰冷的；它描述表面或语气，而不是过程。"},{"word":"frigid","ipa":"/ˈfrɪdʒɪd/","tag":"formal cold","definition":"Extremely cold, often in a formal or technical tone; it comes from Latin frigidus, a different family.","definitionCN":"极冷的，常带正式或技术语气；出自拉丁语 frigidus，属另一词族。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real verb forms, real compounds, and one genuine Latin cognate.","cn":"正常联想：真实的动词形式、真实的复合词，以及一个真正的拉丁同源词。"},"normal":[{"en":"freeze–froze–frozen: the old strong verb keeps its irregular past, and freezing is the regular -ing form built on the base.","cn":"freeze–froze–frozen：这个古老强变化动词保留不规则过去式，freezing 则是在词基上加规则 -ing。"},{"en":"freezer = freeze + -er, the appliance that does the freezing.","cn":"freezer = freeze + -er，做冷冻这件事的器具。"},{"en":"freezing point pairs the process with its threshold, just as boiling point does for heat.","cn":"freezing point 把过程与临界点配对，正如 boiling point 对热所做的那样。"},{"en":"freeze-dry = freeze + dry: ice is removed as vapour without melting, a real preservation method.","cn":"freeze-dry = freeze + dry：冰不经融化直接升华，是真实的保存方法。"},{"en":"anti-freeze = anti- (against) + freeze, the additive that stops a radiator from freezing.","cn":"anti-freeze = anti-「反对」+ freeze，防止水箱结冰的添加剂。"}],"abstract":[{"en":"Abstractly, freezing is motion stopping: water loses its flow and becomes a solid that holds its shape.","cn":"抽象地看，freezing 是运动停止：水失去流动，变成保持形状的固体。"},{"en":"The same stopping can be applied to wages, to tissue, to a pond or to a rock crack.","cn":"同样的「停住」可以用在工资、组织、池塘或岩石裂缝上。"},{"en":"So freezing is not simply cold but the moment a thing can no longer move.","cn":"所以 freezing 不只是冷，而是一物再也不能移动的那一刻。"}]},"examples":[{"en":"Freezing temperatures overnight damaged the young shoots.","cn":"夜间的零下气温冻坏了新芽。"},{"en":"The lab stores the samples by freezing them in liquid nitrogen.","cn":"实验室用液氮冷冻保存样本。"},{"en":"Freezing and thawing slowly breaks the cliff face apart.","cn":"冻融交替慢慢把崖面裂开。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"freeze（冻住）+ -ing：正在冻住 → freezing 结冰、极冷的","word":"freezing"},"root":"freeze 源自古英语 freosan，出自原始日耳曼语 *freusan，更早重构为原始印欧语 *preus-「冻结」；freezing 为其 -ing 分词形式。","sensesIntro":{"en":"Eight senses follow water losing its motion: the process, the cold air, the threshold, food storage, a price freeze, frosty nights, cold surgery and the freeze-thaw that splits rock.","cn":"八个义项沿着「水失去运动」展开：过程、冷空气、临界点、食物储存、价格冻结、有霜的夜、冷冻手术，以及把岩石劈开的冻融。"},"semanticMap":{"core":{"en":"CORE IMAGE: liquid stops moving and locks into a shape.","cn":"核心意象：液体停止流动，锁定成一个形状。"},"chain":["WATER TO ICE","COLD AIR","ZERO POINT","FOOD STORAGE","PRICE FREEZE","WEATHERING"],"branches":[{"senses":"01 · 08","en":"PHYSICAL PROCESS: a pond and a rock crack freeze by the same expansion of water.","cn":"物理过程：池塘与岩石裂缝靠同一个水膨胀原理冻结。"},{"senses":"02 · 06","en":"WEATHER: air below zero and the frosty night it produces.","cn":"天气：零下的空气与它带来的霜夜。"},{"senses":"03","en":"THRESHOLD: the process becomes a fixed number on a thermometer.","cn":"临界点：过程变成温度计上的一个固定数字。"},{"senses":"04","en":"METHOD: industry uses the process to keep food from spoiling.","cn":"方法：工业用这个过程防止食物腐败。"},{"senses":"05 · 07","en":"STOPPING THINGS: money and tissue are both held still by cold or by order.","cn":"使物停住：资金与组织都被寒冷或命令定住。"}]},"affixes":{"intro":{"en":"Freezing belongs to the freeze family: -er names the machine, -ing names the process, and compounds like anti-freeze and freeze-dry add direction or method.","cn":"freezing 属于 freeze 词族：-er 命名机器，-ing 命名过程，anti-freeze、freeze-dry 等复合词则补充方向或方法。"},"latinIntro":{"en":"Freeze is Germanic, but it shares a PIE root with Latin pruina 'hoarfrost'. The Latin entries below are cognates, not ancestors.","cn":"freeze 属日耳曼语，但与拉丁语 pruina「白霜」共享原始印欧语词根。下面的拉丁条目是同源词，不是祖先。"},"items":[{"word":"freeze","structure":"base verb of the family","meaning":"to turn to ice; also a government order stopping prices","meaningCN":"结冰；也指政府停止价格变动的命令","example":"The lake freezes in December.","exampleCN":"湖在十二月结冰。"},{"word":"freezer","structure":"freeze + -er (agent or instrument)","meaning":"an appliance that keeps things frozen","meaningCN":"使物品保持冷冻的器具（-er 表示施动者或工具）","example":"Put the meat in the freezer.","exampleCN":"把肉放进冷冻柜。"},{"word":"frozen","structure":"old strong past participle of freeze","meaning":"turned to ice; also unable to move","meaningCN":"已冻成冰的；也指动弹不得的","example":"The pipes were frozen solid.","exampleCN":"水管冻得结结实实。"},{"word":"freezing point","structure":"freezing + point","meaning":"the temperature at which a liquid solidifies","meaningCN":"液体凝固的温度，即冰点","example":"Brine has a lower freezing point than water.","exampleCN":"盐水的冰点比水低。"},{"word":"freeze-dry","structure":"freeze + dry","meaning":"to preserve by freezing and then removing ice as vapour","meaningCN":"先冷冻再让冰直接升华的干燥保存法","example":"They freeze-dry the coffee for instant use.","exampleCN":"他们把咖啡冻干做成速溶。"},{"word":"anti-freeze","structure":"anti- (against) + freeze","meaning":"a liquid added to water to stop it freezing","meaningCN":"加入水中防止结冰的液体（anti- 表示「抗、防」）","example":"Check the anti-freeze before winter.","exampleCN":"入冬前检查防冻液。"},{"word":"deep-freeze","structure":"deep + freeze","meaning":"a very cold freezer, or to store at very low temperature","meaningCN":"深度冷冻柜；或指在极低温下储存","example":"The specimens went into deep-freeze.","exampleCN":"标本被放入深度冷冻。"},{"word":"freezing rain","structure":"freezing + rain","meaning":"rain that stays liquid in cold air and freezes on contact","meaningCN":"在冷空气中保持液态、触物即冻的雨，即冻雨","example":"Freezing rain closed the airport.","exampleCN":"冻雨使机场关闭。"}],"latinEntries":[{"word":"pruina","structure":"Latin noun, PIE *preus-","meaning":"hoarfrost","meaningCN":"白霜"},{"word":"pruinosus","structure":"pruina + -osus","meaning":"frost-covered","meaningCN":"覆着白霜的"},{"word":"pruinose","structure":"Latin pruinosus → English","meaning":"bearing a white frost-like bloom","meaningCN":"带白霜状粉层的"}]}},{"word":"thaw","ipa_uk":"/θɔː/","ipa_us":"/θɔː/","definition_zh":"解冻；融化；（关系）缓和；解冻期","definition_en":"to melt after being frozen, or a period of warmer weather that melts ice and snow","core_image":"河面的冰裂开一道缝，露出下面黑亮的水，冰沿慢慢后退","scene":"午后阳光照在河面上，冰开始裂开融化。The ice on the river began to thaw in the afternoon sun.","sceneCN":"这里该词指「冰冻之物开始融化」（第 1 个义项：冰或雪解冻）；句意为河上的冰在午后阳光下开始融化。","pos":[{"tag":"vi.","zh":"解冻；融化；（关系、态度）缓和"},{"tag":"vt.","zh":"使解冻；使融化"},{"tag":"n.","zh":"解冻期；融化状态"}],"collocations":[{"phrase":"spring thaw","zh":"春季解冻"},{"phrase":"thaw out","zh":"解冻；暖和过来"},{"phrase":"the ice begins to thaw","zh":"冰开始融化"},{"phrase":"a thaw in relations","zh":"关系的缓和"},{"phrase":"thaw the meat","zh":"把肉解冻"},{"phrase":"permafrost thaw","zh":"永久冻土融化"}],"forms":[{"label":"三单（动词）","form":"thaws"},{"label":"过去式","form":"thawed"},{"label":"过去分词","form":"thawed"},{"label":"现在分词","form":"thawing"},{"label":"复数（名词，多次解冻期）","form":"thaws"},{"label":"形容词（解冻的）","form":"thawed"}],"derivatives":[{"word":"thawing","pos":"n./adj.","zh":"解冻；融化中的"},{"word":"thawed","pos":"adj.","zh":"已解冻的"},{"word":"thaw out","pos":"phr.","zh":"解冻；暖和过来"},{"word":"spring thaw","pos":"n.","zh":"春季解冻"},{"word":"permafrost thaw","pos":"n.","zh":"永久冻土融化"}],"senses":[{"no":"01","title":"Ice or snow melts","titleCN":"冰或雪融化","definition":"to become liquid again after being frozen","definitionCN":"冻结之后重新变成液体","example":"The ice on the river began to thaw in the afternoon sun.","exampleCN":"河上的冰在午后阳光下开始融化。","why":"Thaw is the opposite of freeze, and it names the return of water from a locked solid to a moving liquid.","whyCN":"thaw 是 freeze 的反面，命名水从锁住的固体回到流动液体的过程。"},{"no":"02","title":"A warm spell","titleCN":"一段回暖的时期","definition":"a period of weather warm enough to melt snow and ice","definitionCN":"暖到能融化冰雪的一段天气","example":"A January thaw turned the lanes to mud.","exampleCN":"一月的一次回暖把小路变成了泥浆。","why":"When the melting lasts for days, the process becomes a named season within winter.","whyCN":"当融化持续数日，这个过程就成了冬天里有名字的一段时节。"},{"no":"03","title":"The melted state","titleCN":"融化后的状态","definition":"the condition of having been melted, as in food that is no longer frozen","definitionCN":"已经融化的状态，如不再冰冻的食物","example":"The meat is in thaw and should be cooked today.","exampleCN":"肉已经解冻，今天该做掉。","why":"A noun use records the result rather than the action, useful when the change is already complete.","whyCN":"名词用法记录结果而非动作，在变化已经完成时很有用。"},{"no":"04","title":"Relations become friendlier","titleCN":"关系缓和","definition":"of relations or attitudes, to become less hostile and more open","definitionCN":"指关系或态度变得不那么敌对、更加开放","example":"Relations between the two neighbours thawed after the meeting.","exampleCN":"会面之后，两家的关系缓和了。","why":"Frozen relations are rigid and silent; warmth lets them move again, so the ice image becomes diplomacy.","whyCN":"冻结的关系僵硬而沉默；暖意让它们重新流动，于是冰的意象变成了外交。"},{"no":"05","title":"Defrost frozen food","titleCN":"解冻食物","definition":"to let frozen food stand until it is no longer hard","definitionCN":"让冷冻食物放置到不再坚硬","example":"Thaw the fish overnight in the fridge.","exampleCN":"把鱼放在冰箱里解冻一夜。","why":"Food follows the physical rule: heat flows in, ice turns to water, and the solid becomes usable.","whyCN":"食物遵循同样的物理规律：热量流入，冰变成水，固体变得可用。"},{"no":"06","title":"Rules or policies soften","titleCN":"规定或政策松动","definition":"of rules or policies, to become less strict","definitionCN":"指规定或政策变得不那么严格","example":"The new government thawed the restrictions on travel.","exampleCN":"新政府放宽了旅行限制。","why":"A frozen rule cannot bend; a thawed one can, so the metaphor covers political liberalization.","whyCN":"冻结的规则不能弯；解冻后的可以，所以这个比喻覆盖政治上的放宽。"},{"no":"07","title":"Permafrost melting","titleCN":"永久冻土融化","definition":"the melting of permanently frozen ground in polar regions","definitionCN":"极地地区常年冻结地面的融化","example":"Permafrost thaw is collapsing the Arctic roads.","exampleCN":"永久冻土融化正在使北极的道路塌陷。","why":"In climate science the subject is ground rather than ice on water, but the change of state is the same.","whyCN":"在气候科学中，主体是土地而不是水面上的冰，但状态变化相同。"},{"no":"08","title":"A person warms up","titleCN":"人暖和过来","definition":"of a person, to become warm again after being very cold","definitionCN":"指人在极冷之后重新暖和起来","example":"She thawed out by the fire with a mug of tea.","exampleCN":"她在炉边捧着一杯茶暖和过来。","why":"The body is the frozen object here, and the word describes circulation returning.","whyCN":"这里被冻住的对象是身体，这个词描述血液循环恢复。"}],"etymology":{"intro":{"en":"Thaw is a native Germanic verb. Its link to the PIE root for melting is generally accepted, though the exact root shape is reconstructed.","cn":"thaw 是日耳曼本土动词。它与原始印欧语「融化」词根的联系一般被接受，但确切词根形状属重构。"},"items":[{"era":"OLD ENGLISH","en":"Old English þawian meant 'to thaw', and the noun þaw 'thawing' also existed.","cn":"古英语 þawian 意为「解冻」，名词 þaw「解冻」也已存在。"},{"era":"PROTO-GERMANIC","en":"The verb is reconstructed as *thawon, with Dutch dooien and German tauen as close relatives.","cn":"该动词被重构为 *thawon，荷兰语 dooien 与德语 tauen 是近亲。"},{"era":"PROTO-INDO-EUROPEAN (reconstructed)","en":"It is generally connected with PIE *tā- 'to melt', the source of Latin tabes 'melting, decay' and tabidus 'wasting away'.","cn":"它一般被联系到原始印欧语 *tā-「融化」，拉丁语 tabes「融化、衰败」与 tabidus「消耗的」即出自此。"},{"era":"MIDDLE ENGLISH","en":"Middle English thawen kept the physical sense and began to be used for frozen food as well as for ice.","cn":"中古英语 thawen 保留物理义，并开始既用于冰也用于冷冻食物。"},{"era":"MODERN ENGLISH (19c–20c)","en":"The figurative 'thaw in relations' is recorded in the nineteenth century, and climate science later applied the word to permafrost.","cn":"比喻性的「关系缓和」在十九世纪有记录，气候科学后来又把该词用到永久冻土上。"}]},"similar":{"note":{"en":"Group one holds short words that look or sound close to thaw; group two holds other words for ice turning to water.","cn":"第一组是与 thaw 字形或读音接近的短词；第二组是表示冰化成水的其他词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"thou","ipa":"/ðaʊ/","tag":"near spelling","definition":"An old form of you; the vowel is a diphthong /aʊ/ and the meaning is unrelated.","definitionCN":"古体的「你」；元音是双元音 /aʊ/，意义无关。"},{"word":"thorn","ipa":"/θɔːn/","tag":"near sound","definition":"A sharp spine on a plant; it shares the first sound but ends in -rn.","definitionCN":"植物上的尖刺；它共享开头音，但词尾是 -rn。"},{"word":"thought","ipa":"/θɔːt/","tag":"near sound","definition":"An idea, or the past of think; the vowel is similar but the final cluster is -ght.","definitionCN":"想法，或 think 的过去式；元音相近，但词尾是 -ght。"}]},{"heading":"NEAR MEANING","entries":[{"word":"melt","ipa":"/melt/","tag":"turn to liquid","definition":"To become liquid by heat; it works for ice, butter and metal, while thaw usually implies something was frozen.","definitionCN":"受热变成液体；可用于冰、黄油与金属，而 thaw 通常暗示原先被冻住。"},{"word":"defrost","ipa":"/dɪˈfrɒst/","tag":"remove frost","definition":"To remove ice from a freezer or windscreen; it is a purposeful action, not merely a rise in temperature.","definitionCN":"清除冷冻柜或挡风玻璃上的冰；它是有意为之的动作，而不只是温度上升。"},{"word":"soften","ipa":"/ˈsɒftn/","tag":"figurative use","definition":"To make less hard or less severe; it is the general word behind figurative 'relations thaw'.","definitionCN":"使变软或使缓和；它是比喻性「关系解冻」背后的通用词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real verb forms and real climate terms.","cn":"正常联想：真实的动词形式与真实气候术语。"},"normal":[{"en":"thaw is the direct opposite of freeze; a frozen pond thaws when warm air arrives.","cn":"thaw 是 freeze 的直接反面；暖空气到来时，冻住的池塘就会 thaw。"},{"en":"thaw out is the phrasal form used for people and pipes: warmth returns to something that was stiff with cold.","cn":"thaw out 是用于人和管道的短语形式：暖意回到被冻僵的东西上。"},{"en":"spring thaw is the standard phrase for the seasonal melt that floods rivers.","cn":"spring thaw 是描述季节性融雪、使河水上涨的标准说法。"},{"en":"permafrost thaw pairs the verb with the ground that never used to melt.","cn":"permafrost thaw 把这个动词与原本从不融化的土地配在一起。"},{"en":"a thaw in relations uses the ice image for politics, just as a freeze in talks uses the opposite image.","cn":"a thaw in relations 把冰的意象用于政治，正如 a freeze in talks 用相反的意象。"}],"abstract":[{"en":"Abstractly, thaw is the return of movement: what was locked becomes liquid and can flow again.","cn":"抽象地看，thaw 是运动的回归：被锁住的东西变成液体，重新可以流动。"},{"en":"The same return can happen to ice, to frozen food, to permafrost, to a frozen relationship or to frozen rules.","cn":"同样的回归可以发生在冰、冷冻食物、永久冻土、冻结的关系或冻结的规则上。"},{"en":"So thaw always implies a previous cold state and a new permission to move.","cn":"所以 thaw 总暗示先前的寒冷状态，以及新的「可以活动」的许可。"}]},"examples":[{"en":"The river thawed earlier than usual this year.","cn":"今年这条河比往年更早解冻。"},{"en":"Leave the frozen peas to thaw on the counter.","cn":"把冻豌豆放在台面上解冻。"},{"en":"Talks resumed after a slight thaw between the two sides.","cn":"双方关系略有缓和后，谈判重新开始。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「套」：冰套子融开了 → thaw 解冻","word":"thaw"},"root":"古英语 þawian「解冻」，出自原始日耳曼语 *thawon，更早一般联系到原始印欧语 *tā-「融化」，与拉丁语 tabes「融化、衰败」同源；确切词根形状属重构。","sensesIntro":{"en":"Eight senses follow ice giving way: the melt, the warm spell, the melted state, friendlier relations, thawed food, looser rules, melting permafrost and a person warming up.","cn":"八个义项沿着「冰让位」展开：融化、回暖期、融化状态、关系缓和、食物解冻、规定松动、冻土融化，以及人暖和过来。"},"semanticMap":{"core":{"en":"CORE IMAGE: a locked solid opens and lets water move again.","cn":"核心意象：锁住的固体松开，让水重新流动。"},"chain":["ICE MELTS","WARM SPELL","MELTED STATE","FROZEN FOOD","RIGID RULES","WARMING BODY"],"branches":[{"senses":"03","en":"THE MELTED STATE: the same event seen after it ends.","cn":"融化后的状态：同一事件结束后的样子。"},{"senses":"02 · 07","en":"SCALE: a winter warm spell and a melting Arctic both measure the same change over time.","cn":"尺度：冬季回暖与北极融化都在时间尺度上度量同一种变化。"},{"senses":"05 · 08","en":"WARMTH ARRIVES: food and a cold person both wait for heat to enter.","cn":"暖意到来：食物与受冻的人都在等待热量进入。"},{"senses":"04 · 06","en":"SOCIAL THAW: relations and rules become less frozen and more movable.","cn":"社会解冻：关系与规则不再那么冻结，变得更可松动。"},{"senses":"01","en":"PHYSICAL BASE: all the other senses borrow the melting of ice.","cn":"物理基础：其余所有义项都借用了冰的融化。"}]},"affixes":{"intro":{"en":"Thaw is a small Germanic family; most of its extensions are phrasal verbs and fixed weather compounds rather than suffixes.","cn":"thaw 是一个小的日耳曼词族；其扩展多为短语动词与固定天气复合词，而非后缀派生。"},"latinIntro":{"en":"The Latin entries below are cognates from PIE *tā-, not ancestors. Latin tabes 'melting, decay' shows the same root without the ice.","cn":"下面的拉丁条目是出自原始印欧语 *tā- 的同源词，而非祖先。拉丁语 tabes「融化、衰败」显示同一词根，只是不带冰。"},"items":[{"word":"thawing","structure":"thaw + -ing (participial noun)","meaning":"the process of melting","meaningCN":"融化的过程（-ing 构成动名词）","example":"Thawing releases water into the soil.","exampleCN":"融化把水释放到土壤里。"},{"word":"thawed","structure":"thaw + -ed (past participle)","meaning":"no longer frozen","meaningCN":"已解冻的（-ed 构成过去分词）","example":"Use the thawed berries today.","exampleCN":"今天就用解冻的浆果。"},{"word":"thaw out","structure":"thaw + out (phrasal verb)","meaning":"to warm up after being very cold","meaningCN":"在极冷之后暖和过来（out 表示「出来」）","example":"We thawed out beside the stove.","exampleCN":"我们在炉子边暖和过来。"},{"word":"spring thaw","structure":"spring + thaw","meaning":"the seasonal melt at the end of winter","meaningCN":"冬末的季节性融雪","example":"The spring thaw floods the low fields.","exampleCN":"春季融雪淹了低洼的田地。"},{"word":"permafrost thaw","structure":"permafrost + thaw","meaning":"the melting of permanently frozen ground","meaningCN":"永久冻土的融化","example":"Permafrost thaw undermines the pipeline.","exampleCN":"永久冻土融化正在削弱管道基础。"},{"word":"thaw season","structure":"thaw + season","meaning":"the part of the year when ice melts","meaningCN":"一年中冰雪融化的时段","example":"Travel is restricted during the thaw season.","exampleCN":"解冻季节限制通行。"},{"word":"thaw lake","structure":"thaw + lake","meaning":"a pond formed by melting ground ice","meaningCN":"地下冰融化形成的水塘","example":"The thaw lake grew wider each summer.","exampleCN":"这个融冻湖每个夏天都变宽。"},{"word":"thaw water","structure":"thaw + water","meaning":"meltwater from snow and ice","meaningCN":"冰雪融化产生的水","example":"Thaw water filled the ditches.","exampleCN":"融水灌满了沟渠。"}],"latinEntries":[{"word":"tabes","structure":"Latin noun, PIE *tā-","meaning":"melting, wasting away, decay","meaningCN":"融化；消耗；衰败"},{"word":"tabidus","structure":"tabes + -idus","meaning":"wasting away, melting","meaningCN":"消耗中的；融化中的"},{"word":"tabid","structure":"Latin tabidus → English adjective","meaning":"wasting away, shrivelled","meaningCN":"消瘦的；萎缩的"}]}},{"word":"temperature","ipa_uk":"/ˈtemprətʃə/","ipa_us":"/ˈtemprətʃər/","definition_zh":"温度；体温；发烧；气温","definition_en":"a measure of how hot or cold something is","core_image":"墙上的温度计里，红色液柱停在一个刻度上，室内外差出一大截","scene":"实验室墙上的温度计显示，室内比室外高许多。The thermometer showed a temperature ten degrees higher indoors.","sceneCN":"这里该词指「可测量的冷热程度」（第 1 个义项：温度读数）；句意为温度计显示室内温度比室外高十度。","pos":[{"tag":"n.","zh":"温度；体温；发烧；气温"}],"collocations":[{"phrase":"room temperature","zh":"室温；常温"},{"phrase":"body temperature","zh":"体温"},{"phrase":"high temperature","zh":"高温；高烧"},{"phrase":"temperature drop","zh":"温度下降"},{"phrase":"a rise in temperature","zh":"温度上升"},{"phrase":"temperature control","zh":"温度控制"}],"forms":[{"label":"复数（多个读数）","form":"temperatures"},{"label":"形容词（温带的；有节制的）","form":"temperate"},{"label":"名词（性情；气质）","form":"temperament"},{"label":"动词（调和；使缓和）","form":"temper"},{"label":"测量仪器","form":"thermometer"},{"label":"恒温器","form":"thermostat"}],"derivatives":[{"word":"temper","pos":"v./n.","zh":"调和；使缓和 / 脾气"},{"word":"temperate","pos":"adj.","zh":"温带的；有节制的"},{"word":"temperament","pos":"n.","zh":"性情；气质"},{"word":"thermometer","pos":"n.","zh":"温度计"},{"word":"thermostat","pos":"n.","zh":"恒温器"}],"senses":[{"no":"01","title":"A measured degree of heat","titleCN":"测得的冷热程度","definition":"a number expressing how hot or cold a body or space is","definitionCN":"表示物体或空间冷热程度的数值","example":"The thermometer showed a temperature ten degrees higher indoors.","exampleCN":"温度计显示室内温度比室外高十度。","why":"The Latin source means 'a tempering or moderation'; early science used it for the balance of hot and cold in a body, then for the measured balance itself.","whyCN":"拉丁词源意为「调和、适度」；早期科学用它指体内冷热的平衡，后来指被测出的这个平衡。"},{"no":"02","title":"Body heat","titleCN":"体温","definition":"the internal heat of a living body, normally around thirty-seven degrees","definitionCN":"活体内部的温度，正常约三十七度","example":"The nurse recorded the patient's temperature twice a day.","exampleCN":"护士每天记录病人两次体温。","why":"A living body regulates its own balance of heat, which is exactly what the old sense of tempering described.","whyCN":"活体自行调节冷热平衡，这正是旧义「调和」所描述的。"},{"no":"03","title":"The weather figure","titleCN":"气温读数","definition":"the outdoor air temperature reported in a forecast","definitionCN":"预报中报告的室外空气温度","example":"The forecast gives a temperature of minus five tonight.","exampleCN":"预报说今晚气温为零下五度。","why":"Air is a body too, and meteorology applies the same measurement to the atmosphere.","whyCN":"空气也是一种物体，气象学把同一测量用到大气上。"},{"no":"04","title":"A fever","titleCN":"发烧","definition":"an abnormally high body temperature caused by illness","definitionCN":"疾病引起的异常升高的体温","example":"The child has a temperature and should stay home.","exampleCN":"孩子发烧了，应该待在家里。","why":"In everyday speech a 'temperature' means the raised figure, not the normal one, so the measurement stands for the illness.","whyCN":"日常口语中 a temperature 指升高的那个数值，而不是正常值，于是测量结果代表了疾病。"},{"no":"05","title":"A device set point","titleCN":"设备设定的温度点","definition":"the target temperature set on a thermostat or oven","definitionCN":"在恒温器或烤箱上设定的目标温度","example":"Set the temperature to two hundred degrees before baking.","exampleCN":"烘烤前把温度设为两百度。","why":"A control dial turns the noun into an instruction: the temperature is what the machine is told to reach.","whyCN":"控制旋钮把这个名词变成指令：温度是机器被要求达到的值。"},{"no":"06","title":"The emotional climate","titleCN":"情绪氛围","definition":"the general mood or level of tension in a group","definitionCN":"一个群体中的总体情绪或紧张程度","example":"The temperature of the debate rose after the announcement.","exampleCN":"声明发布后，辩论的火气升高了。","why":"Social heat is read like physical heat: a room can become hot with anger.","whyCN":"社会的热像物理的热一样被读取：一个房间可以因愤怒而变热。"},{"no":"07","title":"A physical quantity","titleCN":"物理量","definition":"in physics, a property measuring the average kinetic energy of particles","definitionCN":"物理学中衡量粒子平均动能的属性","example":"The temperature of the gas rises as the piston compresses it.","exampleCN":"活塞压缩气体时，气体温度升高。","why":"Physics narrows the everyday number to a precise property of a system.","whyCN":"物理学把日常数字收窄为系统的精确属性。"},{"no":"08","title":"A standard condition","titleCN":"标准条件（常温）","definition":"the ordinary indoor heat at which materials and reactions are compared","definitionCN":"比较材料与反应时所用的通常室内温度","example":"Store the reagent at room temperature.","exampleCN":"把试剂存放在室温下。","why":"Labs need a standard, so 'room temperature' becomes a fixed benchmark rather than a description.","whyCN":"实验室需要一个标准，于是「室温」成了固定基准而不是描述。"}],"etymology":{"intro":{"en":"Temperature comes from Latin temperatura 'a tempering, a due mixture'. The modern physical sense is a later narrowing. Dates are approximate.","cn":"temperature 出自拉丁语 temperatura「调和、适当的混合」。现代物理义是后来的收窄。年代为大致估计。"},"items":[{"era":"CLASSICAL LATIN","en":"Temperatura meant a mixing in due proportion, from temperare 'to mix, regulate, restrain'.","cn":"temperatura 意为按适当比例混合，出自 temperare「混合、调节、节制」。"},{"era":"LATIN STRUCTURE","en":"Temperare is related to tempus 'time, season', because mixing in the right measure was imagined as keeping to the right season.","cn":"temperare 与 tempus「时间、季节」相关，因为「按正确比例混合」被想象为顺应正确的时令。"},{"era":"MEDIEVAL LATIN / EARLY ENGLISH (14c–15c)","en":"Medieval medicine used temperatura for the balanced mixture of humours in a body, and English borrowed it as temperature in this medical sense.","cn":"中世纪医学用 temperatura 指体内体液的有序混合，英语借入时也带这一医学义。"},{"era":"EARLY MODERN ENGLISH (17c)","en":"With the thermometer, the word shifted from a balance of qualities to a measurable degree of heat.","cn":"随着温度计的发明，这个词从「性质的平衡」转为「可测量的热度」。"},{"era":"MODERN ENGLISH (18c–19c)","en":"Physics fixed temperature as a quantity, and everyday speech kept the special phrase 'have a temperature' for fever.","cn":"物理学把 temperature 固定为一个物理量，日常口语则保留 have a temperature 这一说法指发烧。"},{"era":"MODERN ENGLISH (20c)","en":"Room temperature and body temperature became standard benchmarks in labs, kitchens and clinics.","cn":"室温与体温成为实验室、厨房与诊所的标准基准。"}]},"similar":{"note":{"en":"Group one separates the temperament words from the temperature word; group two holds related measures and sensations.","cn":"第一组分辨 temperament 词族与 temperature 的区别；第二组是相关度量与感觉词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"temperament","ipa":"/ˈtempərəmənt/","tag":"same family, different sense","definition":"A person's usual character; it comes from the same Latin root, where a balance of humours was thought to shape personality.","definitionCN":"一个人惯常的性格；出自同一拉丁词根，古人认为体液平衡塑造性格。"},{"word":"temper","ipa":"/ˈtempə/","tag":"same family, verb","definition":"To moderate or to become angry easily; the noun means a state of mind, not a degree of heat.","definitionCN":"使缓和，或指容易发怒；名词指心境，而不是热度。"},{"word":"temporal","ipa":"/ˈtempərəl/","tag":"unrelated","definition":"Relating to time or to the material world; it comes from tempus 'time', not from temperare.","definitionCN":"与时间或世俗世界有关；出自 tempus「时间」，而非 temperare。"}]},{"heading":"NEAR MEANING","entries":[{"word":"heat","ipa":"/hiːt/","tag":"energy, not reading","definition":"The energy transferred by a difference in temperature; heat is the cause, temperature is the measured result.","definitionCN":"因温差而传递的能量；热是原因，温度是被测出的结果。"},{"word":"fever","ipa":"/ˈfiːvə/","tag":"illness sign","definition":"A raised body temperature caused by illness; it names the condition, while a temperature is just the reading.","definitionCN":"疾病引起的体温升高；它指病况，而 temperature 只是读数。"},{"word":"reading","ipa":"/ˈriːdɪŋ/","tag":"instrument value","definition":"The figure shown by an instrument; a temperature is one kind of reading.","definitionCN":"仪器显示的数字；温度是读数的一种。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Latin family is real, and the measuring instruments are real compounds.","cn":"正常联想：拉丁词族真实存在，测量仪器也都是真实复合词。"},"normal":[{"en":"temperature and temperament share temperare: one measures the body's heat, the other names the body's mix of moods.","cn":"temperature 与 temperament 共享 temperare：一个测身体的热，一个指身体性情的混合。"},{"en":"thermometer = thermo- (heat) + -meter (measure), the instrument that reads a temperature.","cn":"thermometer = thermo-「热」+ -meter「测量」，读取温度的仪器。"},{"en":"thermostat = thermo- + -stat (standing, holding), a device that holds a set temperature.","cn":"thermostat = thermo- + -stat「保持」，把温度保持在设定值的装置。"},{"en":"room temperature is the standard phrase in recipes and lab protocols for ordinary indoor heat.","cn":"room temperature 是食谱与实验规程中表示通常室内温度的标准说法。"},{"en":"to have a temperature means to be feverish, because the number has gone above normal.","cn":"have a temperature 指发烧，因为那个数字高出了正常值。"}],"abstract":[{"en":"Abstractly, temperature is balance made countable: hot and cold are weighed against each other and turned into a number.","cn":"抽象地看，temperature 是可数的平衡：冷与热相互权衡，变成一个数字。"},{"en":"The same number can describe a room, a body, a gas or the mood of a meeting.","cn":"同一个数字可以描述房间、身体、气体，也可以描述一场会议的气氛。"},{"en":"So temperature is not heat itself but heat made comparable.","cn":"所以 temperature 不是热本身，而是变得可比较的热。"}]},"examples":[{"en":"The temperature fell below zero before dawn.","cn":"黎明前气温降到了零下。"},{"en":"Keep the oven at a constant temperature.","cn":"让烤箱保持恒温。"},{"en":"Her temperature returned to normal after two days.","cn":"两天后她的体温恢复正常。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「天不热」：天不热也有温度 → temperature 温度","word":"temperature"},"root":"拉丁语 temperatura「调和、适当混合」← temperare「混合、调节」，与 tempus「时间、季节」相关；十七世纪起经温度计的使用转为可测量的热度。","sensesIntro":{"en":"Eight senses follow one measurable balance: a room, a body, the weather, a fever, a thermostat setting, a social mood, a physical quantity and a standard benchmark.","cn":"八个义项沿着一个可测的平衡展开：房间、身体、天气、发烧、恒温设定、群体情绪、物理量，以及标准基准。"},"semanticMap":{"core":{"en":"CORE IMAGE: hot and cold weighed against each other and read off as a number.","cn":"核心意象：冷与热相互权衡，被读成一个数字。"},"chain":["MEASURED HEAT","BODY HEAT","WEATHER FIGURE","FEVER","SET POINT","SOCIAL CLIMATE"],"branches":[{"senses":"01 · 07","en":"MEASUREMENT: everyday heat and the physicist's quantity are the same number at two levels of precision.","cn":"测量：日常热度与物理学家的物理量，是同一数字的两种精度。"},{"senses":"02 · 04","en":"THE BODY: normal warmth and illness-heat are one scale read above and below the usual line.","cn":"身体：正常体温与病热，是同一条刻度在常线上下两侧的读数。"},{"senses":"03 · 08","en":"THE AIR: a forecast figure and a lab benchmark both describe ordinary surroundings.","cn":"空气：预报数字与实验室基准都在描述平常环境。"},{"senses":"05","en":"CONTROL: a dial turns the noun into a target to be reached.","cn":"控制：旋钮把这个名词变成一个要达到的目标。"},{"senses":"06","en":"MOOD: a room heated by anger borrows the same thermometer.","cn":"情绪：被愤怒加热的房间借用了同一支温度计。"}]},"affixes":{"intro":{"en":"Temperature belongs to the Latin temperare family. English adds -ature for the noun, while Greek thermo- supplies the instruments.","cn":"temperature 属于拉丁 temperare 词族。英语加 -ature 构成名词，希腊语 thermo- 则提供仪器名称。"},"latinIntro":{"en":"The Latin entries below are the recorded ancestors of the family; tempus 'time' is included because temperare was built on the idea of the right season.","cn":"下面的拉丁条目是该词族有记录的祖先；列出 tempus「时间」，因为 temperare 建立在「合宜时令」的观念上。"},"items":[{"word":"thermometer","structure":"Greek thermo- (heat) + -meter (measure)","meaning":"an instrument for reading temperature","meaningCN":"读取温度的仪器（thermo- 表示热，-meter 表示测量）","example":"The thermometer reads thirty-eight.","exampleCN":"温度计读数是三十八度。"},{"word":"thermostat","structure":"Greek thermo- + -stat (holding)","meaning":"a device that keeps a set temperature","meaningCN":"把温度保持在设定值的装置（-stat 表示保持）","example":"The thermostat switches the heater off.","exampleCN":"恒温器会关掉加热器。"},{"word":"temper","structure":"Latin temperare (mix, regulate)","meaning":"to moderate; also a state of mind","meaningCN":"使缓和；也指心境","example":"She tempered her criticism with praise.","exampleCN":"她用称赞来缓和批评。"},{"word":"temperate","structure":"temperare + -ate (adjective)","meaning":"mild in climate, or self-controlled","meaningCN":"气候温和的；有节制的","example":"The temperate zone has four seasons.","exampleCN":"温带四季分明。"},{"word":"temperament","structure":"Latin temperamentum (due mixture)","meaning":"a person's habitual character","meaningCN":"一个人惯常的性情","example":"He has a calm temperament.","exampleCN":"他性情沉稳。"},{"word":"temperature-controlled","structure":"temperature + controlled","meaning":"kept at a fixed heat by a device","meaningCN":"由设备保持恒温的","example":"The samples sit in a temperature-controlled room.","exampleCN":"样本放在恒温室里。"},{"word":"room temperature","structure":"room + temperature","meaning":"the ordinary indoor heat, used as a benchmark","meaningCN":"通常的室内温度，用作基准","example":"Serve the cheese at room temperature.","exampleCN":"奶酪在室温下上桌。"},{"word":"body temperature","structure":"body + temperature","meaning":"the internal heat of a living body","meaningCN":"活体的内部温度","example":"Body temperature is lowest before dawn.","exampleCN":"体温在黎明前最低。"}],"latinEntries":[{"word":"temperatura","structure":"temperare → temperatura","meaning":"a due mixture, tempering","meaningCN":"适当的混合；调和"},{"word":"temperare","structure":"related to tempus (time, season)","meaning":"to mix in due proportion, regulate","meaningCN":"按适当比例混合；调节"},{"word":"temperamentum","structure":"temperare + -mentum","meaning":"a balanced mixture, disposition","meaningCN":"平衡的混合；性情"},{"word":"tempus","structure":"root noun","meaning":"time, season","meaningCN":"时间；季节"}]}},{"word":"thermal","ipa_uk":"/ˈθɜːml/","ipa_us":"/ˈθɜːrml/","definition_zh":"热的；热量的；保温的；地热的；上升热气流","definition_en":"relating to heat or temperature, or designed to keep heat in","core_image":"温泉池面上腾起白色蒸汽，冷空气里那团暖意看得见","scene":"清晨，温泉池面腾起白色蒸汽，融进冷空气里。Steam rose from the thermal pool into the cold morning air.","sceneCN":"这里该词指「与热有关的、温热的」（第 1 个义项：热量的、热的）；句意为蒸汽从温热的池水中升起，融进清晨的冷空气。","pos":[{"tag":"adj.","zh":"热的；热量的；保温的；地热的"},{"tag":"n.","zh":"上升热气流；（复数）保暖内衣"}],"collocations":[{"phrase":"thermal energy","zh":"热能"},{"phrase":"thermal insulation","zh":"隔热；保温层"},{"phrase":"thermal spring","zh":"温泉"},{"phrase":"thermal power station","zh":"火力发电站"},{"phrase":"thermal imaging","zh":"热成像"},{"phrase":"thermal underwear","zh":"保暖内衣"}],"forms":[{"label":"复数（名词，保暖内衣）","form":"thermals"},{"label":"副词","form":"thermally"},{"label":"名词（热；热量）","form":"therm"},{"label":"名词（温度计）","form":"thermometer"},{"label":"名词（恒温器）","form":"thermostat"}],"derivatives":[{"word":"thermally","pos":"adv.","zh":"在热方面；热学上"},{"word":"therm","pos":"n.","zh":"热量单位；热"},{"word":"thermometer","pos":"n.","zh":"温度计"},{"word":"thermostat","pos":"n.","zh":"恒温器"},{"word":"geothermal","pos":"adj.","zh":"地热的"}],"senses":[{"no":"01","title":"Relating to heat","titleCN":"与热有关的","definition":"connected with heat or temperature","definitionCN":"与热或温度相关的","example":"Steam rose from the thermal pool into the cold morning air.","exampleCN":"蒸汽从温热的池水中升起，融进清晨的冷空气。","why":"Thermal is the adjective built on Greek thermē 'heat', so its base meaning is simply 'of heat'.","whyCN":"thermal 是建立在希腊语 thermē「热」之上的形容词，基本义就是「热的」。"},{"no":"02","title":"Naturally warm water","titleCN":"天然温热的水","definition":"of springs or pools, heated by the earth rather than by a machine","definitionCN":"指由地热而非机器加热的泉水或水池","example":"Bathers sat in the thermal water while snow fell.","exampleCN":"下雪时，泡温泉的人坐在温热的水里。","why":"Hot water heated from inside the earth is the most visible kind of heat, so the adjective attaches naturally to springs.","whyCN":"由地球内部加热的热水是最可见的热，因此这个形容词自然附着在泉水上。"},{"no":"03","title":"Clothing that holds body heat","titleCN":"保住体温的衣物","definition":"designed to trap the warmth a body produces","definitionCN":"设计用来留住身体产生的热量","example":"She wore thermal gloves under the outer pair.","exampleCN":"她在外层手套里又戴了一副保暖手套。","why":"The word moves from the heat itself to a material whose job is to keep that heat from leaving.","whyCN":"这个词从热本身转到一种材料，其职责是不让热跑掉。"},{"no":"04","title":"A rising column of warm air","titleCN":"上升的暖空气柱","definition":"in meteorology and gliding, a warm updraught that lifts aircraft","definitionCN":"气象与滑翔中把飞行器托起的上升暖气流","example":"The glider circled in a thermal above the ridge.","exampleCN":"滑翔机在山脊上空的上升热气流里盘旋。","why":"Warm air is lighter than cold air, so a patch of heated ground sends a column upward; fliers call that column a thermal.","whyCN":"暖空气比冷空气轻，被加热的地面会送出上升气柱；飞行者把这股气柱叫作 thermal。"},{"no":"05","title":"Geothermal power","titleCN":"地热发电","definition":"electricity generated from heat inside the earth","definitionCN":"利用地球内部的热发出的电","example":"The island runs on thermal power from its volcanoes.","exampleCN":"这座岛靠火山的地热发电运行。","why":"Industry turns the natural heat into a resource, and the adjective names the source rather than the warmth.","whyCN":"工业把自然的热变成资源，这个形容词命名的是来源而非暖意。"},{"no":"06","title":"Infrared imaging","titleCN":"热成像","definition":"using emitted heat to form a visible image","definitionCN":"利用物体发出的热形成可见图像","example":"The thermal camera found the leak behind the wall.","exampleCN":"热成像相机找到了墙后的漏点。","why":"Every object above absolute zero emits heat radiation, so a sensor can draw a picture of temperature.","whyCN":"任何高于绝对零度的物体都会发出热辐射，传感器因此能画出温度的图像。"},{"no":"07","title":"A physics property","titleCN":"热学性质","definition":"in physics, relating to heat transfer, capacity or expansion","definitionCN":"物理学中与传热、热容或热膨胀相关的","example":"Thermal expansion cracked the rail in the heat.","exampleCN":"高温下热膨胀使铁轨裂开。","why":"The adjective supplies the technical label for every quantity involving heat.","whyCN":"这个形容词为每一个涉及热的量提供技术标签。"},{"no":"08","title":"Comfort in a building","titleCN":"建筑中的热舒适","definition":"in architecture, related to the heat balance that keeps occupants comfortable","definitionCN":"建筑学中与维持使用者舒适的热平衡有关","example":"Thermal mass keeps the house cool during the day.","exampleCN":"热质量让房子在白天保持凉爽。","why":"Buildings manage heat flows, so the word becomes a design category rather than a weather word.","whyCN":"建筑要管理热流，于是这个词成了设计类别，而不是天气词。"}],"etymology":{"intro":{"en":"Thermal comes from Greek thermē 'heat', passed into scientific Latin. The Greek root is well attested; its PIE origin is a reconstruction. Dates are approximate.","cn":"thermal 出自希腊语 thermē「热」，经科学拉丁语传入。希腊词根有充分记录；其原始印欧语来源属重构。年代为大致估计。"},"items":[{"era":"ANCIENT GREEK","en":"Greek thermē meant 'heat', and thermos meant 'hot'; the family included thermainō 'to warm'.","cn":"希腊语 thermē 意为「热」，thermos 意为「热的」；同族还有 thermainō「加热」。"},{"era":"ANCIENT GREEK (place word)","en":"Greek thermai, literally 'hot springs', was used as the name of towns built around warm baths.","cn":"希腊语 thermai 字面义为「温泉」，曾被用作建在温水浴场旁的城镇名称。"},{"era":"CLASSICAL LATIN","en":"Latin borrowed thermae for hot baths and thermal baths, the source of the English word thermae.","cn":"拉丁语借入 thermae，指温泉浴场与温水浴，是英语 thermae 的来源。"},{"era":"PROTO-INDO-EUROPEAN (reconstructed)","en":"The Greek root is usually traced to PIE *gwher- 'to be hot, to warm', which also lies behind Latin formus 'warm' and English warm.","cn":"希腊词根通常被追溯到原始印欧语 *gwher-「热、加热」，拉丁语 formus「温暖的」与英语 warm 也出自此。"},{"era":"SCIENTIFIC LATIN (17c–18c)","en":"Modern science coined thermalis as an adjective for heat, and English adopted thermal for heat-related quantities and instruments.","cn":"近代科学造出形容词 thermalis 表示热的，英语借用 thermal 表示与热有关的量与仪器。"},{"era":"MODERN ENGLISH (19c–20c)","en":"Geothermal power, thermal imaging and thermal clothing extended the word into engineering and everyday goods.","cn":"地热发电、热成像与保暖衣物把这个词扩展到工程与日常商品。"}]},"similar":{"note":{"en":"Group one holds words that look like thermal but belong elsewhere; group two holds heat-related adjectives.","cn":"第一组是字形像 thermal 但属于其他词族的词；第二组是与热有关的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"terminal","ipa":"/ˈtɜːmɪnl/","tag":"unrelated","definition":"An end point, a computer screen, or a fatal illness; it comes from Latin terminus 'boundary', not from heat.","definitionCN":"终点、计算机终端或绝症；出自拉丁语 terminus「边界」，与热无关。"},{"word":"theorem","ipa":"/θɪˈriːm/","tag":"near spelling","definition":"A proved mathematical statement; the root is Greek theorein 'to look at', not thermē 'heat'.","definitionCN":"经证明的数学命题；词根是希腊语 theorein「观看」，而非 thermē「热」。"},{"word":"theme","ipa":"/θiːm/","tag":"near sound","definition":"The central subject of a work; it shares the beginning th- but comes from Greek thema 'something placed'.","definitionCN":"作品的中心主题；只共享开头 th-，出自希腊语 thema「放置之物」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"geothermal","ipa":"/ˌdʒiːəʊˈθɜːml/","tag":"earth heat","definition":"Relating to heat from inside the earth; it is thermal narrowed to one source.","definitionCN":"与地球内部的热有关；它是 thermal 收窄到一种来源。"},{"word":"insulated","ipa":"/ɪnˈsjʊleɪtɪd/","tag":"heat kept in","definition":"Protected so that heat cannot easily pass in or out; thermal clothing is insulated clothing.","definitionCN":"受保护使热不易进出；保暖衣物就是隔热衣物。"},{"word":"warm","ipa":"/wɔːm/","tag":"plain sensation","definition":"Mildly hot to the touch; it is the everyday sensation, while thermal is the technical adjective.","definitionCN":"摸上去温热；它是日常感觉，而 thermal 是技术形容词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Greek root is real, and every compound below is an existing English word.","cn":"正常联想：希腊词根真实存在，下面每个复合词都是现有的英语词。"},"normal":[{"en":"thermo- is the combining form of heat: thermometer, thermostat and thermos all begin with it.","cn":"thermo- 是「热」的组合形式：thermometer、thermostat、thermos 都以它开头。"},{"en":"thermal + -ly = thermally, the adverb used in physics for heat-related processes.","cn":"thermal + -ly = thermally，物理学中表示与热有关过程的副词。"},{"en":"geothermal = geo- (earth) + thermal, heat that comes from the ground.","cn":"geothermal = geo-「地球」+ thermal，来自地下的热。"},{"en":"thermal mass is a real building term for materials that store heat and release it later.","cn":"thermal mass 是建筑学真实术语，指储存热量并稍后释放的材料。"},{"en":"thermals as a plural noun means thermal underwear, because the garments are defined by the heat they keep.","cn":"thermals 作复数名词指保暖内衣，因为这类衣物以「保住热」来定义。"}],"abstract":[{"en":"Abstractly, thermal marks the direction heat takes: from hot to cold, from the earth to a pool, from a body to the air.","cn":"抽象地看，thermal 标记热的走向：从热到冷，从地下到水池，从身体到空气。"},{"en":"The same label can describe a bath, a glove, a rising column, a power plant or a camera image.","cn":"同一个标签可以描述浴场、手套、上升气柱、发电厂或相机图像。"},{"en":"So thermal is not 'hot' but 'having to do with heat' — a relation rather than a feeling.","cn":"所以 thermal 不是「热的」，而是「与热有关的」——是一种关系，而不是一种感觉。"}]},"examples":[{"en":"The engineers measured the thermal conductivity of the new panel.","cn":"工程师测量了新板材的导热率。"},{"en":"Thermal springs feed the baths below the temple.","cn":"温泉供给神庙下方的浴池。"},{"en":"The drone's thermal sensor spotted the lost hiker at night.","cn":"无人机的热传感器在夜间发现了失踪的徒步者。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音「热猫」：猫身上热乎乎的 → thermal 热的、保温的","word":"thermal"},"root":"希腊语 thermē「热」、thermos「热的」，经拉丁语 thermae「温泉浴场」与科学拉丁语 thermalis 进入英语；更早重构为原始印欧语 *gwher-「热、加热」。","sensesIntro":{"en":"Eight senses follow one relation to heat: the general adjective, warm springs, insulating clothes, rising air, earth power, infrared pictures, physical quantities and building comfort.","cn":"八个义项沿着同一种「与热的关系」展开：一般形容词、温水泉、保温衣物、上升气流、地热电力、红外图像、物理量，以及建筑热舒适。"},"semanticMap":{"core":{"en":"CORE IMAGE: heat as a direction that can be traced, stored, blocked or turned into a picture.","cn":"核心意象：热是一条可被追踪、储存、阻挡或成像的流向。"},"chain":["HEAT ITSELF","WARM WATER","TRAPPED WARMTH","RISING AIR","EARTH POWER","HEAT IMAGE"],"branches":[{"senses":"01 · 07","en":"THE GENERAL LABEL: everyday heat and physics quantities share one adjective.","cn":"一般标签：日常热与物理量共用一个形容词。"},{"senses":"02 · 05","en":"HEAT FROM BELOW: a warm spring and a geothermal plant both draw on the earth.","cn":"来自地下的热：温泉与地热电厂都在利用地球。"},{"senses":"03 · 08","en":"HEAT KEPT OR MANAGED: clothing traps it, and buildings store it.","cn":"留住或管理热：衣物把它困住，建筑把它储存。"},{"senses":"04","en":"HEAT THAT MOVES: a column of warm air lifts a glider.","cn":"移动的热：一股暖空气把滑翔机托起。"},{"senses":"06","en":"HEAT MADE VISIBLE: a sensor draws temperature as a picture.","cn":"变得可见的热：传感器把温度画成图像。"}]},"affixes":{"intro":{"en":"Thermal is built on Greek thermo- 'heat'. English compounds then add -meter, -stat, geo- and imaging words, all of which are transparent.","cn":"thermal 建立在希腊语 thermo-「热」之上。英语复合词随后加入 -meter、-stat、geo- 与成像类词，构词都很透明。"},"latinIntro":{"en":"The route into English runs through Latin thermae 'hot baths' and scientific Latin thermalis. The entries below are the recorded Latin forms.","cn":"进入英语的路径经过拉丁语 thermae「温泉浴场」与科学拉丁语 thermalis。下面的条目是有记录的拉丁形式。"},"items":[{"word":"thermometer","structure":"thermo- (heat) + -meter (measure)","meaning":"an instrument for measuring temperature","meaningCN":"测量温度的仪器（thermo- 热，-meter 测量）","example":"The thermometer broke in the cold.","exampleCN":"温度计在寒冷中碎了。"},{"word":"thermostat","structure":"thermo- + -stat (holding)","meaning":"a device that holds a set temperature","meaningCN":"保持设定温度的装置（-stat 表示保持）","example":"Set the thermostat to twenty degrees.","exampleCN":"把恒温器设在二十度。"},{"word":"thermos","structure":"Greek thermos (hot), originally a trade name","meaning":"an insulated flask that keeps drinks hot or cold","meaningCN":"保温瓶（源自希腊语 thermos「热的」，原为商标名）","example":"The thermos kept the tea hot all day.","exampleCN":"保温瓶让茶一整天都是热的。"},{"word":"geothermal","structure":"geo- (earth) + thermal","meaning":"using heat from inside the earth","meaningCN":"利用地球内部的热的（geo- 表示地球）","example":"Geothermal heat warms the greenhouse.","exampleCN":"地热为温室供暖。"},{"word":"thermal imaging","structure":"thermal + imaging","meaning":"making a picture from emitted heat","meaningCN":"利用发出的热成像","example":"Thermal imaging revealed the faulty wiring.","exampleCN":"热成像暴露了故障线路。"},{"word":"thermal mass","structure":"thermal + mass","meaning":"the ability of a material to store heat","meaningCN":"材料储存热量的能力，即热质量","example":"Stone walls add thermal mass to the house.","exampleCN":"石墙为房子增加了热质量。"},{"word":"thermal underwear","structure":"thermal + underwear","meaning":"close-fitting garments that keep body heat in","meaningCN":"保住体温的贴身衣物，即保暖内衣","example":"He packed thermal underwear for the trip.","exampleCN":"他为旅行带了保暖内衣。"},{"word":"thermic","structure":"therm- + -ic (relating to)","meaning":"relating to heat, especially in physiology","meaningCN":"与热有关的，尤用于生理学（-ic 表示「与……有关」）","example":"Thermic effect refers to energy used in digestion.","exampleCN":"食物热效应指消化所消耗的能量。"}],"latinEntries":[{"word":"thermae","structure":"Greek thermai → Latin thermae","meaning":"hot baths, warm springs","meaningCN":"温泉浴场；温水浴"},{"word":"thermalis","structure":"Greek thermē → scientific Latin thermalis","meaning":"relating to heat","meaningCN":"与热有关的"},{"word":"formus","structure":"Latin adjective, PIE *gwher-","meaning":"warm","meaningCN":"温暖的"}]}}]);
